import React, { useState, useMemo, useRef } from 'react';
import { User, UserRole, Shift, Sale } from '../types';
import { 
  UserCircle, 
  Lock, 
  MapPin, 
  Briefcase, 
  Shield, 
  Save, 
  CheckCircle, 
  AlertCircle,
  Clock,
  TrendingUp,
  Calendar,
  BarChart4,
  DollarSign,
  ShoppingBag,
  Camera,
  Image as ImageIcon,
  Mail,
  Smartphone,
  Hash,
  Globe,
  Bell,
  LogOut
} from 'lucide-react';
import { 
  AreaChart, 
  Area, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  BarChart, 
  Bar,
  PieChart,
  Pie,
  Cell
} from 'recharts';
import { useGlobal } from '../context/GlobalContext';
import { verifyPasswordSync, hashPasswordSync } from '../lib/auth';

interface UserProfileProps {
  user: User;
  shifts: Shift[];
  sales: Sale[];
}

type TimeRange = 'week' | 'month' | 'quarter' | 'year' | 'all';

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8'];

export const UserProfile: React.FC<UserProfileProps> = ({ user, shifts, sales }) => {
  const { updateUser, branches, formatPrice, settings } = useGlobal();
  const [activeTab, setActiveTab] = useState<'overview' | 'performance' | 'security' | 'settings'>('overview');

  // Image Upload Refs
  const fileInputRef = useRef<HTMLInputElement>(null);
  const coverInputRef = useRef<HTMLInputElement>(null);

  // Performance State
  const [timeRange, setTimeRange] = useState<TimeRange>('month');

  // Password Form State
  const [passForm, setPassForm] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [status, setStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);

  // General Stats (All Time)
  const myShifts = useMemo(() => shifts.filter(s => s.userId === user.id).sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime()), [shifts, user.id]);
  const mySales = useMemo(() => sales.filter(s => s.userId === user.id && s.status !== 'voided'), [sales, user.id]);
  const totalSalesValue = mySales.reduce((acc, s) => acc + s.total, 0);
  const branchName = branches.find(b => b.id === user.branchId)?.name || 'Unassigned';

  // --- Image Handlers ---
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 2 * 1024 * 1024) { // 2MB Limit
      alert('File size too large. Please select an image under 2MB.');
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      // Update user with new avatar immediately
      updateUser({ ...user, avatarUrl: reader.result as string });
    };
    reader.readAsDataURL(file);
  };

  const handleCoverUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 3 * 1024 * 1024) { // 3MB Limit for cover
      alert('File size too large. Please select an image under 3MB.');
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      // Update user with new cover immediately
      updateUser({ ...user, coverUrl: reader.result as string });
    };
    reader.readAsDataURL(file);
  };

  // --- Performance Logic ---
  const performanceData = useMemo(() => {
    const now = new Date();
    let startDate = new Date();
    let groupBy: 'day' | 'month' = 'day';

    // 1. Determine Start Date & Grouping
    switch (timeRange) {
      case 'week':
        startDate.setDate(now.getDate() - 7);
        groupBy = 'day';
        break;
      case 'month':
        startDate.setMonth(now.getMonth() - 1);
        groupBy = 'day';
        break;
      case 'quarter':
        startDate.setMonth(now.getMonth() - 3);
        groupBy = 'day'; 
        break;
      case 'year':
        startDate.setFullYear(now.getFullYear() - 1);
        groupBy = 'month';
        break;
      case 'all':
        startDate = new Date(0); // Beginning of time
        groupBy = 'month';
        break;
    }

    // 2. Filter Sales
    const filteredSales = mySales.filter(s => new Date(s.date) >= startDate);

    // 3. Aggregate Data
    const groupedData = new Map<string, { date: string; sortKey: number; revenue: number; count: number }>();
    const paymentMethods: Record<string, number> = {};

    filteredSales.forEach(sale => {
       const d = new Date(sale.date);
       let key = '';
       let sortKey = 0;

       if (groupBy === 'month') {
          key = d.toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
          sortKey = d.getFullYear() * 100 + d.getMonth();
       } else {
          key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
          sortKey = d.getTime();
       }

       const existing = groupedData.get(key) || { date: key, sortKey, revenue: 0, count: 0 };
       existing.revenue += sale.total;
       existing.count += 1;
       groupedData.set(key, existing);

       // Payment Stats
       const method = sale.paymentMethod || 'cash';
       paymentMethods[method] = (paymentMethods[method] || 0) + sale.total;
    });

    const chartData = Array.from(groupedData.values()).sort((a, b) => a.sortKey - b.sortKey);
    const periodRevenue = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const periodOrders = filteredSales.length;
    const periodAvg = periodOrders > 0 ? periodRevenue / periodOrders : 0;

    const paymentChartData = Object.entries(paymentMethods).map(([name, value]) => ({ name, value }));

    return { chartData, periodRevenue, periodOrders, periodAvg, paymentChartData };
  }, [mySales, timeRange]);

  const handlePasswordChange = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus({ type: 'idle', message: '' });

    if (passForm.newPassword !== passForm.confirmPassword) {
      setStatus({ type: 'error', message: 'New passwords do not match' });
      return;
    }

    if (passForm.newPassword.length < 6) {
      setStatus({ type: 'error', message: 'Password must be at least 6 characters' });
      return;
    }

    setIsSubmitting(true);

    try {
      const res = await fetch('/api/auth/change-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: user.id,
          currentPassword: passForm.currentPassword,
          newPassword: passForm.newPassword
        })
      });

      if (res.ok) {
        setStatus({ type: 'success', message: 'Password changed successfully' });
        setPassForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
      } else {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || 'API Failed');
      }
    } catch (err) {
      console.warn("API Error, attempting local update:", err);
      try {
         const isValid = verifyPasswordSync(passForm.currentPassword, user.password || '');
         if (isValid) {
            const newHash = hashPasswordSync(passForm.newPassword);
            updateUser({ ...user, password: newHash });
            setStatus({ type: 'success', message: 'Password updated (Local Mode)' });
            setPassForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
         } else {
            setStatus({ type: 'error', message: 'Incorrect current password' });
         }
      } catch (localErr) {
         setStatus({ type: 'error', message: 'Failed to update password' });
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  const getRoleBadgeColor = (role: string) => {
    switch(role) {
      case 'Admin': return 'bg-purple-100 text-purple-700 border-purple-200';
      case 'Manager': return 'bg-indigo-100 text-indigo-700 border-indigo-200';
      case 'Staff': return 'bg-blue-100 text-blue-700 border-blue-200';
      default: return 'bg-green-100 text-green-700 border-green-200';
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-20">
      {/* --- HERO BANNER --- */}
      <div className="relative rounded-3xl overflow-hidden bg-white shadow-sm border border-slate-200 group">
        {/* Cover Image */}
        <div className="h-48 md:h-64 bg-gradient-to-r from-slate-800 to-slate-900 relative">
           {user.coverUrl ? (
              <img src={user.coverUrl} alt="Cover" className="w-full h-full object-cover" />
           ) : (
              <div className="w-full h-full bg-[url('https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&q=80&w=2000')] bg-cover bg-center opacity-40 mix-blend-overlay"></div>
           )}
           <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent"></div>

           <button 
              onClick={() => coverInputRef.current?.click()}
              className="absolute top-4 right-4 p-2 bg-black/30 hover:bg-black/50 text-white rounded-xl backdrop-blur-md transition-all opacity-0 group-hover:opacity-100 flex items-center text-sm font-medium"
           >
              <Camera className="w-4 h-4 mr-2" /> Change Cover
           </button>
           <input type="file" ref={coverInputRef} className="hidden" accept="image/*" onChange={handleCoverUpload} />
        </div>

        {/* Profile Stats Bar */}
        <div className="h-20 md:h-24 bg-white flex justify-end items-center px-8">
           <div className="flex space-x-8 text-center hidden md:flex">
              <div>
                 <p className="text-xs text-slate-400 uppercase font-bold tracking-wider">Shifts</p>
                 <p className="text-xl font-bold text-slate-800">{myShifts.length}</p>
              </div>
              <div>
                 <p className="text-xs text-slate-400 uppercase font-bold tracking-wider">Orders</p>
                 <p className="text-xl font-bold text-slate-800">{mySales.length}</p>
              </div>
              <div>
                 <p className="text-xs text-slate-400 uppercase font-bold tracking-wider">Revenue</p>
                 <p className="text-xl font-bold text-green-600">{formatPrice(totalSalesValue)}</p>
              </div>
           </div>
        </div>

        {/* Floating Avatar & Info */}
        <div className="absolute top-32 md:top-40 left-6 md:left-10 flex items-end">
           <div className="relative group/avatar">
              <div className="w-32 h-32 md:w-40 md:h-40 rounded-full border-4 border-white bg-slate-100 shadow-xl overflow-hidden flex items-center justify-center cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                 {user.avatarUrl ? (
                    <img src={user.avatarUrl} alt={user.name} className="w-full h-full object-cover" />
                 ) : (
                    <UserCircle className="w-20 h-20 text-slate-300" />
                 )}
                 <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover/avatar:opacity-100 transition-opacity">
                    <Camera className="w-8 h-8 text-white" />
                 </div>
              </div>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
              <div className="absolute bottom-2 right-2 w-6 h-6 bg-green-500 border-2 border-white rounded-full" title="Active"></div>
           </div>

           <div className="mb-4 ml-4 md:mb-6">
              <h1 className="text-2xl md:text-3xl font-bold text-white drop-shadow-md">{user.name}</h1>
              <div className="flex items-center space-x-2 mt-1">
                 <span className={`px-2.5 py-0.5 rounded-full text-xs font-bold border uppercase tracking-wide backdrop-blur-md shadow-sm ${getRoleBadgeColor(user.role)} bg-opacity-90`}>
                    {user.role}
                 </span>
                 <span className="text-slate-200 text-sm font-medium flex items-center drop-shadow-sm">
                    <MapPin className="w-3.5 h-3.5 mr-1" /> {branchName}
                 </span>
              </div>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* LEFT COLUMN: Identity & Info */}
        <div className="space-y-6">
           <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
              <h3 className="font-bold text-slate-800 mb-4 flex items-center">
                 <Briefcase className="w-5 h-5 mr-2 text-slate-500" /> Professional Details
              </h3>
              <div className="space-y-4">
                 <div className="flex justify-between items-center py-2 border-b border-slate-50">
                    <span className="text-sm text-slate-500 flex items-center"><Hash className="w-4 h-4 mr-2"/> Employee ID</span>
                    <span className="text-sm font-mono font-bold text-slate-700 bg-slate-100 px-2 py-0.5 rounded">{user.id.slice(0,8)}</span>
                 </div>
                 <div className="flex justify-between items-center py-2 border-b border-slate-50">
                    <span className="text-sm text-slate-500 flex items-center"><UserCircle className="w-4 h-4 mr-2"/> Username</span>
                    <span className="text-sm font-bold text-slate-700">{user.username}</span>
                 </div>
                 <div className="flex justify-between items-center py-2 border-b border-slate-50">
                    <span className="text-sm text-slate-500 flex items-center"><Shield className="w-4 h-4 mr-2"/> Department</span>
                    <span className="text-sm font-medium text-slate-700">{user.department || 'General'}</span>
                 </div>
              </div>
           </div>

           <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
              <h3 className="font-bold text-slate-800 mb-4 flex items-center">
                 <Mail className="w-5 h-5 mr-2 text-slate-500" /> Contact Info
              </h3>
              <div className="space-y-4">
                 <div className="flex items-start">
                    <Mail className="w-4 h-4 text-slate-400 mt-1 mr-3" />
                    <div>
                       <p className="text-xs text-slate-400 uppercase font-bold">Email Address</p>
                       <p className="text-sm font-medium text-slate-700">{user.email || 'No email provided'}</p>
                    </div>
                 </div>
                 <div className="flex items-start">
                    <Smartphone className="w-4 h-4 text-slate-400 mt-1 mr-3" />
                    <div>
                       <p className="text-xs text-slate-400 uppercase font-bold">Phone Number</p>
                       <p className="text-sm font-medium text-slate-700">Not Linked</p>
                    </div>
                 </div>
              </div>
           </div>
        </div>

        {/* RIGHT COLUMN: Tabs & Content */}
        <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-200 flex flex-col min-h-[500px]">
           {/* Tab Navigation */}
           <div className="flex border-b border-slate-100 overflow-x-auto">
              {[
                 { id: 'overview', label: 'Overview', icon: BarChart4 },
                 { id: 'performance', label: 'Performance', icon: TrendingUp },
                 { id: 'security', label: 'Security', icon: Lock },
                 { id: 'settings', label: 'Preferences', icon: Globe },
              ].map(tab => {
                 const Icon = tab.icon;
                 return (
                    <button 
                       key={tab.id}
                       onClick={() => setActiveTab(tab.id as any)}
                       className={`flex items-center px-6 py-4 text-sm font-bold transition-all whitespace-nowrap border-b-2 ${
                          activeTab === tab.id 
                             ? 'border-orange-500 text-orange-600 bg-orange-50/20' 
                             : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'
                       }`}
                    >
                       <Icon className="w-4 h-4 mr-2" />
                       {tab.label}
                    </button>
                 )
              })}
           </div>

           <div className="p-6 md:p-8 flex-1">
              {activeTab === 'overview' && (
                 <div className="space-y-8 animate-fade-in">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                       <div className="bg-gradient-to-br from-blue-50 to-white p-5 rounded-xl border border-blue-100 shadow-sm">
                          <div className="flex justify-between items-start">
                             <div>
                                <p className="text-xs text-blue-600 font-bold uppercase tracking-wider mb-1">Total Sales</p>
                                <h3 className="text-2xl font-bold text-slate-800">{formatPrice(totalSalesValue)}</h3>
                             </div>
                             <div className="p-2 bg-white rounded-lg shadow-sm">
                                <DollarSign className="w-5 h-5 text-blue-500" />
                             </div>
                          </div>
                       </div>
                       <div className="bg-gradient-to-br from-orange-50 to-white p-5 rounded-xl border border-orange-100 shadow-sm">
                          <div className="flex justify-between items-start">
                             <div>
                                <p className="text-xs text-orange-600 font-bold uppercase tracking-wider mb-1">Shifts Completed</p>
                                <h3 className="text-2xl font-bold text-slate-800">{myShifts.filter(s => s.status === 'Closed').length}</h3>
                             </div>
                             <div className="p-2 bg-white rounded-lg shadow-sm">
                                <Clock className="w-5 h-5 text-orange-500" />
                             </div>
                          </div>
                       </div>
                    </div>

                    <div>
                       <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
                          <Clock className="w-5 h-5 mr-2 text-slate-400" /> Recent Activity
                       </h3>
                       {myShifts.length === 0 ? (
                          <div className="text-center py-12 bg-slate-50 rounded-xl border border-dashed border-slate-200">
                             <p className="text-slate-400 italic">No recent shifts found.</p>
                          </div>
                       ) : (
                          <div className="relative border-l-2 border-slate-100 ml-3 space-y-6 pl-6 pb-2">
                             {myShifts.slice(0, 5).map((shift, idx) => (
                                <div key={shift.id} className="relative">
                                   <div className={`absolute -left-[31px] top-1 w-4 h-4 rounded-full border-2 border-white shadow-sm ${shift.status === 'Open' ? 'bg-green-500' : 'bg-slate-300'}`}></div>
                                   <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow">
                                      <div className="flex justify-between items-start">
                                         <div>
                                            <p className="font-bold text-slate-800 text-sm">
                                               {shift.status === 'Open' ? 'Currently On Shift' : 'Completed Shift'}
                                            </p>
                                            <p className="text-xs text-slate-500 mt-1">
                                               {new Date(shift.startTime).toLocaleDateString()} • {new Date(shift.startTime).toLocaleTimeString()}
                                            </p>
                                         </div>
                                         {shift.endCash && (
                                            <span className="bg-slate-100 text-slate-600 px-2 py-1 rounded text-xs font-mono font-bold">
                                               {formatPrice(shift.endCash)}
                                            </span>
                                         )}
                                      </div>
                                   </div>
                                </div>
                             ))}
                          </div>
                       )}
                    </div>
                 </div>
              )}

              {activeTab === 'performance' && (
                 <div className="space-y-6 animate-fade-in">
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                       <h3 className="text-lg font-bold text-slate-800">Sales Analytics</h3>
                       <div className="flex bg-slate-100 p-1 rounded-lg overflow-x-auto">
                          {(['week', 'month', 'year'] as const).map(p => (
                             <button
                                key={p}
                                onClick={() => setTimeRange(p)}
                                className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all capitalize ${
                                   timeRange === p ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                                }`}
                             >
                                {p}
                             </button>
                          ))}
                       </div>
                    </div>

                    <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm h-[300px]">
                       <ResponsiveContainer width="100%" height="100%">
                          <AreaChart data={performanceData.chartData}>
                             <defs>
                                <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                                   <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                                   <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                                </linearGradient>
                             </defs>
                             <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                             <XAxis dataKey="date" stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} />
                             <YAxis stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} tickFormatter={(val) => `${val/1000}k`} />
                             <Tooltip 
                                contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0' }}
                                formatter={(val: number) => formatPrice(val)}
                             />
                             <Area type="monotone" dataKey="revenue" stroke="#3b82f6" strokeWidth={2} fillOpacity={1} fill="url(#colorRev)" />
                          </AreaChart>
                       </ResponsiveContainer>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                       <div className="bg-slate-50 p-6 rounded-xl border border-slate-200">
                          <h4 className="font-bold text-slate-700 mb-4 text-sm">Payment Methods</h4>
                          <div className="h-48">
                             <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                   <Pie
                                      data={performanceData.paymentChartData}
                                      cx="50%"
                                      cy="50%"
                                      innerRadius={40}
                                      outerRadius={60}
                                      paddingAngle={5}
                                      dataKey="value"
                                   >
                                      {performanceData.paymentChartData.map((entry, index) => (
                                         <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                      ))}
                                   </Pie>
                                   <Tooltip formatter={(val: number) => formatPrice(val)} />
                                </PieChart>
                             </ResponsiveContainer>
                          </div>
                          <div className="flex flex-wrap justify-center gap-3 mt-2">
                             {performanceData.paymentChartData.map((entry, index) => (
                                <div key={index} className="flex items-center text-xs text-slate-600">
                                   <div className="w-2 h-2 rounded-full mr-1" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                                   <span className="capitalize">{entry.name}</span>
                                </div>
                             ))}
                          </div>
                       </div>

                       <div className="bg-slate-50 p-6 rounded-xl border border-slate-200">
                          <h4 className="font-bold text-slate-700 mb-4 text-sm">Period Summary</h4>
                          <div className="space-y-4">
                             <div className="flex justify-between items-center pb-3 border-b border-slate-200">
                                <span className="text-sm text-slate-500">Total Revenue</span>
                                <span className="font-bold text-slate-800">{formatPrice(performanceData.periodRevenue)}</span>
                             </div>
                             <div className="flex justify-between items-center pb-3 border-b border-slate-200">
                                <span className="text-sm text-slate-500">Total Orders</span>
                                <span className="font-bold text-slate-800">{performanceData.periodOrders}</span>
                             </div>
                             <div className="flex justify-between items-center">
                                <span className="text-sm text-slate-500">Avg. Ticket Size</span>
                                <span className="font-bold text-green-600">{formatPrice(performanceData.periodAvg)}</span>
                             </div>
                          </div>
                       </div>
                    </div>
                 </div>
              )}

              {activeTab === 'security' && (
                 <div className="max-w-lg mx-auto animate-fade-in">
                    <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-200 mb-8 flex items-start">
                       <Shield className="w-5 h-5 text-yellow-600 mr-3 mt-0.5" />
                       <div>
                          <h4 className="font-bold text-yellow-800 text-sm">Security Recommendations</h4>
                          <ul className="text-xs text-yellow-700 mt-2 space-y-1 list-disc list-inside">
                             <li>Use a strong password with at least 8 characters.</li>
                             <li>Include numbers and symbols.</li>
                             <li>Do not share your account credentials.</li>
                          </ul>
                       </div>
                    </div>

                    <form onSubmit={handlePasswordChange} className="space-y-5">
                       <div>
                          <label className="block text-sm font-bold text-slate-700 mb-1.5">Current Password</label>
                          <div className="relative group">
