import { Product, CartItem, Category, EstimateResultItem, SystemSettings, Customer, Sale } from '../types';
import { 
  Search, ShoppingCart, Plus, Minus, Trash2, CreditCard, Banknote, Sparkles, Box, 
  ArrowLeft, ScanBarcode, User, X, Percent, Star, QrCode, CheckCircle, FileText,
  Monitor, Tag, Gift, PauseCircle, ClipboardList, RefreshCw, ChevronLeft, Printer
} from 'lucide-react';
import { AiAssistant } from './AiAssistant';
import { BarcodeScanner } from './BarcodeScanner';
import { useGlobal } from '../context/GlobalContext';
import { useCartStore } from '../store/useCartStore';

interface PosTerminalProps {
  products: Product[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number
  ) => Promise<Sale>;
  settings?: SystemSettings;
}

export const PosTerminal: React.FC<PosTerminalProps> = ({ products, onProcessSale, settings }) => {
  const { customers, customerLevels, t, promotions, branches, warehouses, currentUser, formatPrice } = useGlobal();
  const { 
    cart, addToCart, removeFromCart, updateQuantity, setQuantity, clearCart,
    heldOrders, holdCurrentOrder, recallOrder, discardHeldOrder
  } = useCartStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false); 

  // Discount State
  const [manualDiscount, setManualDiscount] = useState<{ type: 'percent' | 'fixed', value: number } | null>(null);
  const [isDiscountModalOpen, setIsDiscountModalOpen] = useState(false);

  // Loyalty State
  const [redeemPoints, setRedeemPoints] = useState<number>(0);

  // Checkout & Payment State
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'qr' | 'credit'>('cash');
  const [receivedAmountStr, setReceivedAmountStr] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  // Mobile UX State for Checkout ('method' = Select Payment Type, 'detail' = Enter Amount)
  const [checkoutStep, setCheckoutStep] = useState<'method' | 'detail'>('method');

  // Receipt State
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);

  // Customer & Recall State
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [customerSearch, setCustomerSearch] = useState('');
  const [isRecallModalOpen, setIsRecallModalOpen] = useState(false);

  // --- Calculations ---
  const customerLevel = useMemo(() => {
    if (!selectedCustomer?.levelId) return null;
    return customerLevels.find(l => l.id === selectedCustomer.levelId);
  }, [selectedCustomer, customerLevels]);

  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);

  // 1. Apply Discounts
  const customerDiscountPercent = customerLevel?.discountPercentage || 0;
  const customerDiscountAmount = customerDiscountPercent > 0 
    ? rawSubtotal * (customerDiscountPercent / 100) 
    : 0;

  let manualDiscountAmount = 0;
  if (manualDiscount) {
    if (manualDiscount.type === 'percent') {
      manualDiscountAmount = rawSubtotal * (manualDiscount.value / 100);
    } else {
      manualDiscountAmount = manualDiscount.value;
    }
  }

  const redeemRate = settings?.loyaltyProgram?.redeemRate || 100;
  const loyaltyDiscountAmount = redeemPoints > 0 ? redeemPoints / redeemRate : 0;

  let discountAmount = Math.min(customerDiscountAmount + manualDiscountAmount + loyaltyDiscountAmount, rawSubtotal);
  let discountedSubtotal = rawSubtotal - discountAmount;

  // 2. Apply Tax
  let taxAmount = 0;
  let finalTotal = discountedSubtotal;
  const taxConfig = settings?.tax;

  if (taxConfig && taxConfig.enabled) {
    const rate = taxConfig.rate / 100;
    if (taxConfig.calculationMode === 'excluded') {
       taxAmount = discountedSubtotal * rate;
       finalTotal = discountedSubtotal + taxAmount;
    } else {
       taxAmount = discountedSubtotal - (discountedSubtotal / (1 + rate));
       finalTotal = discountedSubtotal;
    }
  }

  const receivedAmount = parseFloat(receivedAmountStr) || 0;
  const change = Math.max(0, receivedAmount - finalTotal);

  // --- Broadcast Channel ---
  useEffect(() => {
    if (settings?.customerDisplay?.enabled) {
      const payload = {
        type: isCheckoutOpen ? 'CHECKOUT' : (cart.length === 0 ? 'RESET' : 'UPDATE'),
        cart,
        subtotal: rawSubtotal,
        discount: discountAmount,
        tax: taxAmount,
        total: finalTotal,
        customer: selectedCustomer,
        paymentMethod,
        amountReceived: receivedAmount,
        change,
        companyName: settings?.companyName,
        settings: settings?.customerDisplay
      };
      const channel = new BroadcastChannel('customer_display_channel');
      channel.postMessage(payload);
      return () => channel.close();
    }
  }, [cart, rawSubtotal, discountAmount, taxAmount, finalTotal, selectedCustomer, isCheckoutOpen, paymentMethod, receivedAmount, change, settings]);

  const handleOpenCustomerDisplay = () => {
    window.open('/customer-display', 'CustomerDisplay', 'width=1024,height=768,menubar=no,toolbar=no,location=no,status=no');
  };

  useEffect(() => {
     setRedeemPoints(0);
  }, [selectedCustomer]);

  // --- Branch Logic (Inventory Filtering) ---
  const activeBranchId = settings?.currentBranchId || currentUser?.branchId || (branches.length > 0 ? branches[0].id : '');

  const branchProducts = useMemo(() => {
    if (!activeBranchId) return products;

    // Get warehouse IDs belonging to this branch
    const branchWarehouseIds = warehouses
      .filter(w => w.branchId === activeBranchId)
      .map(w => w.id);

    return products.map(p => {
      // 1. Calculate Stock for this branch
      const branchStock = p.warehouseInventory?.reduce((acc, inv) => {
        if (branchWarehouseIds.includes(inv.warehouseId)) {
          return acc + inv.quantity;
        }
        return acc;
      }, 0) || 0;

      // 2. Check for Branch Price override
      const branchPriceConfig = p.branchPrices?.find(bp => bp.branchId === activeBranchId);
      const effectivePrice = branchPriceConfig ? branchPriceConfig.price : p.price;

      return {
        ...p,
        stock: branchStock,
        price: effectivePrice
      };
    });
  }, [products, activeBranchId, warehouses]);

  const filteredProducts = useMemo(() => {
    return branchProducts.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = 
        p.name.toLowerCase().includes(searchLower) ||
        p.sku?.toLowerCase().includes(searchLower) ||
        p.barcode?.includes(searchLower);

      const matchesVariant = p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower)
      );

      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return (matchesMain || matchesVariant) && matchesCategory;
    });
  }, [branchProducts, searchTerm, selectedCategory]);

  const filteredCustomers = useMemo(() => {
    return customers.filter(c => 
      c.name.toLowerCase().includes(customerSearch.toLowerCase()) || 
      c.phone.includes(customerSearch) ||
      c.code.toLowerCase().includes(customerSearch.toLowerCase())
    );
  }, [customers, customerSearch]);

  const handleBarcodeScan = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;
    performScan(searchTerm);
  };

  const performScan = (code: string) => {
    const mainMatch = branchProducts.find(p => p.barcode === code || p.sku === code);
    if (mainMatch) {
      addToCart(mainMatch, 1, undefined);
      setSearchTerm(''); 
      return;
    }
    for (const p of branchProducts) {
      if (p.variants) {
        const variantMatch = p.variants.find(v => v.barcode === code || v.code === code);
        if (variantMatch) {
          addToCart(p, 1, variantMatch.id);
          setSearchTerm('');
          return;
        }
      }
    }
    if (isScannerOpen) alert(`Product not found: ${code}`);
  };

  const handleAiItemsAdded = (items: EstimateResultItem[]) => {
    items.forEach(est => {
      if (est.matchedProductId) {
        const product = branchProducts.find(p => p.id === est.matchedProductId);
        if (product) addToCart(product, Math.ceil(est.estimatedQuantity), undefined);
      }
    });
  };

  const handleHoldOrder = () => {
    if (cart.length === 0) return;
    const note = prompt("Optional note for this hold:");
    holdCurrentOrder(selectedCustomer, note || undefined);
    setSelectedCustomer(null);
    setManualDiscount(null);
    setRedeemPoints(0);
  };

  const handleRecall = (orderId: string) => {
    const restored = recallOrder(orderId);
    if (restored) {
      setSelectedCustomer(restored.customer || null);
      setIsRecallModalOpen(false);
    }
  };

  // --- Checkout Logic ---
  const handleCheckoutClick = () => {
    setReceivedAmountStr('');
    setPaymentMethod('cash');
    setCheckoutStep('method'); // Always start at method selection
    setIsCheckoutOpen(true);
  };

  const selectPaymentMethod = (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit') => {
    if (method === 'credit' && !selectedCustomer) {
      alert("Credit payment requires a registered customer.");
      return;
    }
    setPaymentMethod(method);
    setReceivedAmountStr('');
    setCheckoutStep('detail'); // Move to next step
  };

  const handleProcessPayment = async () => {
    if (paymentMethod === 'cash' && receivedAmount < finalTotal) {
      alert("Insufficient amount received!");
      return;
    }
    if (paymentMethod === 'credit' && receivedAmount > finalTotal) {
      alert("Deposit cannot exceed total amount.");
      return;
    }

    setIsProcessing(true);
    let finalReceived = paymentMethod === 'cash' || paymentMethod === 'credit' ? receivedAmount : finalTotal;
    let finalChange = paymentMethod === 'cash' ? change : 0;

    try {
      const sale = await onProcessSale(
        cart, finalTotal, selectedCustomer?.id, discountAmount, rawSubtotal,
        paymentMethod, finalReceived, finalChange, redeemPoints
      );

      setLastSale(sale);
      setIsCheckoutOpen(false);
      clearCart();
      setManualDiscount(null); 
      setRedeemPoints(0);
      setSelectedCustomer(null);
      setIsReceiptOpen(true);
    } catch (error) {
      console.error("Sale failed", error);
      alert("Transaction failed. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleNumPadClick = (val: string) => {
    if (val === 'C') setReceivedAmountStr('');
    else if (val === 'BS') setReceivedAmountStr(prev => prev.slice(0, -1));
    else if (val === '.') {
      if (!receivedAmountStr.includes('.')) setReceivedAmountStr(prev => (prev === '' ? '0' : prev) + '.');
    } else {
      setReceivedAmountStr(prev => (prev === '0' ? val : prev + val));
    }
  };

  const handleQuickCash = (amount: number) => {
    setReceivedAmountStr(amount.toString());
  };

  const getConfirmButtonText = () => {
    if (isProcessing) return 'Processing...';

    if (paymentMethod === 'cash') {
      if (receivedAmount < finalTotal) return `Enter Amount (Due: ${formatPrice(finalTotal)})`;
      if (change > 0) return `Confirm Pay & Return ${formatPrice(change)}`;
      return `Confirm Payment ${formatPrice(finalTotal)}`;
    }

    if (paymentMethod === 'credit') {
       return `Confirm Credit Sale ${formatPrice(finalTotal)}`;
    }

    return `Confirm Payment ${formatPrice(finalTotal)}`;
  };

  // --- Render Helpers ---
  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);
  const [tempDiscount, setTempDiscount] = useState<{ type: 'percent' | 'fixed', value: number }>({ type: 'percent', value: 0 });
  const barcodeList = useMemo(() => products.map(p => p.barcode).filter(Boolean), [products]);
  const receiptWidthClass = settings?.receiptPaperSize === '58mm' ? 'print-w-58mm' : settings?.receiptPaperSize === 'A4' ? 'print-w-A4' : 'print-w-80mm';

  return (
    <div className="flex flex-col lg:flex-row h-full gap-6 relative">
      {/* Main Product Area */}
      <div className="flex-1 flex flex-col min-w-0 h-full">
        {/* Top Bar */}
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-4">
            <h2 className="text-2xl font-bold text-slate-800 hidden md:block">{t('pos.newOrder')}</h2>
          </div>

          <div className="flex space-x-2 w-full md:w-auto overflow-x-auto pb-1 md:pb-0">
             <button 
               onClick={() => setIsRecallModalOpen(true)}
               disabled={heldOrders.length === 0}
               className={`flex items-center px-3 py-2 rounded-lg text-sm font-medium border whitespace-nowrap ${
                 heldOrders.length > 0 ? 'bg-orange-50 text-orange-700 border-orange-200' : 'bg-white text-slate-400 border-slate-200 cursor-not-allowed'
               }`}
             >
               <ClipboardList className="w-4 h-4 mr-2" />
               Recall ({heldOrders.length})
             </button>
             {settings?.customerDisplay?.enabled && (
               <button onClick={handleOpenCustomerDisplay} className="flex items-center px-3 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 shadow-sm text-sm whitespace-nowrap">
                 <Monitor className="w-4 h-4 mr-2" /> Customer Screen
               </button>
             )}
             <button 
              onClick={() => setIsCustomerModalOpen(true)}
              className={`flex items-center px-3 py-2 rounded-lg shadow-sm font-medium text-sm border whitespace-nowrap ${
                selectedCustomer ? 'bg-blue-50 text-blue-700 border-blue-200' : 'bg-white text-slate-600 border-slate-200'
              }`}
            >
              <User className="w-4 h-4 mr-2" />
              {selectedCustomer ? selectedCustomer.name : t('pos.selectCustomer')}
            </button>
            <button onClick={() => setIsAiModalOpen(true)} className="flex items-center px-3 py-2 bg-gradient-to-r from-violet-600 to-indigo-600 text-white rounded-lg shadow-md hover:shadow-lg transition-all text-sm font-medium whitespace-nowrap">
              <Sparkles className="w-4 h-4 md:mr-2" /> <span className="hidden md:inline">{t('pos.aiEstimate')}</span>
            </button>
          </div>
        </div>

        {/* Search & Filter */}
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 mb-4 space-y-3">
          <form onSubmit={handleBarcodeScan} className="relative flex gap-2">
            <div className="relative flex-1">
               <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
               <input
                 type="text"
                 placeholder={t('pos.scanPlaceholder')}
                 className="w-full pl-10 pr-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500 text-slate-700 bg-slate-50 font-medium"
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
                 autoFocus
               />
            </div>
            <button type="button" onClick={() => setIsScannerOpen(true)} className="bg-slate-800 text-white px-4 rounded-xl hover:bg-slate-900 shadow-md">
               <ScanBarcode className="w-6 h-6" />
            </button>
          </form>
          <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-hide">
            <button onClick={() => setSelectedCategory('all')} className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border ${selectedCategory === 'all' ? 'bg-slate-800 text-white border-slate-800' : 'bg-white text-slate-600 border-slate-200'}`}>{t('pos.allItems')}</button>
            {Object.values(Category).map(cat => (
              <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border ${selectedCategory === cat ? 'bg-orange-500 text-white border-orange-500' : 'bg-white text-slate-600 border-slate-200'}`}>{cat}</button>
            ))}
          </div>
        </div>

        {/* Products Grid */}
        <div className="flex-1 overflow-y-auto pb-20 md:pb-0">
          <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4">
            {filteredProducts.map((product) => (
              <div key={product.id} onClick={() => !product.variants?.length && addToCart(product)} className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden hover:shadow-lg hover:border-orange-200 transition-all cursor-pointer flex flex-col group h-full">
                <div className="h-32 bg-slate-50 relative flex items-center justify-center overflow-hidden">
                  {product.imageUrl ? (
                    <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                  ) : (
                    <Box className="w-10 h-10 text-slate-300" />
                  )}
                  <span className={`absolute top-2 right-2 px-2 py-0.5 rounded text-[10px] font-bold text-white shadow-sm ${product.stock > (product.minStock || 0) ? 'bg-green-500' : 'bg-red-500'}`}>
                    {product.stock} {product.unit}
                  </span>
                </div>
                <div className="p-3 flex-1 flex flex-col">
                  <h3 className="font-bold text-slate-800 text-sm line-clamp-2 mb-1">{product.name}</h3>
                  <div className="mt-auto pt-2">
                    <div className="flex justify-between items-center mb-2">
                      <span className="font-bold text-slate-900">{formatPrice(product.price)}</span>
                    </div>
                    {product.variants?.length ? (
                      <div className="grid grid-cols-2 gap-1">
                         {product.variants.map(v => (
                           <button key={v.id} onClick={(e) => { e.stopPropagation(); addToCart(product, 1, v.id); }} className="px-2 py-1.5 bg-slate-100 hover:bg-orange-100 text-xs font-bold rounded text-slate-700 hover:text-orange-700 border border-slate-200">
                              {v.name}
                           </button>
                         ))}
                      </div>
                    ) : (
                      <button className="w-full py-1.5 bg-slate-900 text-white rounded-lg text-xs font-bold hover:bg-orange-600 transition-colors opacity-0 group-hover:opacity-100">Add</button>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
          {filteredProducts.length === 0 && (
            <div className="flex flex-col items-center justify-center h-64 text-slate-400">
              <Box className="w-12 h-12 mb-2 opacity-30" />
              <p>No products found.</p>
            </div>
          )}
        </div>
      </div>

      {/* Mobile Cart Toggle */}
      {cartItemCount > 0 && (
        <button 
          onClick={() => setIsCartOpen(true)}
          className="lg:hidden fixed bottom-6 right-4 left-4 bg-slate-900 text-white p-4 rounded-xl shadow-xl flex justify-between items-center z-30"
        >
          <div className="flex items-center">
            <div className="bg-orange-500 rounded-full w-8 h-8 flex items-center justify-center font-bold text-xs mr-3">
              {cartItemCount}
            </div>
            <span className="font-bold">View Cart</span>
          </div>
          <span className="font-bold text-lg">{formatPrice(finalTotal)}</span>
        </button>
      )}

      {/* Cart Sidebar */}
      <div className={`fixed inset-y-0 right-0 z-40 w-full md:w-[400px] bg-white shadow-2xl transform transition-transform duration-300 lg:relative lg:translate-x-0 lg:shadow-none lg:border-l lg:border-slate-200 flex flex-col ${isCartOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-white shadow-sm z-10">
          <h3 className="font-bold text-slate-800 text-lg flex items-center"><ShoppingCart className="w-5 h-5 mr-2 text-orange-600" /> Current Order</h3>
          <div className="flex space-x-2">
             <button onClick={handleHoldOrder} disabled={cart.length === 0} className="p-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200 transition-colors" title="Hold">
                <PauseCircle className="w-5 h-5" />
             </button>
             <button onClick={() => setIsCartOpen(false)} className="lg:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-full">
               <X className="w-6 h-6" />
             </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50/50">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 space-y-4">
              <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center"><ShoppingCart className="w-8 h-8 text-slate-300" /></div>
              <p>Cart is empty</p>
            </div>
          ) : (
            cart.map((item, index) => (
              <div key={`${item.id}-${index}`} className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm flex flex-col gap-2">
                <div className="flex justify-between items-start">
                  <div>
                    <h4 className="font-bold text-slate-800 text-sm line-clamp-1">{item.name}</h4>
                    <span className="text-xs text-slate-500 bg-slate-100 px-1.5 py-0.5 rounded">{item.sellUnit} • {formatPrice(item.sellPrice)}</span>
                  </div>
                  <span className="font-bold text-slate-900">{formatPrice(item.sellPrice * item.quantity)}</span>
                </div>
                <div className="flex items-center justify-between mt-1">
                   <div className="flex items-center bg-slate-100 rounded-lg p-1">
                      <button onClick={() => updateQuantity(index, -1)} className="w-8 h-8 flex items-center justify-center bg-white rounded shadow-sm text-slate-600 hover:text-red-500"><Minus className="w-4 h-4" /></button>
                      <input type="number" value={item.quantity} onChange={(e) => setQuantity(index, parseInt(e.target.value)||1)} className="w-10 text-center bg-transparent font-bold text-sm" />
                      <button onClick={() => updateQuantity(index, 1)} className="w-8 h-8 flex items-center justify-center bg-white rounded shadow-sm text-slate-600 hover:text-green-500"><Plus className="w-4 h-4" /></button>
                   </div>
                   <button onClick={() => removeFromCart(index)} className="p-2 text-red-400 hover:text-red-600"><Trash2 className="w-4 h-4" /></button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-5 bg-white border-t border-slate-200 shadow-[0_-10px_30px_rgba(0,0,0,0.05)] z-20">
          {selectedCustomer && (
             <div className="flex justify-between items-center p-3 bg-blue-50 border border-blue-100 rounded-lg text-sm text-blue-900 mb-3">
                <span className="font-bold flex items-center"><User className="w-4 h-4 mr-2" /> {selectedCustomer.name}</span>
                <button onClick={() => setSelectedCustomer(null)}><X className="w-4 h-4 text-blue-400" /></button>
             </div>
          )}
          <div className="space-y-2 text-sm text-slate-600 mb-4">
            <div className="flex justify-between"><span>Subtotal</span><span>{formatPrice(rawSubtotal)}</span></div>
            <div className="flex justify-between text-green-600 cursor-pointer" onClick={() => setIsDiscountModalOpen(true)}>
               <span className="flex items-center underline"><Percent className="w-3 h-3 mr-1" /> Discount</span>
               <span>-{formatPrice(discountAmount)}</span>
            </div>
            {taxConfig?.enabled && <div className="flex justify-between text-slate-500"><span>Tax ({taxConfig.rate}%)</span><span>{formatPrice(taxAmount)}</span></div>}
          </div>
          <div className="flex justify-between items-end mb-4 pt-4 border-t border-slate-100">
            <span className="text-lg font-bold text-slate-800">Total</span>
            <span className="text-3xl font-bold text-slate-900 tracking-tight">{formatPrice(finalTotal)}</span>
          </div>
          <button 
            onClick={handleCheckoutClick} 
            disabled={cart.length === 0}
            className="w-full py-4 bg-slate-900 text-white rounded-xl font-bold text-lg hover:bg-slate-800 shadow-lg disabled:opacity-50 flex items-center justify-center transition-all active:scale-[0.98]"
          >
            <Banknote className="w-5 h-5 mr-2" /> Charge
          </button>
        </div>
      </div>

      {/* ... (Checkout, Customer, Discount, Recall, Receipt Modals remain unchanged) ... */}
      {/* ... CHECKOUT MODAL ... */}
      {isCheckoutOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/60 backdrop-blur-sm p-0 sm:p-4 animate-fade-in">
          <div className="bg-white w-full h-[90vh] sm:h-[650px] sm:max-w-5xl rounded-t-2xl sm:rounded-2xl shadow-2xl flex flex-col sm:flex-row overflow-hidden">
            {/* ... checkout content same as before ... */}
            <div className={`w-full sm:w-1/3 bg-slate-50 border-r border-slate-200 flex flex-col ${checkoutStep === 'detail' ? 'hidden sm:flex' : 'flex'}`}>
               <div className="p-5 border-b border-slate-200 bg-white sm:bg-transparent flex justify-between items-center">
                  <h3 className="font-bold text-lg text-slate-800">Payment Method</h3>
                  <button onClick={() => setIsCheckoutOpen(false)} className="sm:hidden p-2 bg-slate-100 rounded-full text-slate-500"><X className="w-5 h-5"/></button>
               </div>
               <div className="p-4 space-y-3 flex-1 overflow-y-auto">
                  <button onClick={() => selectPaymentMethod('cash')} className={`w-full p-4 rounded-xl border-2 flex items-center transition-all ${paymentMethod === 'cash' ? 'border-blue-500 bg-white shadow-md' : 'border-slate-200 bg-white hover:border-blue-300'}`}>
                     <div className={`p-3 rounded-full mr-4 ${paymentMethod === 'cash' ? 'bg-blue-100 text-blue-600' : 'bg-slate-100 text-slate-500'}`}><Banknote className="w-6 h-6" /></div>
                     <span className="font-bold text-lg text-slate-700">Cash</span>
                  </button>
                  <button onClick={() => selectPaymentMethod('qr')} className={`w-full p-4 rounded-xl border-2 flex items-center transition-all ${paymentMethod === 'qr' ? 'border-blue-500 bg-white shadow-md' : 'border-slate-200 bg-white hover:border-blue-300'}`}>
                     <div className={`p-3 rounded-full mr-4 ${paymentMethod === 'qr' ? 'bg-blue-100 text-blue-600' : 'bg-slate-100 text-slate-500'}`}><QrCode className="w-6 h-6" /></div>
                     <span className="font-bold text-lg text-slate-700">OnePay / QR</span>
                  </button>
                  <button onClick={() => selectPaymentMethod('card')} className={`w-full p-4 rounded-xl border-2 flex items-center transition-all ${paymentMethod === 'card' ? 'border-blue-500 bg-white shadow-md' : 'border-slate-200 bg-white hover:border-blue-300'}`}>
                     <div className={`p-3 rounded-full mr-4 ${paymentMethod === 'card' ? 'bg-blue-100 text-blue-600' : 'bg-slate-100 text-slate-500'}`}><CreditCard className="w-6 h-6" /></div>
                     <span className="font-bold text-lg text-slate-700">Card / Transfer</span>
                  </button>
                  <button onClick={() => selectPaymentMethod('credit')} className={`w-full p-4 rounded-xl border-2 flex items-center transition-all ${!selectedCustomer ? 'opacity-50 cursor-not-allowed' : ''} ${paymentMethod === 'credit' ? 'border-orange-500 bg-white shadow-md' : 'border-slate-200 bg-white hover:border-orange-300'}`}>
                     <div className={`p-3 rounded-full mr-4 ${paymentMethod === 'credit' ? 'bg-orange-100 text-orange-600' : 'bg-slate-100 text-slate-500'}`}><FileText className="w-6 h-6" /></div>
                     <div className="text-left">
                        <span className="font-bold text-lg text-slate-700 block">Credit / ติดหนี้</span>
                        <span className="text-xs text-slate-400 font-medium">Members Only</span>
                     </div>
                  </button>
               </div>
               <div className="p-5 border-t border-slate-200 bg-white sm:bg-transparent">
                  <div className="flex justify-between items-center">
                     <span className="text-sm font-medium text-slate-500">Total Due</span>
                     <span className="text-2xl font-bold text-slate-900">{formatPrice(finalTotal)}</span>
                  </div>
               </div>
            </div>
            <div className={`flex-1 bg-white flex flex-col ${checkoutStep === 'method' ? 'hidden sm:flex' : 'flex'} h-full`}>
               <div className="p-4 border-b border-slate-100 flex items-center justify-between sm:justify-end">
                  <button onClick={() => setCheckoutStep('method')} className="sm:hidden flex items-center text-slate-500 font-medium hover:text-slate-800">
                     <ChevronLeft className="w-5 h-5 mr-1" /> Back
                  </button>
                  <button onClick={() => setIsCheckoutOpen(false)} className="hidden sm:block p-2 hover:bg-slate-100 rounded-full text-slate-400">
                     <X className="w-6 h-6" />
                  </button>
               </div>
               <div className="flex-1 p-4 sm:p-8 overflow-y-auto">
                  <div className="text-center mb-6">
                     <h3 className="text-xl font-bold text-slate-800 flex items-center justify-center gap-2">
                        {paymentMethod === 'cash' ? <Banknote className="text-blue-600"/> : paymentMethod === 'qr' ? <QrCode className="text-blue-600"/> : <CreditCard className="text-blue-600"/>}
                        {paymentMethod === 'cash' ? 'Cash Payment' : paymentMethod === 'qr' ? 'Scan to Pay' : 'Digital Payment'}
                     </h3>
                  </div>
                  {paymentMethod === 'cash' ? (
                     <div className="flex-1 flex flex-col max-w-lg mx-auto w-full">
                        <div className="bg-slate-50 border border-slate-200 rounded-2xl p-6 mb-4 text-right shadow-inner relative">
                           <span className="absolute top-4 left-4 text-xs font-bold text-slate-400 uppercase tracking-wide">Amount Received</span>
                           <div className={`text-6xl font-bold tracking-tight ${receivedAmountStr ? 'text-slate-900' : 'text-slate-300'}`}>
                              {receivedAmountStr ? formatPrice(parseFloat(receivedAmountStr)) : formatPrice(0)}
                           </div>
                        </div>
                        <div className="flex justify-between items-end mb-6 px-2">
                           <div>
                              <p className="text-xs font-bold text-slate-400 uppercase mb-1">Change Due</p>
                              <p className={`text-4xl font-bold ${change > 0 ? 'text-green-600' : 'text-slate-300'}`}>{formatPrice(change)}</p>
                           </div>
                           {(finalTotal - receivedAmount) > 0 && (
                              <div className="text-right">
                                 <p className="text-xs font-bold text-slate-400 uppercase mb-1">Remaining</p>
                                 <p className="text-2xl font-bold text-red-500">{formatPrice(finalTotal - receivedAmount)}</p>
                              </div>
                           )}
                        </div>
                        <div className="flex gap-3 flex-1 min-h-[320px]">
                           <div className="grid grid-cols-3 gap-3 flex-[3]">
                              {[1, 2, 3, 4, 5, 6, 7, 8, 9, '00', 0, 'BS'].map((btn) => (
                                 <button
                                    key={btn}
                                    onClick={() => handleNumPadClick(btn.toString())}
                                    className="bg-white border border-slate-200 rounded-xl text-2xl font-semibold text-slate-700 hover:bg-slate-50 hover:border-slate-300 active:scale-95 transition-all shadow-sm flex items-center justify-center"
                                 >
                                    {btn === 'BS' ? <ArrowLeft className="w-8 h-8" /> : btn}
                                 </button>
                              ))}
                           </div>
                           <div className="flex flex-col gap-3 flex-1">
                              <button onClick={() => handleQuickCash(Math.ceil(finalTotal))} className="flex-1 bg-blue-50 text-blue-700 font-bold rounded-xl border border-blue-100 hover:bg-blue-100 transition-all text-sm shadow-sm">Exact</button>
                              {[10000, 20000, 50000, 100000].map(val => (
                                 <button key={val} onClick={() => handleQuickCash(val)} className="flex-1 bg-white text-slate-600 font-bold rounded-xl border border-slate-200 hover:bg-slate-50 transition-all text-xs shadow-sm">
                                    {val/1000}k
                                 </button>
                              ))}
                           </div>
                        </div>
                     </div>
                  ) : paymentMethod === 'qr' ? (
                     <div className="flex-1 flex flex-col items-center justify-center">
                        <div className="bg-white p-6 rounded-3xl border-2 border-slate-100 shadow-lg mb-6">
                           <img src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=Payment_OnePay_${finalTotal}`} className="w-64 h-64 object-contain" alt="QR" />
                        </div>
                        <p className="text-lg font-bold text-slate-700">Scan to pay {formatPrice(finalTotal)}</p>
                     </div>
                  ) : (
                     <div className="flex-1 flex flex-col items-center justify-center text-center">
                        <div className="w-32 h-32 bg-slate-100 rounded-full flex items-center justify-center mb-6 animate-pulse">
                           {paymentMethod === 'credit' ? <FileText className="w-16 h-16 text-orange-500" /> : <CreditCard className="w-16 h-16 text-blue-500" />}
                        </div>
                        <h4 className="text-xl font-bold text-slate-800 mb-2">
                           {paymentMethod === 'credit' ? 'Confirm Credit Sale' : 'Waiting for Terminal'}
                        </h4>
                        <p className="text-slate-500">Total amount: <strong>{formatPrice(finalTotal)}</strong></p>
                     </div>
                  )}
               </div>
               <div className="p-4 border-t border-slate-100 bg-white">
                  <button 
                     onClick={handleProcessPayment}
                     disabled={isProcessing || (paymentMethod === 'cash' && receivedAmount < finalTotal) || (paymentMethod === 'credit' && receivedAmount > finalTotal)}
                     className={`w-full py-4 rounded-xl font-bold text-xl text-white shadow-lg flex items-center justify-center transition-all active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed ${paymentMethod === 'credit' ? 'bg-orange-600' : 'bg-slate-900 hover:bg-slate-800'}`}
                  >
                     {isProcessing ? 'Processing...' : (
                        <>
                           <CheckCircle className="w-6 h-6 mr-2" /> 
                           {getConfirmButtonText()}
                        </>
                     )}
                  </button>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* Customer Modal, Discount Modal, Recall Modal, Receipt Modal - same as previous */}
      {isCustomerModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-60 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
           <div className="bg-white rounded-xl shadow-2xl w-full max-w-md max-h-[80vh] flex flex-col overflow-hidden animate-fade-in">
              <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                 <h3 className="font-bold text-slate-800 text-lg">Select Customer</h3>
                 <button onClick={() => setIsCustomerModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X className="w-5 h-5"/></button>
              </div>
              <div className="p-4 flex-1 overflow-hidden flex flex-col">
                 <div className="relative mb-4">
                    <Search className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
                    <input 
                       autoFocus
                       placeholder="Search name, phone, code..." 
                       className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                       value={customerSearch}
                       onChange={e => setCustomerSearch(e.target.value)}
                    />
                 </div>
                 <div className="overflow-y-auto flex-1 space-y-2">
                    {filteredCustomers.length === 0 ? (
                       <div className="text-center py-8 text-slate-400">No customers found.</div>
                    ) : (
                       filteredCustomers.map(c => (
                          <button 
                             key={c.id} 
                             onClick={() => { setSelectedCustomer(c); setIsCustomerModalOpen(false); }}
                             className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 flex justify-between items-center transition-colors group"
                          >
                             <div>
                                <div className="font-bold text-slate-800 group-hover:text-blue-600">{c.name}</div>
                                <div className="text-xs text-slate-500">{c.code} {c.phone && `• ${c.phone}`}</div>
                             </div>
                             {c.loyaltyPoints > 0 && <span className="text-xs bg-yellow-50 text-yellow-700 px-2 py-1 rounded-full font-bold border border-yellow-100">{c.loyaltyPoints} pts</span>}
                          </button>
                       ))
                    )}
                 </div>
              </div>
           </div>
        </div>
      )}

      {isDiscountModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-60 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm animate-fade-in">
            <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
              <h3 className="font-bold text-slate-800 flex items-center"><Tag className="w-5 h-5 mr-2 text-slate-500" /> Apply Discount</h3>
              <button onClick={() => setIsDiscountModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X className="w-5 h-5" /></button>
            </div>
            <div className="p-5 space-y-5">
               <div className="flex bg-slate-100 p-1 rounded-lg">
                  <button onClick={() => setTempDiscount(prev => ({ ...prev, type: 'percent' }))} className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${tempDiscount.type === 'percent' ? 'bg-white shadow-sm text-slate-800' : 'text-slate-500 hover:text-slate-700'}`}>Percent (%)</button>
                  <button onClick={() => setTempDiscount(prev => ({ ...prev, type: 'fixed' }))} className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${tempDiscount.type === 'fixed' ? 'bg-white shadow-sm text-slate-800' : 'text-slate-500 hover:text-slate-700'}`}>Fixed Amount ({settings?.currencySymbol})</button>
               </div>
               <div>
                  <label className="block text-sm font-medium text-slate-700 mb-2">{tempDiscount.type === 'fixed' ? 'Amount' : 'Percentage'}</label>
                  <div className="relative">
                     <input type="number" min="0" step={tempDiscount.type === 'fixed' ? "0.01" : "1"} value={tempDiscount.value || ''} onChange={(e) => setTempDiscount(prev => ({ ...prev, value: parseFloat(e.target.value) || 0 }))} className="w-full pl-4 pr-4 py-3 border border-slate-300 rounded-xl focus:ring-2 focus:ring-blue-500 text-2xl font-bold text-center" placeholder="0" autoFocus />
                  </div>
               </div>
               <div className="flex space-x-3 pt-2">
                  <button onClick={() => { setManualDiscount(null); setIsDiscountModalOpen(false); }} className="flex-1 py-3 border border-red-200 text-red-600 rounded-xl font-bold hover:bg-red-50 transition-colors">Clear</button>
                  <button onClick={() => { setManualDiscount(tempDiscount); setIsDiscountModalOpen(false); }} className="flex-1 py-3 bg-slate-900 text-white rounded-xl font-bold hover:bg-slate-800 transition-colors shadow-lg">Apply Discount</button>
               </div>
            </div>
          </div>
        </div>
      )}

      {isRecallModalOpen && (
         <div className="fixed inset-0 bg-black bg-opacity-60 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg flex flex-col max-h-[80vh]">
               <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
                  <h3 className="font-bold text-slate-800 flex items-center">
                     <ClipboardList className="w-5 h-5 mr-2 text-slate-500" /> 
                     Suspended Orders
                  </h3>
                  <button onClick={() => setIsRecallModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X className="w-5 h-5" /></button>
               </div>
               <div className="p-4 overflow-y-auto flex-1 bg-slate-50">
                  {heldOrders.length === 0 ? (
                     <div className="text-center py-12 text-slate-400">
                        <PauseCircle className="w-12 h-12 mx-auto mb-2 opacity-20" />
                        <p>No suspended orders.</p>
                     </div>
                  ) : (
                     <div className="space-y-3">
                        {heldOrders.map(order => (
                           <div key={order.id} className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 hover:shadow-md transition-all">
                              <div className="flex justify-between items-start mb-2">
                                 <div>
                                    <div className="flex items-center">
                                       <span className="font-bold text-slate-800 text-lg mr-2">{formatPrice(order.total)}</span>
                                       <span className="text-xs bg-slate-100 px-2 py-0.5 rounded text-slate-500 font-mono">
                                          {new Date(order.timestamp).toLocaleTimeString()}
                                       </span>
                                    </div>
                                    <div className="text-sm text-slate-500 mt-1">
                                       {order.customer ? order.customer.name : 'Walk-in Customer'} • {order.items.length} items
                                    </div>
                                    {order.note && <div className="text-xs text-orange-600 mt-2 bg-orange-50 px-2 py-1 rounded inline-block font-medium">{order.note}</div>}
                                 </div>
                                 <button 
                                    onClick={() => { if(confirm('Delete this order?')) discardHeldOrder(order.id); }}
                                    className="text-slate-300 hover:text-red-500 p-2 rounded-full hover:bg-slate-50"
                                 >
                                    <Trash2 className="w-4 h-4" />
                                 </button>
                              </div>
                              <button 
                                 onClick={() => handleRecall(order.id)}
                                 className="w-full mt-2 py-2 bg-slate-800 text-white rounded-lg text-sm font-bold hover:bg-slate-900 transition-colors flex items-center justify-center"
                              >
                                 <RefreshCw className="w-3.5 h-3.5 mr-2" /> Restore to Cart
                              </button>
                           </div>
                        ))}
                     </div>
                  )}
               </div>
            </div>
         </div>
      )}

      {isReceiptOpen && lastSale && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-[70] p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm flex flex-col overflow-hidden">
            <div className="p-4 bg-slate-800 text-white flex justify-between items-center print:hidden">
              <h3 className="font-bold flex items-center"><CheckCircle className="w-5 h-5 mr-2 text-green-400" /> Sale Completed</h3>
              <button onClick={() => setIsReceiptOpen(false)} className="text-slate-400 hover:text-white"><X className="w-5 h-5" /></button>
            </div>

            <div className="p-6 bg-slate-50 flex-1 overflow-y-auto max-h-[60vh] print:p-0 print:max-h-none print:overflow-visible">
              <div id="printable-receipt" className={`bg-white p-4 shadow-sm border border-slate-200 text-xs font-mono text-black mx-auto ${receiptWidthClass} print:shadow-none print:border-none`}>
                <div className="text-center mb-4">
                  <h2 className="text-lg font-bold mb-1">{settings?.companyName}</h2>
                  <p>{settings?.address}</p>
                  <p>{settings?.phone}</p>
                  <div className="border-b border-dashed border-black my-2"></div>
                  <div className="flex justify-between">
                     <span>Inv: #{lastSale.id.slice(-6)}</span>
                     <span>{new Date(lastSale.date).toLocaleDateString()}</span>
                  </div>
                </div>

                <div className="space-y-1 mb-2">
                  {lastSale.items.map((item, i) => (
                    <div key={i} className="flex justify-between">
                      <span className="truncate w-32">{item.name}</span>
                      <span className="text-right">
                        {item.quantity} x {formatPrice(item.sellPrice)}
                      </span>
                      <span className="font-bold text-right w-16">
                        {formatPrice(item.quantity * item.sellPrice)}
                      </span>
                    </div>
                  ))}
                </div>

                <div className="border-b border-dashed border-black my-2"></div>

                <div className="space-y-1">
                  <div className="flex justify-between"><span>Subtotal</span><span>{formatPrice(lastSale.subtotal || lastSale.total)}</span></div>
                  {lastSale.discountAmount ? <div className="flex justify-between"><span>Discount</span><span>-{formatPrice(lastSale.discountAmount)}</span></div> : null}
                  <div className="flex justify-between font-bold text-sm mt-1 pt-1 border-t border-black"><span>Total</span><span>{formatPrice(lastSale.total)}</span></div>
                </div>

                <div className="border-b border-dashed border-black my-3"></div>

                <div className="space-y-1">
                  <div className="flex justify-between"><span className="capitalize">{lastSale.paymentMethod}</span><span>{formatPrice(lastSale.amountReceived || 0)}</span></div>
                  {lastSale.change !== undefined && lastSale.change > 0 && <div className="flex justify-between font-bold"><span>Change</span><span>{formatPrice(lastSale.change)}</span></div>}
                </div>

                <div className="mt-6 text-center italic">
                  <p className="mb-1">{settings?.receiptHeader}</p>
                  <p>{settings?.receiptFooter}</p>
                </div>
              </div>
            </div>

            <div className="p-4 bg-white border-t border-slate-100 flex gap-3 print:hidden">
              <button onClick={() => window.print()} className="flex-1 py-3 bg-white border border-slate-300 text-slate-700 rounded-lg font-bold hover:bg-slate-50 flex items-center justify-center transition-colors">
                <Printer className="w-5 h-5 mr-2" /> Print
              </button>
              <button onClick={() => setIsReceiptOpen(false)} className="flex-1 py-3 bg-slate-900 text-white rounded-lg font-bold hover:bg-slate-800 flex items-center justify-center transition-colors">
                <Plus className="w-5 h-5 mr-2" /> New Order
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Helper Components */}
      <AiAssistant isOpen={isAiModalOpen} onClose={() => setIsAiModalOpen(false)} inventory={branchProducts} onAddItemsToCart={handleAiItemsAdded} />
      <BarcodeScanner isOpen={isScannerOpen} onClose={() => setIsScannerOpen(false)} onScan={performScan} dummyCodes={barcodeList as string[]} />
    </div>
  );
};

'use client';

import React, { useEffect, useState } from 'react';
import { ShoppingCart, Star, CheckCircle, QrCode, Store, Lock, Image as ImageIcon } from 'lucide-react';
import { CartItem, Customer, CustomerDisplaySettings, Promotion } from '../../types';

// Define the data structure received from the POS
interface DisplayData {
  type: 'UPDATE' | 'CHECKOUT' | 'SUCCESS' | 'RESET';
  cart: CartItem[];
  subtotal: number;
  discount: number;
  tax: number;
  total: number;
  customer?: Customer | null;
  paymentMethod?: string;
  amountReceived?: number;
  change?: number;
  companyName?: string;
  settings?: CustomerDisplaySettings;
  activePromotions?: Promotion[];
}

export default function CustomerDisplayPage() {
  const [data, setData] = useState<DisplayData>({
    type: 'RESET',
    cart: [],
    subtotal: 0,
    discount: 0,
    tax: 0,
    total: 0,
    companyName: 'BuildMaster'
  });

  const [currentPromoIndex, setCurrentPromoIndex] = useState(0);

  // Simple formatter since we don't have full context access here easily without provider wrapping,
  // but we can infer from locale or just format basic number.
  // Ideally, the POS should send pre-formatted strings, but we'll try to match the style.
  const formatPrice = (amount: number) => {
     return new Intl.NumberFormat('lo-LA', {
        style: 'currency',
        currency: 'LAK', // Default to Kip for this display as requested
        minimumFractionDigits: 0,
        maximumFractionDigits: 0,
     }).format(amount);
  };

  useEffect(() => {
    // Connect to the broadcast channel
    const channel = new BroadcastChannel('customer_display_channel');

    // Request initial state from POS when mounted
    channel.postMessage({ type: 'REQUEST_INITIAL_STATE' });

    channel.onmessage = (event) => {
      if (event.data && event.data.type !== 'REQUEST_INITIAL_STATE') {
        setData(prev => ({
          ...prev,
          ...event.data,
          // Preserve settings if not provided in update
          settings: event.data.settings || prev.settings,
          activePromotions: event.data.activePromotions || prev.activePromotions
        }));
      }
    };

    return () => {
      channel.close();
    };
  }, []);

  // Carousel Logic
  useEffect(() => {
    if (data.activePromotions && data.activePromotions.length > 1) {
      const interval = setInterval(() => {
        setCurrentPromoIndex(prev => (prev + 1) % data.activePromotions!.length);
      }, (data.settings?.promotionInterval || 5) * 1000);
      return () => clearInterval(interval);
    }
  }, [data.activePromotions, data.settings?.promotionInterval]);

  // Disabled State
  if (data.settings && data.settings.enabled === false) {
    return (
      <div className="h-screen bg-slate-900 flex flex-col items-center justify-center text-slate-500 p-8 text-center">
        <Lock className="w-16 h-16 mb-4 opacity-50" />
        <h1 className="text-2xl font-bold">Display Closed</h1>
      </div>
    );
  }

  // Idle State (Welcome Screen / Promotions)
  if (data.cart.length === 0 && data.type === 'RESET') {
    const hasPromos = data.activePromotions && data.activePromotions.length > 0;

    return (
      <div className="h-screen bg-slate-900 relative overflow-hidden font-sans">
        {hasPromos ? (
          <div className="absolute inset-0 z-0">
             {data.activePromotions!.map((promo, idx) => (
                <div 
                  key={promo.id}
                  className={`absolute inset-0 bg-cover bg-center transition-opacity duration-1000 ease-in-out ${idx === currentPromoIndex ? 'opacity-50' : 'opacity-0'}`}
                  style={{ backgroundImage: `url(${promo.imageUrl})` }}
                />
             ))}
             <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/40 to-black/30" /> 
          </div>
        ) : (
          <div className="absolute inset-0 flex items-center justify-center opacity-10">
             <Store className="w-96 h-96 text-white" />
          </div>
        )}

        <div className="relative z-10 h-full flex flex-col items-center justify-center text-white p-12 text-center">
          <div className="w-32 h-32 bg-white/10 backdrop-blur-md border border-white/20 rounded-full flex items-center justify-center mb-8 shadow-2xl animate-pulse">
            <Store className="w-16 h-16 text-white" />
          </div>
          <h1 className="text-6xl font-bold mb-6 drop-shadow-lg tracking-tight">
            {data.companyName}
          </h1>
          <p className="text-2xl text-slate-200 max-w-2xl leading-relaxed drop-shadow-md">
            {data.settings?.welcomeMessage || "Welcome! We are ready to serve you."}
          </p>
        </div>
      </div>
    );
  }

  // Success State
  if (data.type === 'SUCCESS') {
    return (
      <div className="h-screen bg-green-600 flex flex-col items-center justify-center text-white p-8 text-center font-sans relative overflow-hidden">
        <div className="absolute inset-0 opacity-20">
           <div className="absolute top-10 left-10 w-32 h-32 rounded-full bg-white blur-3xl"></div>
           <div className="absolute bottom-10 right-10 w-64 h-64 rounded-full bg-white blur-3xl"></div>
        </div>

        <div className="w-40 h-40 bg-white rounded-full flex items-center justify-center mb-8 shadow-2xl z-10 animate-bounce">
          <CheckCircle className="w-24 h-24 text-green-600" />
        </div>
        <h1 className="text-6xl font-bold mb-4 z-10">Thank You!</h1>
        <p className="text-2xl text-green-100 mb-8 z-10">Payment Successful</p>

        <div className="bg-white/20 backdrop-blur-xl border border-white/30 rounded-3xl p-10 min-w-[450px] z-10 shadow-xl">
           <div className="flex justify-between text-xl mb-4 text-green-50">
             <span>Total Amount</span>
             <span className="font-bold text-white text-2xl">{formatPrice(data.total)}</span>
           </div>
           <div className="border-t border-white/30 my-4"></div>
           {data.change !== undefined && data.change > 0 && (
             <div className="flex justify-between items-center">
               <span className="text-green-50 text-2xl">Change Due</span>
               <span className="text-5xl font-bold text-white">{formatPrice(data.change)}</span>
             </div>
           )}
        </div>
      </div>
    );
  }

  // Active Transaction State
  return (
    <div className="h-screen bg-slate-50 flex flex-col md:flex-row overflow-hidden font-sans">
      {/* Left: Cart Items */}
      <div className="flex-1 flex flex-col h-full border-r border-slate-200 bg-white">
        <div className="p-6 bg-slate-900 text-white flex justify-between items-center shadow-md z-10">
          <h2 className="text-2xl font-bold flex items-center">
            <ShoppingCart className="w-7 h-7 mr-3 text-orange-500" />
            Your Order
          </h2>
          <span className="bg-orange-500 text-white px-4 py-1.5 rounded-full text-sm font-bold shadow-sm">
            {data.cart.reduce((acc, item) => acc + item.quantity, 0)} Items
          </span>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/50">
          {data.cart.map((item, index) => (
            <div key={`${item.id}-${index}`} className="flex justify-between items-center p-5 bg-white rounded-2xl border border-slate-100 shadow-sm animate-fade-in transition-all hover:shadow-md">
              <div className="flex items-center flex-1">
                 {item.imageUrl ? (
                    <div className="w-16 h-16 rounded-lg overflow-hidden border border-slate-100 mr-4 shrink-0">
                       <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" />
                    </div>
                 ) : (
                    <div className="w-16 h-16 rounded-lg bg-slate-100 flex items-center justify-center mr-4 text-slate-300 shrink-0">
                       <ImageIcon className="w-8 h-8" />
                    </div>
                 )}
                 <div>
                    <h3 className="text-lg font-bold text-slate-800 line-clamp-2">{item.name}</h3>
                    <p className="text-slate-500 font-medium mt-1">
                      {item.quantity} {item.sellUnit} <span className="text-xs text-slate-400">@ {formatPrice(item.sellPrice)}</span>
                    </p>
                 </div>
              </div>
              <div className="text-xl font-bold text-slate-900 pl-4">
                {formatPrice(item.quantity * item.sellPrice)}
              </div>
            </div>
          ))}
        </div>

        {/* Customer Info footer if exists */}
        {data.customer && (
          <div className="p-5 bg-blue-50 border-t border-blue-100 flex items-center justify-between text-blue-900">
             <div className="flex items-center">
                <div className="p-2 bg-white rounded-full shadow-sm mr-3">
                   <Star className="w-5 h-5 text-yellow-500 fill-current" />
                </div>
                <div>
                   <span className="font-bold text-lg block">{data.customer.name}</span>
                   {data.customer.level && (
                     <span className="text-xs font-bold text-blue-600 uppercase tracking-wider">
                       {data.customer.level.name} Member
                     </span>
                   )}
                </div>
             </div>
             {data.discount > 0 && (
                <div className="text-right">
                   <p className="text-xs text-blue-600 uppercase font-bold">You Saved</p>
                   <p className="text-xl font-bold text-green-600">{formatPrice(data.discount)}</p>
                </div>
             )}
          </div>
        )}
      </div>

      {/* Right: Totals & Checkout Status */}
      <div className="w-full md:w-[480px] bg-white flex flex-col shadow-2xl z-20">
        <div className="flex-1 flex flex-col justify-center p-8 bg-slate-50">
           {data.type === 'CHECKOUT' ? (
             <div className="bg-white p-8 rounded-3xl shadow-xl border border-slate-100 text-center animate-fade-in relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-orange-400 to-red-500"></div>
                {data.paymentMethod === 'qr' ? (
                   <>
                     <h3 className="text-2xl font-bold text-slate-800 mb-6">Scan to Pay</h3>
                     <div className="bg-white border-2 border-slate-100 p-4 rounded-2xl inline-block mb-6 shadow-sm">
                        <img 
                          src={`https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=Payment_OnePay_${data.total}`} 
                          alt="QR Code" 
                          className="w-56 h-56 object-contain rounded-lg"
                        />
                     </div>
                     <p className="text-slate-500 font-medium">Use your banking app to scan</p>
                   </>
                ) : (
                   <>
                     <div className="w-20 h-20 bg-orange-100 rounded-full flex items-center justify-center mx-auto mb-6 text-orange-600">
                        <ShoppingCart className="w-10 h-10" />
                     </div>
                     <h3 className="text-2xl font-bold text-slate-800 mb-2">Proceeding to Payment</h3>
                     <p className="text-slate-500 mb-8">Please follow instructions on the terminal</p>

                     <div className="bg-slate-100 rounded-xl p-4 mb-4">
                        <div className="text-sm text-slate-500 uppercase tracking-wide font-bold mb-1">Total Due</div>
                        <div className="text-5xl font-bold text-slate-900">{formatPrice(data.total)}</div>
                     </div>

                     <div className="inline-flex items-center px-4 py-2 rounded-full bg-slate-200 text-slate-700 font-bold text-sm uppercase">
                        Pay via {data.paymentMethod || 'Cash'}
                     </div>
                   </>
                )}
             </div>
           ) : (
             <div className="text-center space-y-6 opacity-50">
                <div className="w-32 h-32 bg-slate-200 rounded-full flex items-center justify-center mx-auto">
                   <Store className="w-16 h-16 text-slate-400" />
                </div>
                <h3 className="text-2xl font-medium text-slate-400">Total Amount Due</h3>
             </div>
           )}
        </div>

        <div className="bg-white p-8 border-t border-slate-100 shadow-[0_-10px_40px_-15px_rgba(0,0,0,0.1)]">
          <div className="space-y-4 mb-8">
            <div className="flex justify-between text-slate-600 text-lg">
              <span>Subtotal</span>
              <span className="font-medium">{formatPrice(data.subtotal)}</span>
            </div>
            {data.discount > 0 && (
              <div className="flex justify-between text-green-600 text-lg font-medium">
                <span>Discount</span>
                <span>-{formatPrice(data.discount)}</span>
              </div>
            )}
            {data.tax > 0 && (
              <div className="flex justify-between text-slate-500 text-lg">
                <span>Tax</span>
                <span>{formatPrice(data.tax)}</span>
              </div>
            )}
          </div>
          <div className="pt-6 border-t-2 border-dashed border-slate-200">
            <div className="flex justify-between items-end">
              <span className="text-2xl font-bold text-slate-700">Total</span>
              <span className="text-7xl font-bold text-slate-900 tracking-tighter leading-none">{formatPrice(data.total)}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { SystemSettings, Language, Branch, PosMachine, BankAccount } from '../types';
import { useGlobal } from '../context/GlobalContext';
import { 
  Save, 
  Globe, 
  Building, 
  Printer, 
  Percent, 
  Monitor, 
  Database, 
  LayoutList, 
  CheckCircle, 
  X, 
  ImageIcon, 
  QrCode, 
  Copy, 
  RefreshCw, 
  Activity, 
  Wifi, 
  Server, 
  Link, 
  Tv, 
  HardDrive, 
  ShieldAlert, 
  Lock, 
  AlertTriangle,
  Loader2,
  Download,
  Upload,
  Target,
  Banknote,
  Landmark,
  Trash2,
  PlusCircle
} from 'lucide-react';

interface SettingsProps {
  settings: SystemSettings;
  onUpdateSettings: (settings: SystemSettings) => void;
  branches?: Branch[];
  posMachines?: PosMachine[];
}

type SettingsTab = 'company' | 'receipt' | 'financials' | 'device' | 'database' | 'localization' | 'interface' | 'customer_display';

const TABS: { id: SettingsTab; label: string; icon: any }[] = [
  { id: 'company', label: 'Company Information', icon: Building },
  { id: 'receipt', label: 'Receipt & Print Settings', icon: Printer },
  { id: 'financials', label: 'Financials & Tax', icon: Percent },
  { id: 'customer_display', label: 'Customer Display Configuration', icon: Tv },
  { id: 'device', label: 'Device Configuration', icon: Monitor },
  { id: 'database', label: 'Database & Backup', icon: Database },
  { id: 'localization', label: 'Localization & Language', icon: Globe },
  { id: 'interface', label: 'Interface & Display', icon: LayoutList },
];

const MAX_FILE_SIZE_MB = 1; // 1MB max for logo/qr

export const Settings: React.FC<SettingsProps> = ({ settings, onUpdateSettings, branches = [], posMachines = [] }) => {
  // Access global context for export/import
  const { 
    products, sales, customers, users, units, categories, 
    branches: allBranches, posMachines: allPos, warehouses, 
    locations, transfers, counts, reservations, receipts, 
    adjustments, shifts, shiftSchedules, promotions,
    restoreSystemData 
  } = useGlobal();

  const [formData, setFormData] = useState<SystemSettings>(settings);
  const [activeTab, setActiveTab] = useState<SettingsTab>('company');
  const [successMsg, setSuccessMsg] = useState('');
  const importFileRef = useRef<HTMLInputElement>(null);

  // Refs for uploads
  const logoInputRef = useRef<HTMLInputElement>(null);
  const qrInputRef = useRef<HTMLInputElement>(null);

  // Bank Account Form
  const [newBank, setNewBank] = useState<BankAccount>({ id: '', bankName: '', accountName: '', accountNumber: '' });

  // Test Connection State
  const [connectionStatus, setConnectionStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');
  const [localDbStatus, setLocalDbStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');

  // POS Availability Check State
  const [posCheckStatus, setPosCheckStatus] = useState<'idle' | 'checking' | 'available' | 'taken'>('idle');

  // Sync state when props change (e.g. data load from mock or API)
  useEffect(() => {
    setFormData(settings);
  }, [settings]);

  // Handle Tab Change with Auto-Reset Logic
  const handleTabChange = (newTab: SettingsTab) => {
    // If we are leaving the 'device' tab AND the ID is currently invalid (taken) OR checking
    if (activeTab === 'device' && (posCheckStatus === 'taken' || posCheckStatus === 'checking')) {
        // Reset Device fields back to original saved settings
        setFormData(prev => ({
            ...prev,
            currentBranchId: settings.currentBranchId,
            currentPosId: settings.currentPosId,
            deviceRole: settings.deviceRole,
            masterApiUrl: settings.masterApiUrl,
            autoSyncInterval: settings.autoSyncInterval
        }));
        // Clear the error status
        setPosCheckStatus('idle');
    }

    setActiveTab(newTab);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    // Strict Block: Prevent saving ONLY if on Device tab AND (ID is duplicate OR Checking)
    if (activeTab === 'device') {
       if (posCheckStatus === 'taken') {
          alert("Error: Cannot save settings. The selected POS Terminal ID is already in use.");
          return;
       }
       if (posCheckStatus === 'checking') {
          return; // Silently block or show toast "Please wait..."
       }
    }

    onUpdateSettings(formData);
    setSuccessMsg('Settings saved successfully!');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleLangChange = (lang: Language) => {
    setFormData({ ...formData, language: lang });
  };

  const handleDenominationsChange = (e: React.ChangeEvent<HTMLInputElement>) => {
     // Split by comma, filter non-numbers, sort descending
     const raw = e.target.value.split(',').map(s => parseFloat(s.trim())).filter(n => !isNaN(n)).sort((a,b) => b-a);
     setFormData(prev => ({ ...prev, cashDenominations: raw }));
  };

  // --- Image Upload Helpers ---
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, field: 'receiptLogoUrl' | 'receiptQrCodeUrl') => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > MAX_FILE_SIZE_MB * 1024 * 1024) {
      alert(`File size exceeds ${MAX_FILE_SIZE_MB}MB.`);
      e.target.value = '';
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file (JPG, PNG).');
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, [field]: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = (field: 'receiptLogoUrl' | 'receiptQrCodeUrl') => {
    setFormData(prev => ({ ...prev, [field]: '' }));
    if (field === 'receiptLogoUrl' && logoInputRef.current) logoInputRef.current.value = '';
    if (field === 'receiptQrCodeUrl' && qrInputRef.current) qrInputRef.current.value = '';
  };

  // --- Bank Account Management ---
  const handleAddBank = () => {
    if (!newBank.bankName || !newBank.accountNumber) {
      alert('Please fill in Bank Name and Account Number');
      return;
    }
    const bankEntry: BankAccount = { ...newBank, id: `ba-${Date.now()}` };
    setFormData(prev => ({ ...prev, bankAccounts: [...prev.bankAccounts, bankEntry] }));
    setNewBank({ id: '', bankName: '', accountName: '', accountNumber: '' }); // Reset form
  };

  const handleRemoveBank = (id: string) => {
    setFormData(prev => ({ ...prev, bankAccounts: prev.bankAccounts.filter(b => b.id !== id) }));
  };

  // --- Export / Import Logic ---
  const handleExportData = () => {
    const exportData = {
      meta: {
        exportedAt: new Date().toISOString(),
        version: '1.0'
      },
      settings: formData,
      products,
      sales,
      customers,
      users,
      units,
      categories,
      branches: allBranches,
      posMachines: allPos,
      warehouses,
      locations,
      transfers,
      counts,
      reservations,
      receipts,
      adjustments,
      shifts,
      shiftSchedules,
      promotions
    };

    const jsonString = JSON.stringify(exportData, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = `buildmaster_backup_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const jsonData = JSON.parse(event.target?.result as string);
        if (confirm("This will overwrite your current system data. Are you sure?")) {
           restoreSystemData(jsonData);
           alert("System data restored successfully!");
        }
      } catch (err) {
        alert("Failed to parse backup file. Invalid JSON.");
      }
      // Reset input
      if (importFileRef.current) importFileRef.current.value = '';
    };
    reader.readAsText(file);
  };

  // ... (Test Connection, Local DB, Check POS Availability logic same as before) ...
  const handleTestConnection = () => {
    if (!formData.masterApiUrl) {
       setConnectionStatus('error');
       return;
    }
    setConnectionStatus('testing');
    setTimeout(() => {
       if (formData.masterApiUrl && (formData.masterApiUrl.includes('http') || formData.masterApiUrl.includes('192') || formData.masterApiUrl.includes('localhost'))) {
          setConnectionStatus('success');
       } else {
          setConnectionStatus('error');
       }
    }, 1500);
  };

  const handleTestLocalDb = () => {
    setLocalDbStatus('testing');
    setTimeout(() => {
      if (formData.localDatabase?.host) {
        setLocalDbStatus('success');
      } else {
        setLocalDbStatus('error');
      }
    }, 1500);
  };

  const checkPosAvailability = (posId: string) => {
     if (!posId) {
        setPosCheckStatus('idle');
        return;
     }
     setPosCheckStatus('checking');
     setTimeout(() => {
        if (posId === 'pm2') { 
           setPosCheckStatus('taken');
        } else {
           setPosCheckStatus('available');
        }
     }, 1000); 
  };

  const availablePosMachines = posMachines.filter(p => p.branchId === formData.currentBranchId);

  const isMasterNode = formData.deviceRole === 'Master';
  const isSaveDisabled = activeTab === 'device' && (posCheckStatus === 'taken' || posCheckStatus === 'checking');

  // Preview Helpers
  const getBranchName = (id?: string) => branches.find(b => b.id === id)?.name || 'Main Branch';
  const getPosName = (id?: string) => posMachines.find(p => p.id === id)?.machineNumber || 'POS-01';

  return (
    <div className="flex flex-col h-full">
      {/* ... Header and Tabs ... */}
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">System Settings</h2>
          <p className="text-slate-500">Manage configuration, preferences, and connections.</p>
        </div>
        {successMsg && (
          <div className="bg-green-100 border border-green-200 text-green-700 px-4 py-2 rounded-lg flex items-center shadow-sm animate-fade-in">
            <CheckCircle className="w-5 h-5 mr-2" />
            {successMsg}
          </div>
        )}
      </div>

      <div className="flex flex-col md:flex-row bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 min-h-0">
        {/* Sidebar Tabs */}
        <div className="w-full md:w-72 bg-slate-50 border-b md:border-b-0 md:border-r border-slate-200 flex flex-row md:flex-col overflow-x-auto md:overflow-y-auto shrink-0">
          {TABS.map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;

            let label = tab.label;
            if (tab.id === 'database') {
                label = 'Database & Backup';
            }

            return (
              <button
                key={tab.id}
                onClick={() => handleTabChange(tab.id)}
                className={`flex items-center px-6 py-4 text-sm font-medium transition-all whitespace-nowrap md:whitespace-normal text-left
                  ${isActive 
                    ? 'bg-white text-construction-orange border-b-2 md:border-b-0 md:border-l-4 border-construction-orange shadow-sm md:shadow-none' 
                    : 'text-slate-600 hover:bg-slate-100 hover:text-slate-900 border-l-4 border-transparent'
                  } ${
                    tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'taken' ? 'text-red-500 hover:text-red-600' : ''
                  }`}
              >
                <Icon className={`w-5 h-5 mr-3 shrink-0 ${isActive ? 'text-construction-orange' : (tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'taken' ? 'text-red-500' : 'text-slate-400')}`} />
                {label}
                {tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'taken' && (
                   <AlertTriangle className="w-4 h-4 ml-auto text-red-500" />
                )}
                {tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'checking' && (
                   <Loader2 className="w-4 h-4 ml-auto text-slate-400 animate-spin" />
                )}
              </button>
            );
          })}
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-6 md:p-8 bg-white relative">
          <form onSubmit={handleSave} className="max-w-4xl mx-auto pb-20">

            {/* Company Info */}
            {activeTab === 'company' && (
              <div className="space-y-6 animate-fade-in">
                <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Company Information</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Company Name</label>
                    <input
                      type="text"
                      value={formData.companyName}
                      onChange={e => setFormData({ ...formData, companyName: e.target.value })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Tax ID / Registration No.</label>
                    <input
                      type="text"
                      value={formData.taxId}
                      onChange={e => setFormData({ ...formData, taxId: e.target.value })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                  </div>
                  <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-slate-700 mb-1">Address</label>
                    <textarea
                      value={formData.address}
                      onChange={e => setFormData({ ...formData, address: e.target.value })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 resize-none h-24"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Phone</label>
                    <input
                      type="text"
                      value={formData.phone}
                      onChange={e => setFormData({ ...formData, phone: e.target.value })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                  </div>

                  {/* Monthly Target Input */}
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center">
                       <Target className="w-4 h-4 mr-1 text-slate-500" />
                       Monthly Revenue Target ({formData.currencySymbol})
                    </label>
                    <input
                      type="number"
                      min="0"
                      value={formData.monthlyTarget || 0}
                      onChange={e => setFormData({ ...formData, monthlyTarget: parseFloat(e.target.value) })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 font-bold"
                    />
                    <p className="text-xs text-slate-400 mt-1">Used for dashboard progress tracking.</p>
                  </div>
                </div>
              </div>
            )}

            {/* Other Tabs Logic */}

            {activeTab === 'customer_display' && (
              <div className="space-y-6 animate-fade-in">
                <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Customer Facing Display Configuration</h3>
                <div className="p-4 bg-slate-50 border border-slate-200 rounded-xl flex items-center justify-between mb-6">
                  <div>
                    <h4 className="font-bold text-slate-800">Enable Customer Screen</h4>
                    <p className="text-xs text-slate-500">Allow customers to view cart and pay on a secondary screen</p>
                  </div>
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input type="checkbox" className="sr-only peer" checked={formData.customerDisplay?.enabled} onChange={e => setFormData({ ...formData, customerDisplay: { ...formData.customerDisplay, enabled: e.target.checked } })} />
                    <div className="w-11 h-6 bg-slate-300 peer-focus:outline-none rounded-full peer peer-checked:bg-green-600"></div>
                  </label>
                </div>
                {formData.customerDisplay?.enabled && (
                  <div className="space-y-6">
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Welcome Message</label>
                      <input type="text" value={formData.customerDisplay.welcomeMessage} onChange={e => setFormData({ ...formData, customerDisplay: { ...formData.customerDisplay, welcomeMessage: e.target.value } })} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Slide Interval (Seconds)</label>
                      <input type="number" min="3" max="60" value={formData.customerDisplay.promotionInterval} onChange={e => setFormData({ ...formData, customerDisplay: { ...formData.customerDisplay, promotionInterval: parseInt(e.target.value) || 5 } })} className="w-full md:w-32 px-4 py-2 border border-slate-300 rounded-lg" />
                    </div>
                  </div>
                )}
              </div>
            )}

            {activeTab === 'receipt' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Receipt & Print Settings</h3>
                  <div className="flex flex-col xl:flex-row gap-8">
                     <div className="flex-1 space-y-8">

                        {/* Layout & Format Section */}
                        <section className="space-y-4">
                           <h4 className="font-bold text-slate-700 flex items-center text-sm uppercase tracking-wide">
                              <LayoutList className="w-4 h-4 mr-2" /> Layout & Format
                           </h4>
                           <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                              <div>
                                 <label className="block text-sm font-medium text-slate-700 mb-1">Paper Size</label>
                                 <select value={formData.receiptPaperSize} onChange={e => setFormData({ ...formData, receiptPaperSize: e.target.value as any })} className="w-full px-4 py-2 border border-slate-300 rounded-lg">
                                    <option value="58mm">Thermal 58mm (Small)</option>
                                    <option value="80mm">Thermal 80mm (Standard)</option>
                                    <option value="A4">A4 (Full Page)</option>
                                 </select>
                              </div>
                              <div>
                                 <label className="block text-sm font-medium text-slate-700 mb-1">Print Copies</label>
                                 <input type="number" min="1" max="5" value={formData.receiptCopies || 1} onChange={e => setFormData({ ...formData, receiptCopies: parseInt(e.target.value) || 1 })} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                              </div>
                           </div>
                           <div className="flex items-center space-x-3 bg-slate-50 p-3 rounded-lg border border-slate-200">
                              <input type="checkbox" id="autoPrint" checked={formData.receiptAutoPrint} onChange={e => setFormData({ ...formData, receiptAutoPrint: e.target.checked })} className="w-4 h-4 text-primary-600 rounded" />
                              <label htmlFor="autoPrint" className="text-sm font-medium text-slate-700 cursor-pointer select-none">
                                 Automatically print receipt after sale completion
                              </label>
                           </div>
                        </section>

                        {/* Content & Branding Section */}
                        <section className="space-y-4">
                           <h4 className="font-bold text-slate-700 flex items-center text-sm uppercase tracking-wide">
                              <ImageIcon className="w-4 h-4 mr-2" /> Content & Branding
                           </h4>

                           <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                              {/* Logo Upload */}
                              <div>
                                <label className="block text-sm font-medium text-slate-700 mb-2">Receipt Logo</label>
