                              <button key={lang.code} type="button" onClick={() => handleLangChange(lang.code as any)} className={`flex flex-col items-center justify-center p-4 rounded-xl border-2 transition-all ${formData.language === lang.code ? 'border-primary-500 bg-primary-50 text-primary-700' : 'border-slate-200 hover:bg-slate-50 text-slate-600'}`}>
                                 <span className="text-3xl mb-2">{lang.flag}</span>
                                 <span className="text-sm font-bold">{lang.label}</span>
                              </button>
                           ))}
                        </div>
                     </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-3">Currency Symbol</label>
                        <select value={formData.currencySymbol} onChange={e => setFormData({ ...formData, currencySymbol: e.target.value })} className="w-full px-4 py-2 border border-slate-300 rounded-lg">
                           <option value="$">USD ($)</option>
                           <option value="฿">Thai Baht (฿)</option>
                           <option value="₭">Lao Kip (₭)</option>
                        </select>
                     </div>
                  </div>
               </div>
            )}

            {activeTab === 'interface' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Interface & Display</h3>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-2">Default Items Per Page</label>
                     <select value={formData.defaultItemsPerPage} onChange={e => setFormData({ ...formData, defaultItemsPerPage: parseInt(e.target.value) })} className="w-full md:w-64 px-4 py-2 border border-slate-300 rounded-lg">
                        <option value={10}>10 items</option>
                        <option value={20}>20 items</option>
                        <option value={50}>50 items</option>
                     </select>
                  </div>
               </div>
            )}

            {/* Floating Save Button */}
            <div className="fixed bottom-6 right-6 md:absolute md:bottom-0 md:right-0 md:p-8 md:bg-transparent pointer-events-none">
                <button
                  type="submit"
                  disabled={isSaveDisabled}
                  className={`pointer-events-auto px-6 py-3 font-bold rounded-full md:rounded-lg shadow-lg flex items-center transform transition-all ${
                    isSaveDisabled 
                      ? 'bg-slate-300 text-slate-500 cursor-not-allowed' 
                      : 'bg-construction-orange text-white hover:bg-orange-600 hover:scale-105'
                  }`}
                >
                  {isSaveDisabled && <AlertTriangle className="w-5 h-5 mr-2" />}
                  {!isSaveDisabled && <Save className="w-5 h-5 mr-2" />}
                  {isSaveDisabled 
                     ? (posCheckStatus === 'checking' ? 'Checking ID...' : 'Cannot Save (Invalid ID)') 
                     : 'Save Settings'}
                </button>
            </div>

          </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { SystemSettings, Language, Branch, PosMachine, BankAccount } from '../types';
import { useGlobal } from '../context/GlobalContext';
import { 
  Save, 
  Globe, 
  Building, 
  Printer, 
  Percent, 
  Monitor, 
  Database, 
  LayoutList, 
  CheckCircle, 
  X, 
  ImageIcon, 
  QrCode, 
  Copy, 
  RefreshCw, 
  Activity, 
  Wifi, 
  Server, 
  Link, 
  Tv, 
  HardDrive, 
  ShieldAlert, 
  Lock, 
  AlertTriangle,
  Loader2,
  Download,
  Upload,
  Target,
  Banknote,
  Landmark,
  Trash2,
  PlusCircle,
  Network
} from 'lucide-react';

interface SettingsProps {
  settings: SystemSettings;
  onUpdateSettings: (settings: SystemSettings) => void;
  branches?: Branch[];
  posMachines?: PosMachine[];
}

type SettingsTab = 'company' | 'receipt' | 'financials' | 'device' | 'database' | 'localization' | 'interface' | 'customer_display';

const TABS: { id: SettingsTab; label: string; icon: any }[] = [
  { id: 'company', label: 'Company Information', icon: Building },
  { id: 'receipt', label: 'Receipt & Print Settings', icon: Printer },
  { id: 'financials', label: 'Financials & Tax', icon: Percent },
  { id: 'customer_display', label: 'Customer Display Configuration', icon: Tv },
  { id: 'device', label: 'Device & Network (Master/Slave)', icon: Network },
  { id: 'database', label: 'Database & Backup', icon: Database },
  { id: 'localization', label: 'Localization & Language', icon: Globe },
  { id: 'interface', label: 'Interface & Display', icon: LayoutList },
];

const MAX_FILE_SIZE_MB = 1; // 1MB max for logo/qr

export const Settings: React.FC<SettingsProps> = ({ settings, onUpdateSettings, branches = [], posMachines = [] }) => {
  // Access global context for export/import
  const { 
    products, sales, customers, users, units, categories, 
    branches: allBranches, posMachines: allPos, warehouses, 
    locations, transfers, counts, reservations, receipts, 
    adjustments, shifts, shiftSchedules, promotions,
    restoreSystemData 
  } = useGlobal();

  const [formData, setFormData] = useState<SystemSettings>(settings);
  const [activeTab, setActiveTab] = useState<SettingsTab>('company');
  const [successMsg, setSuccessMsg] = useState('');
  const importFileRef = useRef<HTMLInputElement>(null);

  // Refs for uploads
  const logoInputRef = useRef<HTMLInputElement>(null);
  const qrInputRef = useRef<HTMLInputElement>(null);

  // Bank Account Form
  const [newBank, setNewBank] = useState<BankAccount>({ id: '', bankName: '', accountName: '', accountNumber: '' });

  // Test Connection State
  const [connectionStatus, setConnectionStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');
  const [localDbStatus, setLocalDbStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');

  // POS Availability Check State
  const [posCheckStatus, setPosCheckStatus] = useState<'idle' | 'checking' | 'available' | 'taken'>('idle');

  // Sync state when props change (e.g. data load from mock or API)
  useEffect(() => {
    setFormData(settings);
  }, [settings]);

  // Handle Tab Change with Auto-Reset Logic
  const handleTabChange = (newTab: SettingsTab) => {
    // If we are leaving the 'device' tab AND the ID is currently invalid (taken) OR checking
    if (activeTab === 'device' && (posCheckStatus === 'taken' || posCheckStatus === 'checking')) {
        // Reset Device fields back to original saved settings
        setFormData(prev => ({
            ...prev,
            currentBranchId: settings.currentBranchId,
            currentPosId: settings.currentPosId,
            deviceRole: settings.deviceRole,
            masterApiUrl: settings.masterApiUrl,
            autoSyncInterval: settings.autoSyncInterval
        }));
        // Clear the error status
        setPosCheckStatus('idle');
    }

    setActiveTab(newTab);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    // Strict Block: Prevent saving ONLY if on Device tab AND (ID is duplicate OR Checking)
    if (activeTab === 'device') {
       if (posCheckStatus === 'taken') {
          alert("Error: Cannot save settings. The selected POS Terminal ID is already in use.");
          return;
       }
       if (posCheckStatus === 'checking') {
          return; // Silently block or show toast "Please wait..."
       }
    }

    onUpdateSettings(formData);
    setSuccessMsg('Settings saved successfully!');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleLangChange = (lang: Language) => {
    setFormData({ ...formData, language: lang });
  };

  const handleDenominationsChange = (e: React.ChangeEvent<HTMLInputElement>) => {
     // Split by comma, filter non-numbers, sort descending
     const raw = e.target.value.split(',').map(s => parseFloat(s.trim())).filter(n => !isNaN(n)).sort((a,b) => b-a);
     setFormData(prev => ({ ...prev, cashDenominations: raw }));
  };

  // --- Image Upload Helpers ---
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, field: 'receiptLogoUrl' | 'receiptQrCodeUrl') => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > MAX_FILE_SIZE_MB * 1024 * 1024) {
      alert(`File size exceeds ${MAX_FILE_SIZE_MB}MB.`);
      e.target.value = '';
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file (JPG, PNG).');
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, [field]: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = (field: 'receiptLogoUrl' | 'receiptQrCodeUrl') => {
    setFormData(prev => ({ ...prev, [field]: '' }));
    if (field === 'receiptLogoUrl' && logoInputRef.current) logoInputRef.current.value = '';
    if (field === 'receiptQrCodeUrl' && qrInputRef.current) qrInputRef.current.value = '';
  };

  // --- Bank Account Management ---
  const handleAddBank = () => {
    if (!newBank.bankName || !newBank.accountNumber) {
      alert('Please fill in Bank Name and Account Number');
      return;
    }
    const bankEntry: BankAccount = { ...newBank, id: `ba-${Date.now()}` };
    setFormData(prev => ({ ...prev, bankAccounts: [...prev.bankAccounts, bankEntry] }));
    setNewBank({ id: '', bankName: '', accountName: '', accountNumber: '' }); // Reset form
  };

  const handleRemoveBank = (id: string) => {
    setFormData(prev => ({ ...prev, bankAccounts: prev.bankAccounts.filter(b => b.id !== id) }));
  };

  // --- Export / Import Logic ---
  const handleExportData = () => {
    const exportData = {
      meta: {
        exportedAt: new Date().toISOString(),
        version: '1.0'
      },
      settings: formData,
      products,
      sales,
      customers,
      users,
      units,
      categories,
      branches: allBranches,
      posMachines: allPos,
      warehouses,
      locations,
      transfers,
      counts,
      reservations,
      receipts,
      adjustments,
      shifts,
      shiftSchedules,
      promotions
    };

    const jsonString = JSON.stringify(exportData, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = `buildmaster_backup_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const jsonData = JSON.parse(event.target?.result as string);
        if (confirm("This will overwrite your current system data. Are you sure?")) {
           restoreSystemData(jsonData);
           alert("System data restored successfully!");
        }
      } catch (err) {
        alert("Failed to parse backup file. Invalid JSON.");
      }
      // Reset input
      if (importFileRef.current) importFileRef.current.value = '';
    };
    reader.readAsText(file);
  };

  // ... (Test Connection, Local DB, Check POS Availability logic same as before) ...
  const handleTestConnection = () => {
    if (!formData.masterApiUrl) {
       setConnectionStatus('error');
       return;
    }
    setConnectionStatus('testing');
    setTimeout(() => {
       if (formData.masterApiUrl && (formData.masterApiUrl.includes('http') || formData.masterApiUrl.includes('192') || formData.masterApiUrl.includes('localhost'))) {
          setConnectionStatus('success');
       } else {
          setConnectionStatus('error');
       }
    }, 1500);
  };

  const handleTestLocalDb = () => {
    setLocalDbStatus('testing');
    setTimeout(() => {
      if (formData.localDatabase?.host) {
        setLocalDbStatus('success');
      } else {
        setLocalDbStatus('error');
      }
    }, 1500);
  };

  const checkPosAvailability = (posId: string) => {
     if (!posId) {
        setPosCheckStatus('idle');
        return;
     }
     setPosCheckStatus('checking');
     setTimeout(() => {
        if (posId === 'pm2') { 
           setPosCheckStatus('taken');
        } else {
           setPosCheckStatus('available');
        }
     }, 1000); 
  };

  const availablePosMachines = posMachines.filter(p => p.branchId === formData.currentBranchId);

  const isMasterNode = formData.deviceRole === 'Master';
  const isSaveDisabled = activeTab === 'device' && (posCheckStatus === 'taken' || posCheckStatus === 'checking');

  // Preview Helpers
  const getBranchName = (id?: string) => branches.find(b => b.id === id)?.name || 'Main Branch';
  const getPosName = (id?: string) => posMachines.find(p => p.id === id)?.machineNumber || 'POS-01';

  return (
    <div className="flex flex-col h-full">
      {/* ... Header and Tabs ... */}
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">System Settings</h2>
          <p className="text-slate-500">Manage configuration, preferences, and connections.</p>
        </div>
        {successMsg && (
          <div className="bg-green-100 border border-green-200 text-green-700 px-4 py-2 rounded-lg flex items-center shadow-sm animate-fade-in">
            <CheckCircle className="w-5 h-5 mr-2" />
            {successMsg}
          </div>
        )}
      </div>

      <div className="flex flex-col md:flex-row bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 min-h-0">
        {/* Sidebar Tabs */}
        <div className="w-full md:w-72 bg-slate-50 border-b md:border-b-0 md:border-r border-slate-200 flex flex-row md:flex-col overflow-x-auto md:overflow-y-auto shrink-0">
          {TABS.map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;

            let label = tab.label;
            if (tab.id === 'database') {
                label = 'Database & Backup';
            }

            return (
              <button
                key={tab.id}
                onClick={() => handleTabChange(tab.id)}
                className={`flex items-center px-6 py-4 text-sm font-medium transition-all whitespace-nowrap md:whitespace-normal text-left
                  ${isActive 
                    ? 'bg-white text-construction-orange border-b-2 md:border-b-0 md:border-l-4 border-construction-orange shadow-sm md:shadow-none' 
                    : 'text-slate-600 hover:bg-slate-100 hover:text-slate-900 border-l-4 border-transparent'
                  } ${
                    tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'taken' ? 'text-red-500 hover:text-red-600' : ''
                  }`}
              >
                <Icon className={`w-5 h-5 mr-3 shrink-0 ${isActive ? 'text-construction-orange' : (tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'taken' ? 'text-red-500' : 'text-slate-400')}`} />
                {label}
                {tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'taken' && (
                   <AlertTriangle className="w-4 h-4 ml-auto text-red-500" />
                )}
                {tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'checking' && (
                   <Loader2 className="w-4 h-4 ml-auto text-slate-400 animate-spin" />
                )}
              </button>
            );
          })}
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-6 md:p-8 bg-white relative">
          <form onSubmit={handleSave} className="max-w-4xl mx-auto pb-20">

            {/* Company Info */}
            {activeTab === 'company' && (
              <div className="space-y-6 animate-fade-in">
                <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Company Information</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Company Name</label>
                    <input
                      type="text"
                      value={formData.companyName}
                      onChange={e => setFormData({ ...formData, companyName: e.target.value })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Tax ID / Registration No.</label>
                    <input
                      type="text"
                      value={formData.taxId}
                      onChange={e => setFormData({ ...formData, taxId: e.target.value })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                  </div>
                  <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-slate-700 mb-1">Address</label>
                    <textarea
                      value={formData.address}
                      onChange={e => setFormData({ ...formData, address: e.target.value })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 resize-none h-24"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Phone</label>
                    <input
                      type="text"
                      value={formData.phone}
                      onChange={e => setFormData({ ...formData, phone: e.target.value })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                  </div>

                  {/* Monthly Target Input */}
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center">
                       <Target className="w-4 h-4 mr-1 text-slate-500" />
                       Monthly Revenue Target ({formData.currencySymbol})
                    </label>
                    <input
                      type="number"
                      min="0"
                      value={formData.monthlyTarget || 0}
                      onChange={e => setFormData({ ...formData, monthlyTarget: parseFloat(e.target.value) })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 font-bold"
                    />
                    <p className="text-xs text-slate-400 mt-1">Used for dashboard progress tracking.</p>
                  </div>
                </div>
              </div>
            )}

            {/* Other Tabs Logic */}

            {activeTab === 'customer_display' && (
              <div className="space-y-6 animate-fade-in">
                <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Customer Facing Display Configuration</h3>
                <div className="p-4 bg-slate-50 border border-slate-200 rounded-xl flex items-center justify-between mb-6">
                  <div>
                    <h4 className="font-bold text-slate-800">Enable Customer Screen</h4>
                    <p className="text-xs text-slate-500">Allow customers to view cart and pay on a secondary screen</p>
                  </div>
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input type="checkbox" className="sr-only peer" checked={formData.customerDisplay?.enabled} onChange={e => setFormData({ ...formData, customerDisplay: { ...formData.customerDisplay, enabled: e.target.checked } })} />
                    <div className="w-11 h-6 bg-slate-300 peer-focus:outline-none rounded-full peer peer-checked:bg-green-600"></div>
                  </label>
                </div>
                {formData.customerDisplay?.enabled && (
                  <div className="space-y-6">
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Welcome Message</label>
                      <input type="text" value={formData.customerDisplay.welcomeMessage} onChange={e => setFormData({ ...formData, customerDisplay: { ...formData.customerDisplay, welcomeMessage: e.target.value } })} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Slide Interval (Seconds)</label>
                      <input type="number" min="3" max="60" value={formData.customerDisplay.promotionInterval} onChange={e => setFormData({ ...formData, customerDisplay: { ...formData.customerDisplay, promotionInterval: parseInt(e.target.value) || 5 } })} className="w-full md:w-32 px-4 py-2 border border-slate-300 rounded-lg" />
                    </div>
                  </div>
                )}
              </div>
            )}

            {activeTab === 'receipt' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Receipt & Print Settings</h3>
                  <div className="flex flex-col xl:flex-row gap-8">
                     <div className="flex-1 space-y-8">

                        {/* Layout & Format Section */}
                        <section className="space-y-4">
                           <h4 className="font-bold text-slate-700 flex items-center text-sm uppercase tracking-wide">
                              <LayoutList className="w-4 h-4 mr-2" /> Layout & Format
                           </h4>
                           <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                              <div>
                                 <label className="block text-sm font-medium text-slate-700 mb-1">Paper Size</label>
                                 <select value={formData.receiptPaperSize} onChange={e => setFormData({ ...formData, receiptPaperSize: e.target.value as any })} className="w-full px-4 py-2 border border-slate-300 rounded-lg">
                                    <option value="58mm">Thermal 58mm (Small)</option>
                                    <option value="80mm">Thermal 80mm (Standard)</option>
                                    <option value="A4">A4 (Full Page)</option>
                                 </select>
                              </div>
                              <div>
                                 <label className="block text-sm font-medium text-slate-700 mb-1">Print Copies</label>
                                 <input type="number" min="1" max="5" value={formData.receiptCopies || 1} onChange={e => setFormData({ ...formData, receiptCopies: parseInt(e.target.value) || 1 })} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                              </div>
                           </div>
                           <div className="flex items-center space-x-3 bg-slate-50 p-3 rounded-lg border border-slate-200">
                              <input type="checkbox" id="autoPrint" checked={formData.receiptAutoPrint} onChange={e => setFormData({ ...formData, receiptAutoPrint: e.target.checked })} className="w-4 h-4 text-primary-600 rounded" />
                              <label htmlFor="autoPrint" className="text-sm font-medium text-slate-700 cursor-pointer select-none">
                                 Automatically print receipt after sale completion
                              </label>
                           </div>
                        </section>

                        {/* Content & Branding Section */}
                        <section className="space-y-4">
                           <h4 className="font-bold text-slate-700 flex items-center text-sm uppercase tracking-wide">
                              <ImageIcon className="w-4 h-4 mr-2" /> Content & Branding
                           </h4>

                           <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                              {/* Logo Upload */}
                              <div>
                                <label className="block text-sm font-medium text-slate-700 mb-2">Receipt Logo</label>
                                <div className="flex items-center space-x-4">
                                  {formData.receiptLogoUrl ? (
                                    <div className="relative w-16 h-16 border rounded-lg overflow-hidden bg-slate-50">
                                       <img src={formData.receiptLogoUrl} alt="Logo" className="w-full h-full object-contain" />
                                       <button type="button" onClick={() => handleRemoveImage('receiptLogoUrl')} className="absolute top-0 right-0 bg-red-500 text-white p-0.5 rounded-bl-lg hover:bg-red-600"><Trash2 className="w-3 h-3" /></button>
                                    </div>
                                  ) : (
                                    <div 
                                      onClick={() => logoInputRef.current?.click()}
                                      className="w-16 h-16 border-2 border-dashed border-slate-300 rounded-lg flex items-center justify-center cursor-pointer hover:bg-slate-50 text-slate-400"
                                    >
                                      <Upload className="w-6 h-6" />
                                    </div>
                                  )}
                                  <div className="flex-1">
                                     <button type="button" onClick={() => logoInputRef.current?.click()} className="text-sm text-primary-600 hover:text-primary-700 font-medium">Upload Image</button>
                                     <p className="text-xs text-slate-400">Max 1MB (JPG/PNG)</p>
                                     <input type="file" ref={logoInputRef} className="hidden" accept="image/*" onChange={(e) => handleImageUpload(e, 'receiptLogoUrl')} />
                                  </div>
                                </div>
                              </div>

                              {/* QR Code Upload */}
                              <div>
                                <label className="block text-sm font-medium text-slate-700 mb-2">Payment QR Code</label>
                                <div className="flex items-center space-x-4">
                                  {formData.receiptQrCodeUrl ? (
                                    <div className="relative w-16 h-16 border rounded-lg overflow-hidden bg-slate-50">
                                       <img src={formData.receiptQrCodeUrl} alt="QR" className="w-full h-full object-contain" />
                                       <button type="button" onClick={() => handleRemoveImage('receiptQrCodeUrl')} className="absolute top-0 right-0 bg-red-500 text-white p-0.5 rounded-bl-lg hover:bg-red-600"><Trash2 className="w-3 h-3" /></button>
                                    </div>
                                  ) : (
