                      <button 
                        onClick={() => onDelete(product.id)}
                        className="p-1.5 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* MOBILE CARD VIEW */}
      <div className="md:hidden flex-1 overflow-y-auto bg-slate-50 p-4 space-y-3">
         {products.map((product) => {
            const isLowStock = product.stock < (product.minStock || 20);
            return (
               <div 
                  key={product.id}
                  className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden relative"
               >
                  {isLowStock && <div className="absolute top-0 right-0 w-3 h-3 bg-red-500 rounded-bl-lg z-10" />}

