                <div className={`bg-white border shadow-sm p-4 flex flex-col items-center text-center ${settings.type === 'shelf' ? 'w-64 h-40' : 'w-32 h-20 text-xs'}`}>
                   <div className="font-bold truncate w-full mb-1">{product.name}</div>
                   {settings.showPrice && <div className={`${settings.type === 'shelf' ? 'text-2xl' : 'text-lg'} font-bold`}>{formatPrice(product.price)}</div>}
                   {settings.showSku && <div className="text-slate-500 font-mono text-xs">{product.sku}</div>}
                   <div className="flex-1 w-full bg-slate-800 mt-2 opacity-80 h-8"></div>
                </div>
             </div>
          </div>
          <div className="p-4 border-t border-slate-100 flex justify-end gap-3 bg-slate-50 rounded-b-xl">
             <button onClick={onClose} className="px-4 py-2 border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-100">Cancel</button>
             <button onClick={() => window.print()} className="px-6 py-2 bg-slate-900 text-white rounded-lg hover:bg-slate-800 font-bold flex items-center"><Printer className="w-4 h-4 mr-2" /> Print</button>
          </div>
       </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Product, UnitDefinition, CategoryItem, Warehouse, Sale } from '../types';
import { Search, Plus, Sparkles, Download, Upload, ScanBarcode } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { BarcodeScanner } from './BarcodeScanner';
import { useInventoryStore } from '../store/useInventoryStore';

// Sub-components
import { InventoryList } from './inventory/InventoryList';
import { ProductFormModal } from './inventory/ProductFormModal';
import { ImportModal } from './inventory/ImportModal';
import { InventoryAiModal } from './inventory/InventoryAiModal';
import { LabelPrintModal } from './inventory/LabelPrintModal';

interface InventoryProps {
  products: Product[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  warehouses?: Warehouse[];
  sales: Sale[];
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onAddProduct: (product: Product) => void;
}

export const Inventory: React.FC<InventoryProps> = ({ sales }) => {
  const { settings, t, formatPrice } = useGlobal();

  // Store Access
  const products = useInventoryStore((state) => state.products);
  const units = useInventoryStore((state) => state.units);
  const categories = useInventoryStore((state) => state.categories);
  const addProduct = useInventoryStore((state) => state.addProduct);
  const updateProduct = useInventoryStore((state) => state.updateProduct);
  const deleteProduct = useInventoryStore((state) => state.deleteProduct);

  // State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [isScannerOpen, setIsScannerOpen] = useState(false);

  // Modal States
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | undefined>(undefined);

  const [isImportOpen, setIsImportOpen] = useState(false);
  const [isAiOpen, setIsAiOpen] = useState(false);

  const [labelProduct, setLabelProduct] = useState<Product | null>(null);

  // --- Filtering ---
  const getCategoryName = (idOrName: string) => {
    const cat = categories.find(c => c.id === idOrName);
    return cat ? cat.name : idOrName; 
  };

  const filteredProducts = products.filter(p => {
    const searchLower = searchTerm.toLowerCase();
    const matchesSearch = 
      p.name.toLowerCase().includes(searchLower) || 
      p.sku?.toLowerCase().includes(searchLower) || 
      p.barcode?.includes(searchLower);

    const pCatName = getCategoryName(p.category);
    const filterCatName = filterCategory === 'all' ? 'all' : getCategoryName(filterCategory);
    const matchesCategory = filterCategory === 'all' || p.category === filterCategory || pCatName === filterCatName;

    return matchesSearch && matchesCategory;
  });

  // --- Handlers ---
  const handleEdit = (product: Product) => {
    setEditingProduct(product);
    setIsFormOpen(true);
  };

  const handleAdd = () => {
    setEditingProduct(undefined);
    setIsFormOpen(true);
  };

  const handleFormSubmit = (product: Product) => {
    if (editingProduct) updateProduct(product);
    else addProduct(product);
  };

  const handleImport = (importedProducts: Partial<Product>[], action: 'Create' | 'Update') => {
    importedProducts.forEach(p => {
       // Simple mapping logic
       const newProduct = {
          ...p,
          id: p.id || `P-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
          category: p.category || categories[0]?.id || 'Uncategorized',
          unit: p.unit || 'pc',
          warehouseInventory: [{ warehouseId: 'wh1', quantity: p.stock || 0 }]
       } as Product;

       if (action === 'Update') updateProduct(newProduct);
       else addProduct(newProduct);
    });
  };

  const handleScan = (code: string) => {
    setSearchTerm(code);
    setIsScannerOpen(false);
  };

  const handleExportCSV = () => {
    const headers = ['ID', 'Name', 'Category', 'Price', 'Stock', 'SKU'];
    const csvContent = [
      headers.join(','),
      ...filteredProducts.map(p => [p.id, `"${p.name}"`, getCategoryName(p.category), p.price, p.stock, p.sku].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `inventory_export.csv`;
    link.click();
  };

  return (
    <div className="space-y-6 h-full flex flex-col relative pb-20 md:pb-0">
      {/* Header Actions */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">{t('inventory.title')}</h2>
          <p className="text-slate-500">{t('inventory.subtitle')}</p>
        </div>
        <div className="flex gap-2 overflow-x-auto pb-1 md:pb-0 scrollbar-hide">
          <button onClick={handleExportCSV} className="flex items-center px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 font-medium shadow-sm whitespace-nowrap">
            <Download className="w-4 h-4 md:mr-2" /> <span className="hidden md:inline">Export</span>
          </button>
          <button onClick={() => setIsImportOpen(true)} className="flex items-center px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 font-medium shadow-sm whitespace-nowrap">
            <Upload className="w-4 h-4 md:mr-2" /> <span className="hidden md:inline">Import</span>
          </button>
          <button onClick={() => setIsAiOpen(true)} className="flex items-center px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-lg hover:shadow-lg font-medium shadow-sm whitespace-nowrap">
            <Sparkles className="w-4 h-4 mr-2" /> {t('inventory.aiInsights')}
          </button>
          <button onClick={handleAdd} className="hidden md:flex items-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 font-medium shadow-sm whitespace-nowrap">
            <Plus className="w-4 h-4 mr-2" /> {t('inventory.addProduct')}
          </button>
        </div>
      </div>

      {/* Search & Filter */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4">
        <div className="relative flex-1 flex gap-2">
          <div className="relative flex-1">
             <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
             <input
               type="text"
               placeholder={t('inventory.searchPlaceholder')}
               className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700"
               value={searchTerm}
               onChange={(e) => setSearchTerm(e.target.value)}
             />
          </div>
          <button onClick={() => setIsScannerOpen(true)} className="px-3 py-2 bg-slate-100 rounded-lg border border-slate-200 hover:bg-slate-200 text-slate-600">
             <ScanBarcode className="w-5 h-5" />
          </button>
        </div>
        <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="px-4 py-2 border border-slate-200 rounded-lg bg-white">
          <option value="all">{t('inventory.allCategories')}</option>
          {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
        </select>
      </div>

      {/* Inventory List */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col relative">
        <InventoryList 
          products={filteredProducts} 
          categories={categories} 
          formatPrice={formatPrice} 
          onEdit={handleEdit} 
          onDelete={deleteProduct} 
          onPrintLabel={(p) => setLabelProduct(p)} 
        />
      </div>

      {/* Mobile FAB */}
      <button onClick={handleAdd} className="md:hidden fixed bottom-20 right-6 w-14 h-14 bg-construction-orange text-white rounded-full shadow-lg flex items-center justify-center z-40 hover:bg-orange-600 active:scale-95 transition-all">
          <Plus className="w-8 h-8" />
      </button>

      {/* Modals */}
      <BarcodeScanner isOpen={isScannerOpen} onClose={() => setIsScannerOpen(false)} onScan={handleScan} />

      <ProductFormModal 
        isOpen={isFormOpen} 
        onClose={() => setIsFormOpen(false)} 
        onSubmit={handleFormSubmit} 
        initialData={editingProduct} 
        categories={categories} 
        units={units}
        currencySymbol={settings.currencySymbol}
      />

      <ImportModal 
        isOpen={isImportOpen} 
        onClose={() => setIsImportOpen(false)} 
        onImport={handleImport}
        currencySymbol={settings.currencySymbol}
        formatPrice={formatPrice}
      />

      <InventoryAiModal 
        isOpen={isAiOpen} 
        onClose={() => setIsAiOpen(false)} 
        products={products} 
        sales={sales} 
        formatPrice={formatPrice} 
      />

      {labelProduct && (
        <LabelPrintModal 
          isOpen={!!labelProduct} 
          onClose={() => setLabelProduct(null)} 
          product={labelProduct} 
          formatPrice={formatPrice} 
        />
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Product, ProductVariant, UnitDefinition, CategoryItem } from '../../types';
import { Box, Scale, DollarSign, Layers, X, Plus, Trash2, ImageIcon, Ruler, Check } from 'lucide-react';

interface ProductFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (product: Product) => void;
  initialData?: Product;
  categories: CategoryItem[];
  units: UnitDefinition[];
  currencySymbol: string;
}

const MAX_FILE_SIZE_MB = 5;

export const ProductFormModal: React.FC<ProductFormModalProps> = ({
  isOpen, onClose, onSubmit, initialData, categories, units, currencySymbol
}) => {
  const [activeTab, setActiveTab] = useState<'general' | 'physical' | 'pricing' | 'variants'>('general');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', barcode: '', category: '', price: 0, costPrice: 0,
    stock: 0, minStock: 20, unit: '', physical: { weight: 0, width: 0, height: 0, depth: 0 },
    branchPrices: [], imageUrl: ''
  });

  const [variants, setVariants] = useState<Partial<ProductVariant>[]>([]);

  useEffect(() => {
    if (initialData) {
      setFormData({ ...initialData });
      setVariants(initialData.variants ? initialData.variants.map(v => ({...v})) : []);
    } else {
      setFormData({
        name: '', sku: '', barcode: '', category: categories[0]?.id || '', price: 0, costPrice: 0,
        stock: 0, minStock: 20, unit: units[0]?.symbol || 'pc',
        physical: { weight: 0, width: 0, height: 0, depth: 0 }, branchPrices: [], imageUrl: ''
      });
      setVariants([]);
    }
    setActiveTab('general');
  }, [initialData, isOpen, categories, units]);

  if (!isOpen) return null;

  // Flatten categories for dropdown
  const categoryOptions: { id: string; name: string; level: number }[] = [];
  const buildCatOptions = (parentId: string | null, level: number) => {
    categories.filter(c => c.parentId === parentId).forEach(c => {
      categoryOptions.push({ id: c.id, name: c.name, level });
      buildCatOptions(c.id, level + 1);
    });
  };
  buildCatOptions(null, 0);

  const unitsByCategory = units.reduce((acc, unit) => {
    if (!acc[unit.category]) acc[unit.category] = [];
    acc[unit.category].push(unit);
    return acc;
  }, {} as Record<string, UnitDefinition[]>);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    const isNum = ['price', 'costPrice', 'stock', 'minStock'].includes(name);

    setFormData(prev => ({ ...prev, [name]: isNum ? (parseFloat(value) || 0) : value }));

    if (name === 'price') {
      const newMainPrice = parseFloat(value) || 0;
      setVariants(prev => prev.map(v => {
         const factor = v.conversionFactor || 1;
         return { ...v, price: factor !== 0 ? newMainPrice / factor : 0 };
      }));
    }
  };

  const handlePhysicalChange = (field: string, value: string) => {
    setFormData(prev => ({
      ...prev, physical: { ...prev.physical, [field]: parseFloat(value) || 0 }
    }));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > MAX_FILE_SIZE_MB * 1024 * 1024) {
      alert(`File size exceeds ${MAX_FILE_SIZE_MB}MB.`);
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
    reader.readAsDataURL(file);
  };

  // Variant Logic
  const handleAddVariant = () => {
    const suffix = (variants.length + 1).toString().padStart(3, '0');
    setVariants(prev => [...prev, {
      id: `v-${Date.now()}`,
      name: '', code: `${formData.sku || 'SKU'}-${suffix}`, barcode: formData.barcode ? `${formData.barcode}${suffix}` : '',
      conversionFactor: 1, price: formData.price, costPrice: formData.costPrice
    }]);
  };

  const handleVariantChange = (index: number, field: keyof ProductVariant, value: any) => {
    setVariants(prev => {
      const newVars = [...prev];
      newVars[index] = { ...newVars[index], [field]: field === 'name' ? value : (parseFloat(value) || value) };

      if (field === 'name') {
        const main = units.find(u => u.symbol === formData.unit);
        const sub = units.find(u => u.symbol === value);
        if (main && sub && main.category === sub.category) {
          const factor = main.baseFactor / sub.baseFactor;
          newVars[index].conversionFactor = factor;
          newVars[index].price = (formData.price || 0) / factor;
        }
      }
      return newVars;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.name && formData.unit) {
      const productData: Product = {
        ...initialData,
        ...formData as Product,
        id: initialData?.id || `P-${Date.now()}`,
        variants: variants.length > 0 ? variants as ProductVariant[] : undefined,
        warehouseInventory: initialData?.warehouseInventory || [{ warehouseId: 'wh1', quantity: formData.stock || 0 }],
      };
      onSubmit(productData);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
          <h3 className="text-xl font-bold text-slate-800">{initialData ? 'Edit' : 'Add'} Product</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600"><X className="w-6 h-6" /></button>
        </div>

        <div className="flex border-b border-slate-200 bg-white overflow-x-auto no-scrollbar">
           {[
             { id: 'general', label: 'General Info', icon: Box },
             { id: 'physical', label: 'Physical Attributes', icon: Scale },
             { id: 'pricing', label: 'Pricing & Branches', icon: DollarSign },
             { id: 'variants', label: 'Variants', icon: Layers },
           ].map(tab => (
             <button
               key={tab.id}
               onClick={() => setActiveTab(tab.id as any)}
               className={`flex-1 flex items-center justify-center px-6 py-5 text-lg font-semibold transition-all whitespace-nowrap min-w-fit outline-none focus:outline-none select-none ${
                 activeTab === tab.id ? 'border-b-4 border-construction-orange text-construction-orange bg-orange-50' : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50 border-b-4 border-transparent'
               }`}
             >
               <tab.icon className="w-6 h-6 mr-3" />
               {tab.label}
             </button>
           ))}
        </div>

        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 bg-slate-50/50">
          {activeTab === 'general' && (
            <div className="space-y-6 animate-fade-in bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="md:col-span-2 flex justify-center">
                     <div className="relative group w-32 h-32 rounded-xl overflow-hidden border-2 border-dashed border-slate-300 hover:border-primary-500 transition-colors bg-slate-50">
                        {formData.imageUrl ? <img src={formData.imageUrl} className="w-full h-full object-cover" /> : <div className="w-full h-full flex flex-col items-center justify-center text-slate-400"><ImageIcon className="w-8 h-8 mb-1" /><span className="text-xs">Upload</span></div>}
                        <input type="file" ref={fileInputRef} className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" onChange={handleImageUpload} />
                     </div>
                  </div>
                  <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-slate-700 mb-1">Product Name *</label>
                    <input type="text" name="name" required value={formData.name} onChange={handleInputChange} className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Category *</label>
                    <select name="category" required value={formData.category} onChange={handleInputChange} className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-white">
                       <option value="">Select</option>
                       {categoryOptions.map(cat => <option key={cat.id} value={cat.id}>{'\u00A0'.repeat(cat.level * 3)}{cat.name}</option>)}
                    </select>
                  </div>
                  <div><label className="block text-sm font-medium text-slate-700 mb-1">SKU</label><input type="text" name="sku" value={formData.sku} onChange={handleInputChange} className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 font-mono" /></div>
                  <div><label className="block text-sm font-medium text-slate-700 mb-1">Barcode</label><input type="text" name="barcode" value={formData.barcode} onChange={handleInputChange} className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 font-mono" /></div>
                  <div><label className="block text-sm font-medium text-slate-700 mb-1">Stock</label><input type="number" name="stock" min="0" value={formData.stock} onChange={handleInputChange} className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500" /></div>
                  <div><label className="block text-sm font-medium text-slate-700 mb-1">Unit</label><select name="unit" required value={formData.unit} onChange={handleInputChange} className="w-full px-4 py-2 border border-slate-300 rounded-lg bg-white"><option value="">Select</option>{units.map(u => <option key={u.id} value={u.symbol}>{u.name} ({u.symbol})</option>)}</select></div>
               </div>
            </div>
          )}

          {activeTab === 'physical' && (
             <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm animate-fade-in">
                <h4 className="font-bold text-slate-800 mb-4 flex items-center"><Ruler className="w-5 h-5 mr-2" /> Dimensions & Weight</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div><label className="block text-sm font-medium text-slate-700 mb-1">Weight (kg)</label><input type="number" value={formData.physical?.weight || 0} onChange={e => handlePhysicalChange('weight', e.target.value)} className="w-full px-4 py-2 border border-slate-300 rounded-lg" /></div>
                   <div className="grid grid-cols-3 gap-2">
                      <div><label className="block text-sm font-medium text-slate-700 mb-1">Length</label><input type="number" value={formData.physical?.depth || 0} onChange={e => handlePhysicalChange('depth', e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded-lg" /></div>
                      <div><label className="block text-sm font-medium text-slate-700 mb-1">Width</label><input type="number" value={formData.physical?.width || 0} onChange={e => handlePhysicalChange('width', e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded-lg" /></div>
                      <div><label className="block text-sm font-medium text-slate-700 mb-1">Height</label><input type="number" value={formData.physical?.height || 0} onChange={e => handlePhysicalChange('height', e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded-lg" /></div>
                   </div>
                </div>
             </div>
          )}

          {activeTab === 'pricing' && (
            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm animate-fade-in">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                     <label className="block text-sm font-bold text-slate-800 mb-2">Selling Price</label>
                     <div className="relative"><span className="absolute left-3 top-2.5 text-slate-400 font-bold">{currencySymbol}</span><input type="number" name="price" min="0" step="0.01" value={formData.price} onChange={handleInputChange} className="w-full pl-8 px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 text-lg font-bold" /></div>
                  </div>
                  <div>
                     <label className="block text-sm font-bold text-slate-800 mb-2">Cost Price</label>
                     <div className="relative"><span className="absolute left-3 top-2.5 text-slate-400 font-bold">{currencySymbol}</span><input type="number" name="costPrice" min="0" step="0.01" value={formData.costPrice} onChange={handleInputChange} className="w-full pl-8 px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 text-lg" /></div>
                  </div>
               </div>
            </div>
          )}

          {activeTab === 'variants' && (
            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm animate-fade-in">
               <div className="flex justify-between items-center mb-4">
                 <h4 className="font-bold text-slate-800">Product Variants</h4>
                 <button type="button" onClick={handleAddVariant} className="text-sm flex items-center text-primary-600 font-medium hover:text-primary-700 bg-primary-50 px-3 py-1.5 rounded-lg"><Plus className="w-4 h-4 mr-1" /> Add Variant</button>
               </div>
               <div className="space-y-4">
                  {variants.map((v, i) => (
                     <div key={i} className="bg-slate-50 p-4 rounded-xl border border-slate-200 relative group">
                        <button type="button" onClick={() => setVariants(prev => prev.filter((_, idx) => idx !== i))} className="absolute top-2 right-2 p-1 text-slate-400 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                        <div className="grid grid-cols-3 gap-4">
                           <select value={v.name} onChange={e => handleVariantChange(i, 'name', e.target.value)} className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm bg-white">
                              <option value="">Unit</option>
                              {Object.entries(unitsByCategory).map(([c, uList]) => (
                                <optgroup key={c} label={c}>
                                  {(uList as UnitDefinition[]).map(u => <option key={u.id} value={u.symbol}>{u.name}</option>)}
                                </optgroup>
                              ))}
                           </select>
                           <input type="text" value={v.code} onChange={e => handleVariantChange(i, 'code', e.target.value)} placeholder="SKU" className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm" />
                           <input type="number" value={v.price} onChange={e => handleVariantChange(i, 'price', e.target.value)} placeholder="Price" className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm font-bold" />
                        </div>
                     </div>
                  ))}
                  {variants.length === 0 && <div className="text-center py-8 text-slate-400 border-2 border-dashed border-slate-100 rounded-lg">No variants added.</div>}
               </div>
            </div>
          )}
        </form>

        <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-white shrink-0">
            <button onClick={onClose} className="px-5 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg">Cancel</button>
            <button type="button" onClick={handleSubmit} className="px-5 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 shadow-sm flex items-center"><Check className="w-4 h-4 mr-2" /> Save</button>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { ArrowRightLeft, Truck, SlidersHorizontal, CheckSquare, CalendarClock } from 'lucide-react';

interface StockNavigationProps {
