import React from 'react';
import { Warehouse, DocumentStatus } from '../../types';
import { Edit2, Trash2, PlayCircle, FileText, Package, Calendar } from 'lucide-react';

interface StockListProps {
  activeTab: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment';
  items: any[];
  warehouses: Warehouse[];
  onOpenModal: (item: any) => void;
  onComplete: (item: any) => void;
  onDelete: (id: string) => void;
}

export const StockList: React.FC<StockListProps> = ({
  activeTab,
  items,
  warehouses,
  onOpenModal,
  onComplete,
  onDelete
}) => {
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Completed': return 'bg-green-100 text-green-700 border-green-200';
      case 'Approved': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'Cancelled': return 'bg-red-100 text-red-700 border-red-200';
      default: return 'bg-orange-100 text-orange-700 border-orange-200';
    }
  };

  const getDetails = (item: any) => {
    switch (activeTab) {
      case 'transfer': return `From: ${warehouses.find(w => w.id === item.sourceWarehouseId)?.name} To: ${warehouses.find(w => w.id === item.targetWarehouseId)?.name}`;
      case 'receipt': return `Vendor: ${item.vendorName} (Ref: ${item.vendorInvoiceNo})`;
      case 'adjustment': return `Reason: ${item.reason} @ ${warehouses.find(w => w.id === item.warehouseId)?.name}`;
      case 'count': return `Counter: ${item.counterName} @ ${warehouses.find(w => w.id === item.warehouseId)?.name}`;
      case 'reservation': return `Customer: ${item.customerName} (Exp: ${new Date(item.expiryDate).toLocaleDateString()})`;
      default: return '';
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
      {/* DESKTOP TABLE */}
      <div className="hidden md:block overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-100">
            <tr>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase whitespace-nowrap">Ref No / Date</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase whitespace-nowrap">Details</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center whitespace-nowrap">Items</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center whitespace-nowrap">Status</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right whitespace-nowrap">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {items.map((item) => (
              <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className="font-bold text-slate-800">{item.referenceNo}</div>
                  <div className="text-xs text-slate-500">{new Date(item.date).toLocaleDateString()}</div>
                </td>
                <td className="px-6 py-4 text-sm text-slate-600 min-w-[200px]">
                  {getDetails(item)}
                </td>
                <td className="px-6 py-4 text-center whitespace-nowrap">
                  <span className="bg-slate-100 px-2 py-1 rounded text-xs font-bold text-slate-600">
                    {item.items?.length || 0} items
                  </span>
                </td>
                <td className="px-6 py-4 text-center whitespace-nowrap">
                  <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold border ${getStatusColor(item.status)}`}>
                    {item.status}
                  </span>
                </td>
                <td className="px-6 py-4 text-right whitespace-nowrap">
                  <div className="flex justify-end space-x-2 items-center">
                    {item.status === 'Approved' && (
                      <button 
                        onClick={(e) => { e.stopPropagation(); onComplete(item); }}
                        className="flex items-center px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-xs font-bold shadow-sm"
                      >
                        <PlayCircle className="w-3 h-3 mr-1" /> Complete
                      </button>
                    )}
                    <button onClick={(e) => { e.stopPropagation(); onOpenModal(item); }} className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-slate-100 rounded">
                      {item.status === 'Draft' ? <Edit2 className="w-4 h-4" /> : <FileText className="w-4 h-4" />}
                    </button>
                    {(item.status === 'Draft' || item.status === 'Approved') && (
                      <button onClick={(e) => { e.stopPropagation(); onDelete(item.id); }} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-slate-100 rounded">
                        <Trash2 className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* MOBILE CARD VIEW */}
      <div className="md:hidden flex-1 overflow-y-auto bg-slate-50 p-4 space-y-3">
         {items.map((item) => (
            <div 
              key={item.id} 
              onClick={() => onOpenModal(item)}
              className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 relative"
            >
               <div className="flex justify-between items-start mb-2">
                  <div>
                     <div className="flex items-center">
                        <span className="font-bold text-slate-800 text-lg mr-2">{item.referenceNo}</span>
                     </div>
                     <div className="flex items-center text-xs text-slate-500 mt-1">
                        <Calendar className="w-3 h-3 mr-1" />
                        {new Date(item.date).toLocaleDateString()}
                     </div>
                  </div>
                  <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[10px] font-bold uppercase border ${getStatusColor(item.status)}`}>
                    {item.status}
                  </span>
               </div>

               <div className="text-sm text-slate-600 mb-3 bg-slate-50 p-2 rounded border border-slate-100">
                  {activeTab === 'transfer' && (
                     <div className="flex flex-col gap-1">
                        <span className="flex items-center"><span className="w-12 text-xs font-bold text-slate-400 uppercase">From</span> {warehouses.find(w => w.id === item.sourceWarehouseId)?.name}</span>
                        <span className="flex items-center"><span className="w-12 text-xs font-bold text-slate-400 uppercase">To</span> {warehouses.find(w => w.id === item.targetWarehouseId)?.name}</span>
                     </div>
                  )}
                  {activeTab !== 'transfer' && (
                     <span>{getDetails(item)}</span>
                  )}
               </div>

               <div className="flex justify-between items-center border-t border-slate-100 pt-3">
                  <div className="text-xs font-bold text-slate-500 flex items-center">
                     <Package className="w-4 h-4 mr-1" />
                     {item.items?.length || 0} Items
                  </div>

                  <div className="flex space-x-3">
                     {item.status === 'Approved' && (
                        <button 
                           onClick={(e) => { e.stopPropagation(); onComplete(item); }}
                           className="px-3 py-1.5 bg-green-600 text-white rounded-lg text-xs font-bold shadow-sm"
                        >
                           Complete
                        </button>
                     )}
                     {(item.status === 'Draft' || item.status === 'Approved') && (
                        <button 
                           onClick={(e) => { e.stopPropagation(); onDelete(item.id); }}
                           className="p-1.5 text-slate-400 hover:text-red-500 bg-slate-50 rounded-lg border border-slate-200"
                        >
                           <Trash2 className="w-4 h-4" />
                        </button>
                     )}
                  </div>
               </div>
            </div>
         ))}
         {items.length === 0 && (
            <div className="text-center py-12 text-slate-400">
               <Package className="w-12 h-12 mx-auto mb-2 opacity-20" />
               <p>No documents found.</p>
            </div>
         )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Warehouse, Product, StockItem } from '../../types';
import { Edit2, Plus, X, AlertCircle, Trash2, CheckCircle, PlayCircle } from 'lucide-react';

interface StockDocumentModalProps {
  isOpen: boolean;
  onClose: () => void;
  activeTab: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment';
  editingId: string | null;
  initialData: any;
  warehouses: Warehouse[];
  products: Product[];
  onSave: (data: any) => void;
  onComplete: (data: any) => void;
}

export const StockDocumentModal: React.FC<StockDocumentModalProps> = ({
  isOpen, onClose, activeTab, editingId, initialData, warehouses, products, onSave, onComplete
}) => {
  const [formData, setFormData] = useState<any>(initialData);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setFormData(initialData);
    setError(null);
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const isReadOnly = formData.status !== 'Draft';

  const validateForm = () => {
    if (!formData.date) return 'Date is required';

    if (activeTab === 'transfer') {
        if (!formData.sourceWarehouseId) return 'Source Warehouse is required';
        if (!formData.targetWarehouseId) return 'Target Warehouse is required';
        if (formData.sourceWarehouseId === formData.targetWarehouseId) return 'Source and Target warehouses cannot be the same';
    }

    if (['adjustment', 'count', 'receipt', 'reservation'].includes(activeTab)) {
        if (!formData.warehouseId) return 'Warehouse is required';
    }

    if (activeTab === 'receipt' && !formData.vendorName) return 'Vendor Name is required';

    if (activeTab === 'reservation') {
        if (!formData.customerName) return 'Customer Name is required';
        if (!formData.expiryDate) return 'Expiry Date is required';
    }

    if (activeTab === 'count' && !formData.counterName) return 'Counter Name is required';

    if (activeTab === 'adjustment' && !formData.reason) return 'Reason is required';

    return null;
  };

  const handleSaveClick = () => {
    const err = validateForm();
    if (err) {
      setError(err);
      return;
    }
    onSave(formData);
  };

  const handleAddItem = () => {
    if (!products.length) return;
    const p = products[0];
    const newItem: StockItem = {
      productId: p.id,
      productName: p.name,
      unit: p.unit,
      quantity: 1
    };
    setFormData({ ...formData, items: [...(formData.items || []), newItem] });
  };

  const handleUpdateItem = (index: number, field: string, value: any) => {
    const newItems = [...formData.items];
    if (field === 'productId') {
        const p = products.find(prod => prod.id === value);
        if (p) {
            newItems[index] = { ...newItems[index], productId: p.id, productName: p.name, unit: p.unit };
        }
    } else {
        newItems[index] = { ...newItems[index], [field]: value };
    }
    setFormData({ ...formData, items: newItems });
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...formData.items];
    newItems.splice(index, 1);
    setFormData({ ...formData, items: newItems });
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[60] p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[95vh] flex flex-col overflow-hidden animate-fade-in">
        <div className="p-4 md:p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
          <h3 className="text-lg md:text-xl font-bold text-slate-800 uppercase flex items-center">
            {editingId ? <Edit2 className="w-5 h-5 mr-2 text-blue-500" /> : <Plus className="w-5 h-5 mr-2 text-green-500" />}
            {editingId ? 'Edit' : 'New'} {activeTab}
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto">
          <div className="p-4 md:p-6 space-y-4">

            {error && (
              <div className="p-3 bg-red-50 border border-red-100 rounded-lg text-red-600 text-sm flex items-center">
                <AlertCircle className="w-4 h-4 mr-2 flex-shrink-0" />
                {error}
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Date *</label>
                  <input 
                    type="date" 
                    disabled={isReadOnly}
                    required 
                    value={formData.date ? new Date(formData.date).toISOString().split('T')[0] : ''} 
                    onChange={e => setFormData({...formData, date: e.target.value})} 
                    className="w-full px-4 py-2 border border-slate-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" 
                  />
               </div>
               <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Ref No</label>
                  <input 
                    type="text" 
                    disabled={isReadOnly}
                    value={formData.referenceNo} 
                    onChange={e => setFormData({...formData, referenceNo: e.target.value})} 
                    className="w-full px-4 py-2 border border-slate-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" 
                    placeholder="Auto-generated if empty" 
                  />
               </div>
            </div>

            {/* Dynamic Fields */}
            {activeTab === 'transfer' && (
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Source Warehouse *</label>
                     <select 
                        disabled={isReadOnly}
                        required 
                        value={formData.sourceWarehouseId} 
                        onChange={e => setFormData({...formData, sourceWarehouseId: e.target.value})} 
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg bg-white disabled:bg-slate-100 disabled:text-slate-500"
                     >
                        <option value="">Select Source</option>
                        {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                     </select>
                  </div>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Target Warehouse *</label>
                     <select 
                        disabled={isReadOnly}
                        required 
                        value={formData.targetWarehouseId} 
                        onChange={e => setFormData({...formData, targetWarehouseId: e.target.value})} 
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg bg-white disabled:bg-slate-100 disabled:text-slate-500"
                     >
                        <option value="">Select Target</option>
                        {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                     </select>
                  </div>
               </div>
            )}

            {(activeTab === 'adjustment' || activeTab === 'count' || activeTab === 'receipt' || activeTab === 'reservation') && (
               <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Warehouse *</label>
                  <select 
                    disabled={isReadOnly}
                    required 
                    value={formData.warehouseId} 
                    onChange={e => setFormData({...formData, warehouseId: e.target.value})} 
                    className="w-full px-4 py-2 border border-slate-300 rounded-lg bg-white disabled:bg-slate-100 disabled:text-slate-500"
                  >
                     <option value="">Select Warehouse</option>
                     {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                  </select>
               </div>
            )}

            {activeTab === 'receipt' && (
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Vendor Name *</label>
                     <input 
                        disabled={isReadOnly}
                        type="text" 
                        required 
                        value={formData.vendorName} 
                        onChange={e => setFormData({...formData, vendorName: e.target.value})} 
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" 
                     />
                  </div>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Vendor Invoice No</label>
                     <input 
                        disabled={isReadOnly}
                        type="text" 
                        value={formData.vendorInvoiceNo} 
                        onChange={e => setFormData({...formData, vendorInvoiceNo: e.target.value})} 
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" 
                     />
                  </div>
               </div>
            )}

            {activeTab === 'reservation' && (
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Customer Name *</label>
                     <input 
                        disabled={isReadOnly}
                        type="text" 
                        required 
                        value={formData.customerName} 
                        onChange={e => setFormData({...formData, customerName: e.target.value})} 
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" 
                     />
                  </div>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Expiry Date *</label>
                     <input 
                        disabled={isReadOnly}
                        type="date" 
                        required 
                        value={formData.expiryDate ? new Date(formData.expiryDate).toISOString().split('T')[0] : ''} 
                        onChange={e => setFormData({...formData, expiryDate: e.target.value})} 
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" 
                     />
                  </div>
               </div>
            )}

            {activeTab === 'count' && (
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Counter Name *</label>
                     <input 
                        disabled={isReadOnly}
                        type="text" 
                        required 
                        value={formData.counterName} 
                        onChange={e => setFormData({...formData, counterName: e.target.value})} 
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" 
                     />
                  </div>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Reason</label>
                     <input 
                        disabled={isReadOnly}
                        type="text" 
                        value={formData.reason} 
                        onChange={e => setFormData({...formData, reason: e.target.value})} 
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" 
                     />
                  </div>
               </div>
            )}

            {activeTab === 'adjustment' && (
               <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Reason *</label>
                  <input 
                    disabled={isReadOnly}
                    type="text" 
                    required 
                    value={formData.reason} 
                    onChange={e => setFormData({...formData, reason: e.target.value})} 
                    className="w-full px-4 py-2 border border-slate-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" 
                  />
               </div>
            )}

            {/* Items Section */}
            <div className="border-t border-slate-100 pt-4">
               <div className="flex justify-between items-center mb-2">
                  <h4 className="font-bold text-slate-700">Items</h4>
                  {!isReadOnly && (
                    <button type="button" onClick={handleAddItem} className="text-sm text-blue-600 hover:underline flex items-center font-medium bg-blue-50 px-3 py-1.5 rounded-lg"><Plus className="w-4 h-4 mr-1"/> Add Item</button>
                  )}
               </div>
               <div className="space-y-3">
                  {formData.items?.map((item: any, idx: number) => (
                     <div key={idx} className="flex flex-col md:flex-row gap-3 items-start md:items-center bg-slate-50 p-3 rounded-lg border border-slate-200">
                        <select 
                           disabled={isReadOnly}
                           value={item.productId} 
                           onChange={e => handleUpdateItem(idx, 'productId', e.target.value)} 
                           className="w-full md:flex-1 px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white disabled:bg-slate-100"
                        >
                           {products.map(p => <option key={p.id} value={p.id}>{p.name} ({p.unit})</option>)}
                        </select>

                        <div className="flex gap-2 w-full md:w-auto items-center">
                           {activeTab === 'count' ? (
                              <div className="flex-1 md:w-24">
                                 <input 
                                    disabled={isReadOnly}
                                    type="number" 
                                    value={item.countedQuantity || 0} 
                                    onChange={e => handleUpdateItem(idx, 'countedQuantity', parseFloat(e.target.value))} 
                                    className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm disabled:bg-slate-100 font-medium"
                                    placeholder="Count"
                                 />
                              </div>
                           ) : (
                              <div className="flex-1 md:w-24">
                                 <input 
                                    disabled={isReadOnly}
                                    type="number" 
                                    value={item.quantity || 0} 
                                    onChange={e => handleUpdateItem(idx, 'quantity', parseFloat(e.target.value))} 
                                    className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm disabled:bg-slate-100 font-medium"
                                    placeholder="Qty"
                                 />
                              </div>
                           )}

                           {!isReadOnly && (
                               <button type="button" onClick={() => handleRemoveItem(idx)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg border border-transparent hover:border-red-200"><Trash2 className="w-4 h-4"/></button>
                           )}
                        </div>
                     </div>
                  ))}
                  {(!formData.items || formData.items.length === 0) && (
                     <div className="text-center py-8 text-slate-400 text-sm italic border-2 border-dashed border-slate-100 rounded-lg">No items added yet.</div>
                  )}
               </div>
            </div>
          </div>
        </div>

        <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-slate-50 shrink-0">
          <button
            type="button"
            onClick={onClose}
            className="px-5 py-2.5 text-slate-600 font-medium hover:bg-slate-200 rounded-lg transition-colors"
          >
            {isReadOnly ? 'Close' : 'Cancel'}
          </button>

          {formData.status === 'Draft' && (
             <button
                type="button"
                onClick={handleSaveClick}
                className="px-6 py-2.5 bg-construction-orange text-white font-bold rounded-lg hover:bg-orange-600 transition-colors shadow-sm"
             >
                Save Draft
             </button>
          )}

          {formData.status === 'Approved' && (
             <button
                type="button"
                onClick={() => onComplete(formData)}
                className="flex items-center px-6 py-2.5 bg-green-600 text-white font-bold rounded-lg hover:bg-green-700 transition-colors shadow-sm"
             >
                <PlayCircle className="w-4 h-4 mr-2" />
                Complete
             </button>
          )}

          {(formData.status === 'Completed' || formData.status === 'Cancelled') && (
             <span className={`flex items-center font-bold px-4 py-2 ${formData.status === 'Completed' ? 'text-green-600 bg-green-50 rounded-lg' : 'text-red-600 bg-red-50 rounded-lg'}`}>
                {formData.status === 'Completed' ? <CheckCircle className="w-5 h-5 mr-2" /> : <AlertCircle className="w-5 h-5 mr-2" />} 
                {formData.status}
             </span>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { 
  Warehouse, Product, StockTransfer, StockCount, StockReservation, StockReceipt, StockAdjustment, 
  DocumentStatus 
} from '../types';
import { Plus } from 'lucide-react';
import { StockNavigation } from './stock/StockNavigation';
import { StockList } from './stock/StockList';
import { StockDocumentModal } from './stock/StockDocumentModal';

interface StockManagementProps {
  warehouses: Warehouse[];
  products: Product[];
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  defaultItemsPerPage: number;
  onUpdateTransfer: (t: StockTransfer) => void;
  onDeleteTransfer: (id: string) => void;
  onUpdateCount: (c: StockCount) => void;
  onDeleteCount: (id: string) => void;
  onUpdateReservation: (r: StockReservation) => void;
  onDeleteReservation: (id: string) => void;
  onUpdateReceipt: (r: StockReceipt) => void;
  onDeleteReceipt: (id: string) => void;
  onUpdateAdjustment: (a: StockAdjustment) => void;
  onDeleteAdjustment: (id: string) => void;
  onStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;
}

export const StockManagement: React.FC<StockManagementProps> = ({
  warehouses, products, transfers, counts, reservations, receipts, adjustments,
  onUpdateTransfer, onDeleteTransfer,
  onUpdateCount, onDeleteCount,
  onUpdateReservation, onDeleteReservation,
  onUpdateReceipt, onDeleteReceipt,
  onUpdateAdjustment, onDeleteAdjustment,
  onStatusChange
}) => {
  const [activeTab, setActiveTab] = useState<'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment'>('transfer');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<any>({}); 

  // Init form based on tab
  const initForm = () => {
    const common = {
      referenceNo: '',
      date: new Date().toISOString().split('T')[0],
      status: 'Draft',
      items: []
    };

    switch(activeTab) {
      case 'transfer': return { ...common, sourceWarehouseId: '', targetWarehouseId: '' };
      case 'count': return { ...common, warehouseId: '', counterName: '', reason: '' };
      case 'reservation': return { ...common, warehouseId: '', customerName: '', expiryDate: '' };
      case 'receipt': return { ...common, warehouseId: '', vendorName: '', vendorInvoiceNo: '', totalCost: 0 };
      case 'adjustment': return { ...common, warehouseId: '', reason: '' };
    }
  };

  const handleOpenModal = (item?: any) => {
    if (item) {
      setEditingId(item.id);
      setFormData({ ...item });
    } else {
      setEditingId(null);
      setFormData(initForm());
    }
    setIsModalOpen(true);
  };

  const handleSave = (data: any) => {
    const id = editingId || (activeTab === 'transfer' ? `TR-${Date.now()}` : 
                             activeTab === 'count' ? `SC-${Date.now()}` :
                             activeTab === 'reservation' ? `RS-${Date.now()}` :
                             activeTab === 'receipt' ? `RC-${Date.now()}` :
                             `AD-${Date.now()}`);

    // Always save as Draft initially or preserve existing status if editing
    const currentStatus = data.status === 'Completed' || data.status === 'Approved' ? data.status : 'Draft';
    const payload = { ...data, id, status: currentStatus };

    // Auto-generate Ref No if missing
    if (!payload.referenceNo) {
        payload.referenceNo = `${activeTab.toUpperCase().slice(0,2)}-${new Date().getFullYear()}${new Date().getMonth()+1}-${Math.floor(Math.random()*1000)}`;
    }

    switch (activeTab) {
      case 'transfer': onUpdateTransfer(payload); break;
      case 'count': onUpdateCount(payload); break;
      case 'reservation': onUpdateReservation(payload); break;
      case 'receipt': onUpdateReceipt(payload); break;
      case 'adjustment': onUpdateAdjustment(payload); break;
    }
    setIsModalOpen(false);
  };

  const handleComplete = (item: any) => {
    if (window.confirm('Confirm completion? This will update stock levels permanently.')) {
      onStatusChange(activeTab, item.id, 'Completed');
      if (isModalOpen) setIsModalOpen(false);
    }
  };

  const handleDelete = (id: string) => {
    if (!confirm('Delete this document?')) return;
    switch(activeTab) {
      case 'transfer': onDeleteTransfer(id); break;
      case 'count': onDeleteCount(id); break;
      case 'reservation': onDeleteReservation(id); break;
      case 'receipt': onDeleteReceipt(id); break;
      case 'adjustment': onDeleteAdjustment(id); break;
    }
  };

  const getList = () => {
    switch(activeTab) {
      case 'transfer': return transfers;
      case 'count': return counts;
      case 'reservation': return reservations;
      case 'receipt': return receipts;
      case 'adjustment': return adjustments;
      default: return [];
    }
  };

  return (
    <div className="space-y-6 h-full flex flex-col pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Stock Management</h2>
          <p className="text-slate-500">Manage stock movements, counts, and adjustments.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="flex items-center justify-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 transition-colors font-medium shadow-sm">
          <Plus className="w-4 h-4 mr-2" />
          Create Document
        </button>
      </div>

      <StockNavigation activeTab={activeTab} setActiveTab={setActiveTab} />

      <StockList 
        activeTab={activeTab}
        items={getList()}
        warehouses={warehouses}
        onOpenModal={handleOpenModal}
        onComplete={handleComplete}
        onDelete={handleDelete}
      />

      <StockDocumentModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        activeTab={activeTab}
        editingId={editingId}
        initialData={formData}
        warehouses={warehouses}
        products={products}
        onSave={handleSave}
        onComplete={handleComplete}
      />
    </div>
  );
};

