import React, { useState } from 'react';
import { Branch, User, ShiftSchedule } from '../../types';
import { ArrowRightLeft, Repeat, X } from 'lucide-react';

interface ScheduleModalProps {
  isOpen: boolean;
  onClose: () => void;
  branches: Branch[];
  users: User[];
  editingScheduleId: string | null;
  shiftSchedules: ShiftSchedule[];
  planningDate: string;
  selectedBranchId: string;
  calendarDate: Date;
  onSave: (schedule: any, isRecurring: boolean, recurringDays: number[]) => void;
  onRevertSwap: (id: string) => void;
}

export const ScheduleModal: React.FC<ScheduleModalProps> = ({
  isOpen, onClose, branches, users, editingScheduleId, shiftSchedules, planningDate, selectedBranchId, calendarDate, onSave, onRevertSwap
}) => {
  const [isRecurringMode, setIsRecurringMode] = useState(false);
  const [recurringDays, setRecurringDays] = useState<number[]>([1, 2, 3, 4, 5]);

  const editingSchedule = shiftSchedules.find(s => s.id === editingScheduleId);

  const [formData, setFormData] = useState({
    userId: editingSchedule?.userId || '',
    branchId: editingSchedule?.branchId || selectedBranchId,
    startTime: editingSchedule?.startTime || '09:00',
    endTime: editingSchedule?.endTime || '18:00',
    note: editingSchedule?.note || ''
  });

  if (!isOpen) return null;

  const handleToggleDay = (dayIndex: number) => {
    if (recurringDays.includes(dayIndex)) {
        setRecurringDays(prev => prev.filter(d => d !== dayIndex));
    } else {
        setRecurringDays(prev => [...prev, dayIndex].sort());
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(formData, isRecurringMode, recurringDays);
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[70] p-4 backdrop-blur-sm">
        <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
           <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="font-bold text-slate-800 flex items-center">
                {editingScheduleId ? (
                  <>
                    <ArrowRightLeft className="w-5 h-5 mr-2 text-blue-600" />
                    Manage / Swap Shift
                  </>
                ) : (
                  'Add Schedule Shift'
                )}
              </h3>
              <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
                 <X className="w-5 h-5" />
              </button>
           </div>

           <div className="flex-1 overflow-y-auto p-6">
              <form onSubmit={handleSubmit} className="space-y-5">

                 {/* Mode Toggle (Only for New) */}
                 {!editingScheduleId && (
                    <div className="flex bg-slate-100 p-1 rounded-lg mb-4">
                       <button 
                          type="button"
                          onClick={() => setIsRecurringMode(false)}
                          className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${!isRecurringMode ? 'bg-white shadow-sm text-slate-800' : 'text-slate-500'}`}
                       >
                          Single Day
                       </button>
                       <button 
                          type="button"
                          onClick={() => setIsRecurringMode(true)}
                          className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${isRecurringMode ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}
                       >
                          <Repeat className="w-3 h-3 inline mr-1" /> Weekly Pattern
                       </button>
                    </div>
                 )}

                 {/* Date Selection Logic */}
                 {isRecurringMode ? (
                    <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 space-y-3">
                       <div className="flex items-center justify-between">
                          <h4 className="text-xs font-bold text-blue-800 uppercase tracking-wide">Pattern Settings</h4>
                          <span className="text-[10px] font-bold bg-blue-100 text-blue-600 px-2 py-0.5 rounded">
                             Applying for {calendarDate.toLocaleString('default', { month: 'long', year: 'numeric' })}
                          </span>
                       </div>

                       <div>
                          <label className="block text-xs font-bold text-slate-500 mb-2">Repeat On Days</label>
                          <div className="flex justify-between gap-1">
                             {['S','M','T','W','T','F','S'].map((day, idx) => (
                                <button
                                   key={idx}
                                   type="button"
                                   onClick={() => handleToggleDay(idx)}
                                   className={`w-8 h-8 rounded-full text-xs font-bold transition-all ${recurringDays.includes(idx) ? 'bg-blue-600 text-white' : 'bg-white border border-slate-200 text-slate-400 hover:border-blue-300'}`}
                                >
                                   {day}
                                </button>
                             ))}
                          </div>
                          <p className="text-[10px] text-blue-600 mt-2 italic">
                             * This will generate shifts for the entire selected month automatically.
                          </p>
                       </div>
                    </div>
                 ) : (
                    <div>
                       <label className="block text-sm font-medium text-slate-700 mb-1">Date</label>
                       <input 
                          type="date"
                          disabled={!!editingScheduleId}
                          defaultValue={editingSchedule ? editingSchedule.date : planningDate}
                          className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-white disabled:bg-slate-100"
                          readOnly={!!editingScheduleId}
                       />
                    </div>
                 )}

                 {/* Branch Context */}
                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Branch</label>
                    <select 
                       required
                       value={formData.branchId}
                       onChange={(e) => setFormData({ ...formData, branchId: e.target.value })}
                       disabled={true} 
                       className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-slate-100 text-slate-500"
                    >
                       <option value="">Select Branch</option>
                       {branches.map(b => (
                          <option key={b.id} value={b.id}>{b.name}</option>
                       ))}
                    </select>
                 </div>

                 {/* Staff Selection */}
                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">
                       {editingScheduleId ? "Assign To (Swap User)" : "Staff Member"}
                    </label>
                    <select 
                       required
                       value={formData.userId}
                       onChange={(e) => setFormData({ ...formData, userId: e.target.value })}
                       className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                    >
                       <option value="">Select Staff</option>
                       {users
                          .filter(u => u.branchId === formData.branchId)
                          .map(u => (
                             <option key={u.id} value={u.id}>{u.name} ({u.role})</option>
                          ))
                       }
                    </select>
                 </div>

                 <div className="grid grid-cols-2 gap-3">
                    <div>
                       <label className="block text-sm font-medium text-slate-700 mb-1">Start Time</label>
                       <input 
                          type="time" 
                          required
                          value={formData.startTime}
                          onChange={(e) => setFormData({ ...formData, startTime: e.target.value })}
                          className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                       />
                    </div>
                    <div>
                       <label className="block text-sm font-medium text-slate-700 mb-1">End Time</label>
                       <input 
                          type="time" 
                          required
                          value={formData.endTime}
                          onChange={(e) => setFormData({ ...formData, endTime: e.target.value })}
                          className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                       />
                    </div>
                 </div>

                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Note (Optional)</label>
                    <textarea 
                       value={formData.note}
                       onChange={(e) => setFormData({ ...formData, note: e.target.value })}
                       className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 h-20 resize-none"
                       placeholder="e.g. Morning Shift"
                    />
                 </div>

                 <div className="pt-2 flex flex-col gap-3">
                    <button 
                       type="submit"
                       className={`w-full py-3 text-white rounded-lg font-bold shadow-md transition-colors ${editingScheduleId ? 'bg-blue-600 hover:bg-blue-700' : 'bg-slate-900 hover:bg-slate-800'}`}
                    >
                       {editingScheduleId ? 'Update / Swap Schedule' : isRecurringMode ? 'Generate Monthly Roster' : 'Add Single Shift'}
                    </button>

                    {editingScheduleId && editingSchedule?.isSwap && (
                       <button 
                          type="button"
                          onClick={() => onRevertSwap(editingScheduleId)}
                          className="w-full py-2 bg-orange-100 text-orange-700 border border-orange-200 rounded-lg font-bold hover:bg-orange-200 transition-colors flex items-center justify-center"
                       >
                          <ArrowRightLeft className="w-4 h-4 mr-2" /> Revert to Original Owner
                       </button>
                    )}
                 </div>
              </form>
           </div>
        </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { ShiftSchedule, Shift, User, Branch } from '../../types';
import { List, Plus, Calendar, Edit2, Trash2, ChevronLeft, ChevronRight, ArrowRightLeft, Sparkles, MapPin, Clock } from 'lucide-react';

interface ShiftRosterProps {
  shiftSchedules: ShiftSchedule[];
  shifts: Shift[];
  users: User[];
  branches: Branch[];
  canPlanShifts: boolean;
  onAddSchedule: () => void;
  onEditSchedule: (schedule: ShiftSchedule) => void;
  onDeleteSchedule: (id: string) => void;
  planningDate: string;
  setPlanningDate: (date: string) => void;
  calendarDate: Date;
  setCalendarDate: (date: Date) => void;
}

export const ShiftRoster: React.FC<ShiftRosterProps> = ({
  shiftSchedules, shifts, users, branches, canPlanShifts, 
  onAddSchedule, onEditSchedule, onDeleteSchedule,
  planningDate, setPlanningDate, calendarDate, setCalendarDate
}) => {
  const [viewMode, setViewMode] = useState<'list' | 'calendar'>('list');

  // Filter schedules for List View
  const filteredSchedules = useMemo(() => {
    return shiftSchedules.filter(s => s.date === planningDate);
  }, [shiftSchedules, planningDate]);

  // Calendar Logic
  const calendarGrid = useMemo(() => {
    const year = calendarDate.getFullYear();
    const month = calendarDate.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const startDay = new Date(year, month, 1).getDay();

    const days: { date: number; fullDate: string; schedules: ShiftSchedule[] }[] = [];

    for (let i = 0; i < startDay; i++) days.push({ date: 0, fullDate: '', schedules: [] });

    for (let i = 1; i <= daysInMonth; i++) {
        const fullDate = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
        const daySchedules = shiftSchedules.filter(s => s.date === fullDate);
        days.push({ date: i, fullDate, schedules: daySchedules });
    }
    return days;
  }, [calendarDate, shiftSchedules]);

  const handlePrevMonth = () => setCalendarDate(new Date(calendarDate.getFullYear(), calendarDate.getMonth() - 1, 1));
  const handleNextMonth = () => setCalendarDate(new Date(calendarDate.getFullYear(), calendarDate.getMonth() + 1, 1));

  if (!canPlanShifts) return null;

  return (
    <div className="flex flex-col gap-6 animate-fade-in h-full print:hidden">
       {/* Controls */}
       <div className="flex flex-col md:flex-row justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-slate-200 gap-4">
          <div className="flex items-center gap-4 w-full md:w-auto">
             <h3 className="font-bold text-slate-700 flex items-center">
                 <List className="w-5 h-5 mr-2 text-slate-500" />
                 Shift Roster
             </h3>
             <div className="flex bg-slate-100 p-1 rounded-lg">
                <button 
                   onClick={() => setViewMode('list')}
                   className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors ${viewMode === 'list' ? 'bg-white shadow-sm text-slate-800' : 'text-slate-500'}`}
                >
                   List
                </button>
                <button 
                   onClick={() => setViewMode('calendar')}
                   className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors ${viewMode === 'calendar' ? 'bg-white shadow-sm text-slate-800' : 'text-slate-500'}`}
                >
                   Calendar
                </button>
             </div>
          </div>

          <div className="flex items-center gap-3 w-full md:w-auto justify-end">
             {viewMode === 'calendar' && (
                <div className="flex items-center text-xs text-green-600 bg-green-50 px-2 py-1 rounded border border-green-100">
                    <Sparkles className="w-3 h-3 mr-1" />
                    Auto-Fills from Prev. Month
                </div>
             )}

             {viewMode === 'list' && (
                <input 
                   type="date" 
                   value={planningDate} 
                   onChange={(e) => setPlanningDate(e.target.value)}
                   className="px-3 py-1.5 border border-slate-300 rounded-lg text-sm bg-white shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                />
             )}
             <button 
                onClick={onAddSchedule}
                className="flex items-center px-4 py-2 bg-construction-orange text-white rounded-lg text-sm font-bold hover:bg-orange-600 transition-colors shadow-sm"
             >
                <Plus className="w-4 h-4 mr-1.5" /> Add Shift
             </button>
          </div>
       </div>

       {/* LIST VIEW */}
       {viewMode === 'list' && (
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-y-auto p-4 space-y-3">
             <h4 className="font-bold text-slate-700 mb-2">Schedule for {new Date(planningDate).toLocaleDateString()}</h4>
             {filteredSchedules.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-48 text-slate-400">
                   <Calendar className="w-12 h-12 mb-3 opacity-30" />
                   <p>No shifts assigned for this date.</p>
                </div>
             ) : (
                filteredSchedules.map(schedule => {
                   const user = users.find(u => u.id === schedule.userId);
                   const branch = branches.find(b => b.id === schedule.branchId);
                   const originalUser = schedule.originalUserId ? users.find(u => u.id === schedule.originalUserId) : null;

                   const actualShift = shifts.find(s => 
                      s.userId === schedule.userId && 
                      s.branchId === schedule.branchId &&
                      new Date(s.startTime).toISOString().split('T')[0] === schedule.date
                   );

                   let statusBadge = <span className="text-xs bg-slate-100 text-slate-500 px-2 py-0.5 rounded border">Scheduled</span>;

                   if (actualShift) {
                      if (actualShift.status === 'Open') {
                         statusBadge = <span className="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded border border-green-200 font-bold animate-pulse">Working Now</span>;
                      } else {
                         statusBadge = <span className="text-xs bg-blue-100 text-blue-700 px-2 py-0.5 rounded border border-blue-200 font-bold">Completed</span>;
                      }
                   }

                   return (
                      <div key={schedule.id} className="flex items-center justify-between p-4 border border-slate-200 rounded-xl hover:border-blue-300 transition-colors bg-white group shadow-sm relative">
                         {schedule.isSwap && (
                            <span className="absolute top-2 right-2 flex items-center gap-1 px-1.5 py-0.5 bg-orange-100 text-orange-700 text-[10px] font-bold uppercase rounded border border-orange-200 tracking-wide" title={`Originally assigned to ${originalUser?.name || 'Unknown'}`}>
                               <ArrowRightLeft className="w-3 h-3" /> Swapped
                            </span>
                         )}
                         <div className="flex items-center space-x-4">
                            <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 font-bold text-sm">
                               {user?.name.charAt(0) || 'U'}
                            </div>
                            <div>
                               <div className="flex items-center gap-2">
                                  <h4 className="font-bold text-slate-800">{user?.name || 'Unknown User'}</h4>
                                  {statusBadge}
                               </div>
                               <div className="flex items-center text-xs text-slate-500 mt-1">
                                  <span className="flex items-center mr-3">
                                     <MapPin className="w-3 h-3 mr-1" /> {branch?.name}
                                  </span>
                                  <span className="flex items-center">
                                     <Clock className="w-3 h-3 mr-1" /> {schedule.startTime} - {schedule.endTime}
                                  </span>
                               </div>
                            </div>
                         </div>

                         <div className="flex space-x-2">
                            <button 
                              onClick={() => onEditSchedule(schedule)}
                              className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                              title="Edit Shift"
                            >
                              <Edit2 className="w-4 h-4" />
                            </button>
                            <button 
                              onClick={() => onDeleteSchedule(schedule.id)}
                              className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                              title="Delete Shift"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                         </div>
                      </div>
                   );
                })
             )}
          </div>
       )}

       {/* CALENDAR VIEW */}
       {viewMode === 'calendar' && (
          <div className="flex-1 flex flex-col gap-4">
             <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 flex flex-col overflow-hidden">
                <div className="flex justify-between items-center p-4 border-b border-slate-100">
                   <button onClick={handlePrevMonth} className="p-1 hover:bg-slate-100 rounded-full"><ChevronLeft className="w-5 h-5"/></button>
                   <h3 className="font-bold text-lg text-slate-800">
                      {calendarDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}
                   </h3>
                   <button onClick={handleNextMonth} className="p-1 hover:bg-slate-100 rounded-full"><ChevronRight className="w-5 h-5"/></button>
                </div>

                <div className="grid grid-cols-7 border-b border-slate-100 bg-slate-50 text-xs font-bold text-slate-500 uppercase text-center py-2">
                   {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => <div key={d}>{d}</div>)}
                </div>

                <div className="flex-1 grid grid-cols-7 auto-rows-fr overflow-y-auto">
                   {calendarGrid.map((day, idx) => {
                      const isToday = day.fullDate === new Date().toISOString().split('T')[0];
                      const isSelected = day.fullDate === planningDate;

                      return (
                         <div 
                            key={idx} 
                            className={`border-b border-r border-slate-100 p-1 md:p-2 min-h-[60px] md:min-h-[100px] flex flex-col cursor-pointer transition-colors ${day.date === 0 ? 'bg-slate-50/50' : isSelected ? 'bg-blue-50' : 'bg-white hover:bg-slate-50'}`}
                            onClick={() => {
                               if(day.date !== 0) {
                                  setPlanningDate(day.fullDate);
                               }
                            }}
                         >
                            {day.date !== 0 && (
                               <>
                                  <div className="flex justify-between items-start">
                                     <span className={`text-xs md:text-sm font-bold mb-1 w-6 h-6 flex items-center justify-center rounded-full ${isToday ? 'bg-blue-600 text-white' : 'text-slate-700'}`}>
                                        {day.date}
                                     </span>
                                     <div className="md:hidden flex gap-0.5">
                                        {day.schedules.length > 0 && <div className="w-1.5 h-1.5 rounded-full bg-orange-500"></div>}
                                     </div>
                                  </div>
                                  <div className="hidden md:block space-y-1 overflow-y-auto max-h-[80px]">
                                     {day.schedules.map(sch => {
                                        const u = users.find(user => user.id === sch.userId);
                                        return (
                                           <div key={sch.id} className={`text-[10px] px-1.5 py-0.5 rounded truncate font-medium border ${sch.isSwap ? 'bg-orange-50 text-orange-700 border-orange-100' : 'bg-blue-50 text-blue-700 border-blue-100'}`}>
                                              {u?.name.split(' ')[0]} ({sch.startTime})
                                           </div>
                                        );
                                     })}
                                  </div>
                               </>
                            )}
                         </div>
                      );
                   })}
                </div>
             </div>

             {/* Mobile Detail List */}
             <div className="md:hidden bg-white rounded-xl shadow-sm border border-slate-200 p-4">
                <h4 className="font-bold text-slate-700 mb-2 border-b border-slate-100 pb-2">
                   Details for {new Date(planningDate).toLocaleDateString()}
                </h4>
                {filteredSchedules.length === 0 ? (
                   <p className="text-sm text-slate-400 italic">No shifts scheduled.</p>
                ) : (
                   <div className="space-y-2">
                      {filteredSchedules.map(sch => {
                         const u = users.find(user => user.id === sch.userId);
                         return (
                            <div key={sch.id} className="flex justify-between items-center text-sm p-2 bg-slate-50 rounded-lg border border-slate-100">
                               <div>
                                  <span className="font-bold text-slate-800">{u?.name}</span>
                                  <span className="text-slate-500 text-xs ml-2">{sch.startTime} - {sch.endTime}</span>
                               </div>
                               {sch.isSwap && <span className="text-[10px] bg-orange-100 text-orange-700 px-1.5 rounded">Swap</span>}
                               <div className="flex gap-2">
                                   <button onClick={() => onEditSchedule(sch)}><Edit2 className="w-4 h-4 text-slate-400"/></button>
                                   <button onClick={() => onDeleteSchedule(sch.id)}><Trash2 className="w-4 h-4 text-red-400"/></button>
                               </div>
                            </div>
                         )
                      })}
                   </div>
                )}
             </div>
          </div>
       )}
    </div>
  );
};

import React, { useState } from 'react';
import { Shift, Branch, PosMachine, User, ShiftSchedule } from '../../types';
import { Clock, DollarSign, MapPin, PlayCircle, StopCircle, Monitor, Briefcase, ArrowDownCircle, ArrowUpCircle, FileText, Calculator, History, CalendarDays } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';

interface ShiftAttendanceProps {
  shifts: Shift[];
  branches: Branch[];
  posMachines: PosMachine[];
  users: User[];
  currentUser: User | null;
  settings: any;
  activeShift: Shift | undefined;
  todaySchedule: ShiftSchedule | undefined;
  historyShifts: Shift[];
  onStartShift: (branchId: string, startCash: number, notes?: string, posId?: string) => void;
  onEndShift: (shiftId: string, endCash: number, notes?: string) => void;
  onAddCashTransaction: (type: 'in' | 'out', amount: number, reason: string) => void;
  onGenerateReport: (shift: Shift) => void;
}

export const ShiftAttendance: React.FC<ShiftAttendanceProps> = ({
  shifts, branches, posMachines, users, currentUser, settings, 
  activeShift, todaySchedule, historyShifts,
  onStartShift, onEndShift, onAddCashTransaction, onGenerateReport
}) => {
  const { formatPrice } = useGlobal();
  const [startCash, setStartCash] = useState<string>('0');
  const [endCash, setEndCash] = useState<string>('0');
  const [notes, setNotes] = useState('');
  const [confirmEnd, setConfirmEnd] = useState(false);

  // Internal Transaction Modal State
  const [isTxnOpen, setIsTxnOpen] = useState(false);
  const [txnType, setTxnType] = useState<'in'|'out'>('out');
  const [txnAmount, setTxnAmount] = useState('');
  const [txnReason, setTxnReason] = useState('');

  const currentBranchName = branches.find(b => b.id === currentUser?.branchId || settings.currentBranchId)?.name || 'Unknown Branch';
  const currentPosName = posMachines.find(p => p.id === settings.currentPosId)?.machineNumber || 'Unknown POS';

  const handleStart = (e: React.FormEvent) => {
    e.preventDefault();
    const branchId = currentUser?.branchId || settings.currentBranchId || (branches[0]?.id);
    if (!branchId) return alert("Branch not configured");

    const scheduleInfo = todaySchedule ? ` (Scheduled: ${todaySchedule.startTime}-${todaySchedule.endTime})` : '';
    const finalNotes = `${notes}${scheduleInfo}`.trim();

    onStartShift(branchId, parseFloat(startCash) || 0, finalNotes, settings.currentPosId);
    setStartCash('0');
    setNotes('');
  };

  const handleEnd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeShift) return;
    onEndShift(activeShift.id, parseFloat(endCash) || 0, notes);
    setEndCash('0');
    setNotes('');
    setConfirmEnd(false);
  };

  const submitCashTxn = () => {
    const amt = parseFloat(txnAmount);
    if (amt > 0 && txnReason) {
      onAddCashTransaction(txnType, amt, txnReason);
      setIsTxnOpen(false);
      setTxnAmount('');
      setTxnReason('');
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 animate-fade-in print:hidden">
      {/* Active Shift Card */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-fit">
         <div className="p-6 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
            <h3 className="font-bold text-slate-800 flex items-center">
               <Clock className="w-5 h-5 mr-2 text-slate-500" />
               Current Status
            </h3>
            {activeShift ? (
               <span className="px-3 py-1 bg-green-100 text-green-700 rounded-full text-xs font-bold uppercase tracking-wide flex items-center">
                  <span className="w-2 h-2 bg-green-500 rounded-full mr-2 animate-pulse"></span>
                  On Duty
               </span>
            ) : (
               <span className="px-3 py-1 bg-slate-200 text-slate-500 rounded-full text-xs font-bold uppercase tracking-wide">
                  Off Duty
               </span>
            )}
         </div>

         <div className="p-6">
            {activeShift ? (
               !confirmEnd ? (
                  <div className="space-y-6">
                     <div className="flex items-center justify-between">
                        <div>
                           <p className="text-sm text-slate-500 mb-1">Started At</p>
                           <p className="text-xl font-bold text-slate-800">
                              {new Date(activeShift.startTime).toLocaleTimeString()}
                           </p>
                           <p className="text-xs text-slate-400">
                              {new Date(activeShift.startTime).toLocaleDateString()}
                           </p>
                        </div>
                        <div>
                           <p className="text-sm text-slate-500 mb-1">Opening Cash</p>
                           <p className="text-xl font-bold text-green-600">
                              {formatPrice(activeShift.startCash)}
                           </p>
                        </div>
                     </div>

                     <div className="bg-blue-50 p-3 rounded-lg flex items-center border border-blue-100">
                        <Monitor className="w-5 h-5 text-blue-600 mr-2" />
                        <div>
                           <p className="text-xs text-blue-500 font-bold uppercase">Active POS Terminal</p>
                           <p className="text-sm font-bold text-slate-700">
                              {activeShift.posId 
                                 ? (posMachines.find(p => p.id === activeShift.posId)?.machineNumber || activeShift.posId)
                                 : (settings.currentPosId ? posMachines.find(p => p.id === settings.currentPosId)?.machineNumber : 'Unknown')
                              }
                           </p>
                        </div>
                     </div>

                     <div className="p-4 bg-slate-50 rounded-xl border border-slate-200">
                        <h4 className="font-bold text-slate-700 mb-3 flex items-center text-sm">
                           <Briefcase className="w-4 h-4 mr-2" /> Drawer Operations
                        </h4>
                        <div className="grid grid-cols-2 gap-3">
                           <button 
                              onClick={() => { setTxnType('in'); setIsTxnOpen(true); }}
                              className="flex items-center justify-center px-4 py-2 bg-white border border-green-200 text-green-700 rounded-lg hover:bg-green-50 transition-colors font-medium text-sm shadow-sm"
                           >
                              <ArrowDownCircle className="w-4 h-4 mr-2" />
                              Add Cash
                           </button>
                           <button 
                              onClick={() => { setTxnType('out'); setIsTxnOpen(true); }}
                              className="flex items-center justify-center px-4 py-2 bg-white border border-red-200 text-red-700 rounded-lg hover:bg-red-50 transition-colors font-medium text-sm shadow-sm"
                           >
                              <ArrowUpCircle className="w-4 h-4 mr-2" />
                              Pay Out
                           </button>
                        </div>
                     </div>

                     <div className="flex gap-3">
                        <button 
                           onClick={() => onGenerateReport(activeShift)}
                           className="flex-1 py-3 bg-white border border-slate-300 text-slate-700 rounded-xl font-bold hover:bg-slate-50 transition-colors shadow-sm flex items-center justify-center"
                        >
                           <FileText className="w-5 h-5 mr-2" />
                           X-Report
                        </button>
                        <button 
                            onClick={() => setConfirmEnd(true)}
                            className="flex-1 py-3 bg-red-600 text-white rounded-xl font-bold hover:bg-red-700 transition-colors shadow-lg flex items-center justify-center"
                        >
                            <StopCircle className="w-6 h-6 mr-2" />
                            End Shift
                        </button>
                     </div>
                  </div>
               ) : (
                  <form onSubmit={handleEnd} className="space-y-4 animate-fade-in">
                     <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 mb-4">
                        <h4 className="font-bold text-slate-700 mb-2">Closing Register</h4>
                        <p className="text-xs text-slate-500">Please count the cash drawer and enter the total amount.</p>
                     </div>

                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Closing Cash Amount</label>
                        <div className="flex gap-2">
                           <div className="relative flex-1">
                              <DollarSign className="absolute left-3 top-2.5 w-5 h-5 text-slate-400" />
                              <input 
                                 type="number" 
                                 step="0.01" 
                                 min="0"
                                 required
                                 value={endCash}
                                 onChange={(e) => setEndCash(e.target.value)}
                                 className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-red-500 text-lg font-bold"
                              />
                           </div>
                        </div>
                     </div>

                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Shift Notes</label>
                        <textarea 
                           value={notes}
                           onChange={(e) => setNotes(e.target.value)}
                           className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-red-500 h-24 resize-none"
                           placeholder="Any discrepancies or comments..."
                        />
                     </div>

                     <div className="flex space-x-3 pt-2">
                        <button 
                           type="button"
                           onClick={() => setConfirmEnd(false)}
                           className="flex-1 py-3 border border-slate-300 text-slate-600 rounded-lg font-medium hover:bg-slate-50"
                        >
                           Cancel
                        </button>
                        <button 
                           type="submit"
                           className="flex-1 py-3 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700 shadow-md"
                        >
                           Confirm Clock Out
                        </button>
                     </div>
                  </form>
               )
            ) : (
               <form onSubmit={handleStart} className="space-y-4">
                  {todaySchedule && (
                     <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 flex items-start text-sm text-blue-700">
                        <CalendarDays className="w-5 h-5 mr-2 flex-shrink-0 mt-0.5" />
                        <div>
                           <p className="font-bold">Scheduled for Today</p>
                           <p className="text-xs mt-1">
                              {todaySchedule.startTime} - {todaySchedule.endTime}
                           </p>
                           {todaySchedule.note && <p className="text-xs italic mt-1">"{todaySchedule.note}"</p>}
                        </div>
                     </div>
                  )}

                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Location / Branch</label>
                     <div className="relative">
                        <MapPin className="absolute left-3 top-2.5 w-5 h-5 text-slate-400" />
                        <input 
                           type="text" 
                           disabled
                           value={currentBranchName}
                           className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg bg-slate-100 text-slate-500 font-medium cursor-not-allowed"
                        />
                     </div>
                     <div className="mt-2 flex items-center text-xs text-slate-500 bg-slate-50 p-2 rounded border border-slate-200">
                        <Monitor className="w-3.5 h-3.5 mr-2 text-blue-500" />
                        <span>
                           POS ID: <span className="font-bold font-mono text-slate-700">{currentPosName}</span>
                        </span>
                     </div>
                  </div>

                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Opening Cash Amount</label>
                     <div className="relative">
                        <DollarSign className="absolute left-3 top-2.5 w-5 h-5 text-slate-400" />
                        <input 
                           type="number" 
                           step="0.01" 
                           min="0"
                           required
                           value={startCash}
                           onChange={(e) => setStartCash(e.target.value)}
                           className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-green-500 font-bold"
                        />
                     </div>
                  </div>

                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Notes (Optional)</label>
                     <textarea 
                        value={notes}
                        onChange={(e) => setNotes(e.target.value)}
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-green-500 h-20 resize-none"
                        placeholder="e.g. Register 2"
                     />
                  </div>

                  <button 
                     type="submit"
                     className="w-full py-4 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 transition-colors shadow-lg flex items-center justify-center"
                  >
                     <PlayCircle className="w-6 h-6 mr-2" />
                     Start Shift (Clock In)
                  </button>
               </form>
            )}
         </div>
      </div>

      {/* History */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col overflow-hidden h-[500px]">
         <div className="p-4 border-b border-slate-100 bg-slate-50">
            <h3 className="font-bold text-slate-700 flex items-center">
               <History className="w-5 h-5 mr-2 text-slate-500" />
               Recent Shift History
            </h3>
         </div>
         <div className="overflow-y-auto flex-1 p-0">
            {historyShifts.length === 0 ? (
               <div className="p-8 text-center text-slate-400">No shift history found.</div>
            ) : (
               <table className="w-full text-left">
                  <thead className="bg-slate-50 text-xs text-slate-500 uppercase font-semibold sticky top-0">
                     <tr>
                        <th className="px-4 py-3">Date / User</th>
                        <th className="px-4 py-3">Duration</th>
                        <th className="px-4 py-3 text-right">Cash Out</th>
                        <th className="px-4 py-3 text-center">Action</th>
                     </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                     {historyShifts.map(shift => {
                        const start = new Date(shift.startTime);
                        const end = shift.endTime ? new Date(shift.endTime) : null;
                        const duration = end ? 
                           Math.round((end.getTime() - start.getTime()) / (1000 * 60 * 60) * 10) / 10 + ' hrs' : 
                           'Running';

                        const user = users.find(u => u.id === shift.userId);
                        const branch = branches.find(b => b.id === shift.branchId);

                        return (
                           <tr key={shift.id} className="hover:bg-slate-50 transition-colors text-sm">
                              <td className="px-4 py-3">
                                 <div className="font-medium text-slate-800">{start.toLocaleDateString()}</div>
                                 <div className="text-xs text-slate-500">{user?.name || 'Unknown'}</div>
                                 <div className="text-[10px] text-slate-400 flex items-center mt-0.5">
                                    <MapPin className="w-3 h-3 mr-1" />
                                    {branch?.name}
                                 </div>
                              </td>
                              <td className="px-4 py-3 text-slate-600">
                                 {start.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} - 
                                 {end ? end.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) : '...'}
                                 <div className="text-xs text-slate-400 mt-0.5">{duration}</div>
                              </td>
                              <td className="px-4 py-3 text-right font-mono">
                                 {shift.endCash !== undefined ? formatPrice(shift.endCash) : '-'}
                              </td>
                              <td className="px-4 py-3 text-center">
                                 <button 
                                    onClick={() => onGenerateReport(shift)}
                                    className="text-blue-600 hover:text-blue-800 text-xs font-bold underline"
                                 >
                                    Report
                                 </button>
                              </td>
                           </tr>
                        );
                     })}
                  </tbody>
               </table>
            )}
         </div>
      </div>

      {/* Transaction Modal */}
      {isTxnOpen && (
         <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[70]">
            <div className="bg-white rounded-xl p-6 w-full max-w-sm shadow-2xl">
               <h3 className="font-bold text-slate-800 mb-4">{txnType === 'in' ? 'Pay In (Add Cash)' : 'Pay Out (Remove Cash)'}</h3>
               <input 
                  type="number" 
                  placeholder="Amount" 
                  className="w-full border rounded-lg px-3 py-2 mb-3"
                  value={txnAmount}
                  onChange={e => setTxnAmount(e.target.value)}
                  autoFocus
               />
               <textarea 
                  placeholder="Reason / Reference" 
                  className="w-full border rounded-lg px-3 py-2 mb-4 h-20"
                  value={txnReason}
                  onChange={e => setTxnReason(e.target.value)}
               />
               <div className="flex gap-2">
                  <button onClick={() => setIsTxnOpen(false)} className="flex-1 py-2 border rounded-lg">Cancel</button>
                  <button onClick={submitCashTxn} className="flex-1 py-2 bg-slate-900 text-white rounded-lg">Confirm</button>
               </div>
            </div>
         </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Shift, Branch, User, ShiftSchedule } from '../types';
import { Clock, CalendarDays } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';

// Sub-components
import { ShiftAttendance } from './shift/ShiftAttendance';
import { ShiftRoster } from './shift/ShiftRoster';
import { ZReportModal, ZReportData } from './shift/ZReportModal';
import { ScheduleModal } from './shift/ScheduleModal';

interface ShiftManagementProps {
  shifts: Shift[];
  branches: Branch[];
  users: User[];
  currentUser: User | null;
  onStartShift: (branchId: string, startCash: number, notes?: string, posId?: string) => void;
  onEndShift: (shiftId: string, endCash: number, notes?: string) => void;
}

export const ShiftManagement: React.FC<ShiftManagementProps> = ({
  shifts, branches, users, currentUser, onStartShift, onEndShift
}) => {
  const { 
    shiftSchedules, 
    addShiftSchedule, 
    updateShiftSchedule,
    deleteShiftSchedule, 
    settings, 
    posMachines, 
    sales, 
    addCashTransaction,
    formatPrice
  } = useGlobal();

  const [activeTab, setActiveTab] = useState<'attendance' | 'planning'>('attendance');

  // Roster State
  const [planningDate, setPlanningDate] = useState(new Date().toISOString().split('T')[0]);
  const [calendarDate, setCalendarDate] = useState(new Date());

  // Modals State
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [editingScheduleId, setEditingScheduleId] = useState<string | null>(null);
  const [viewingReport, setViewingReport] = useState<ZReportData | null>(null);

  // Derived State
  const activeShift = shifts.find(s => s.userId === currentUser?.id && s.status === 'Open');
  const todaySchedule = useMemo(() => {
    if (!currentUser) return undefined;
    const todayStr = new Date().toISOString().split('T')[0];
    return shiftSchedules.find(s => s.userId === currentUser.id && s.date === todayStr);
  }, [shiftSchedules, currentUser]);

  const historyShifts = useMemo(() => {
    let filtered = shifts;
    if (currentUser?.role !== 'Admin' && currentUser?.role !== 'Manager') {
      filtered = filtered.filter(s => s.userId === currentUser?.id);
    }
    return filtered.sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime());
  }, [shifts, currentUser]);

  const canPlanShifts = currentUser?.role === 'Admin' || currentUser?.role === 'Manager';
  const selectedBranchId = currentUser?.branchId || settings.currentBranchId || branches[0]?.id || '';

  // Auto-clone logic for calendar (simplified version of original hook)
  useEffect(() => {
    if (activeTab !== 'planning') return;
    const currentYear = calendarDate.getFullYear();
    const currentMonth = calendarDate.getMonth();

    // Check if empty
    const hasCurrent = shiftSchedules.some(s => {
       const d = new Date(s.date);
       return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    if (!hasCurrent) {
       // Check prev month
       const prevDate = new Date(currentYear, currentMonth - 1, 1);
       const prevSchedules = shiftSchedules.filter(s => {
          const d = new Date(s.date);
          return d.getMonth() === prevDate.getMonth() && d.getFullYear() === prevDate.getFullYear();
       });

       if (prevSchedules.length > 0) {
          console.log("Auto-populating roster...");
          prevSchedules.forEach((oldSch, idx) => {
             const oldDate = new Date(oldSch.date);
             const targetDate = new Date(currentYear, currentMonth, oldDate.getDate());
             // Basic copy
             if (targetDate.getMonth() === currentMonth) {
                addShiftSchedule({
                   ...oldSch,
                   id: `auto-${Date.now()}-${idx}`,
                   date: targetDate.toISOString().split('T')[0],
                   isSwap: false
                });
             }
          });
       }
    }
  }, [activeTab, calendarDate, shiftSchedules, addShiftSchedule]);

  // Handlers
  const handleOpenAddSchedule = () => {
    setEditingScheduleId(null);
    setIsScheduleModalOpen(true);
  };

  const handleOpenEditSchedule = (schedule: ShiftSchedule) => {
    setEditingScheduleId(schedule.id);
    setIsScheduleModalOpen(true);
  };

  const handleSaveSchedule = (formData: any, isRecurring: boolean, recurringDays: number[]) => {
    if (editingScheduleId) {
       // Update Single
       const original = shiftSchedules.find(s => s.id === editingScheduleId);
       const isSwap = original && original.userId !== formData.userId;
       const originalUserId = (isSwap && !original?.originalUserId) ? original?.userId : original?.originalUserId;

       updateShiftSchedule({
          id: editingScheduleId,
          date: original ? original.date : planningDate,
          userId: formData.userId,
          branchId: formData.branchId,
          startTime: formData.startTime,
          endTime: formData.endTime,
          note: formData.note,
          isSwap: isSwap || original?.isSwap,
          originalUserId: originalUserId
       });
    } else {
       // Add New
       if (isRecurring) {
          const year = calendarDate.getFullYear();
          const month = calendarDate.getMonth();
          const daysInMonth = new Date(year, month + 1, 0).getDate();
          let count = 0;

          for (let i = 1; i <= daysInMonth; i++) {
             const d = new Date(year, month, i);
             if (recurringDays.includes(d.getDay())) {
                addShiftSchedule({
                   id: `sch-${Date.now()}-${count++}`,
                   date: d.toISOString().split('T')[0],
                   userId: formData.userId,
                   branchId: formData.branchId,
                   startTime: formData.startTime,
                   endTime: formData.endTime,
                   note: formData.note
                });
             }
          }
       } else {
          addShiftSchedule({
             id: `sch-${Date.now()}`,
             date: planningDate,
             userId: formData.userId,
             branchId: formData.branchId,
             startTime: formData.startTime,
             endTime: formData.endTime,
             note: formData.note
          });
       }
    }
    setIsScheduleModalOpen(false);
  };

  const handleRevertSwap = (id: string) => {
     const s = shiftSchedules.find(x => x.id === id);
     if (s && s.originalUserId) {
        if(confirm("Revert to original user?")) {
           updateShiftSchedule({ ...s, userId: s.originalUserId, originalUserId: undefined, isSwap: false });
           setIsScheduleModalOpen(false);
        }
     }
  };

  const generateZReport = (shift: Shift) => {
    // Re-implement report logic using global sales/data
    const start = new Date(shift.startTime);
    const end = shift.endTime ? new Date(shift.endTime) : new Date();

    const shiftSales = sales.filter(s => {
      const sDate = new Date(s.date);
      return sDate >= start && sDate <= end && s.status !== 'voided';
    });

    const salesByMethod: Record<string, number> = {};
    let totalSales = 0;
    let cashReceived = 0;
    let cashChange = 0;

    shiftSales.forEach(s => {
      const method = s.paymentMethod;
      salesByMethod[method] = (salesByMethod[method] || 0) + s.total;
      totalSales += s.total;
      if (method === 'cash') {
         cashReceived += (s.amountReceived || s.total);
         cashChange += (s.change || 0);
      }
    });

    const txns = shift.cashTransactions || [];
    const cashIn = txns.filter(t => t.type === 'in').reduce((sum, t) => sum + t.amount, 0);
    const cashOut = txns.filter(t => t.type === 'out').reduce((sum, t) => sum + t.amount, 0);
    const netCashSales = cashReceived - cashChange;
    const expectedCash = shift.startCash + netCashSales + cashIn - cashOut;
    const actualEndCash = shift.endCash || 0; 

    setViewingReport({
      shiftId: shift.id,
      user: users.find(u => u.id === shift.userId)?.name || 'Unknown',
      branch: branches.find(b => b.id === shift.branchId)?.name || 'Unknown',
      posMachine: shift.posId ? (posMachines.find(p => p.id === shift.posId)?.machineNumber || shift.posId) : 'N/A',
      start: start.toLocaleString(),
      end: shift.status === 'Open' ? 'Running...' : end.toLocaleString(),
      startCash: shift.startCash,
      endCash: actualEndCash,
      totalSales,
      salesByMethod,
      cashReceived,
      cashChange,
      expectedCash,
      discrepancy: actualEndCash - expectedCash,
      transactionCount: shiftSales.length,
      cashIn,
      cashOut,
      notes: shift.notes
    });
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center print:hidden">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Shift Management</h2>
          <p className="text-slate-500">Track working hours and manage staff schedules.</p>
        </div>

        <div className="flex bg-slate-100 p-1 rounded-lg">
           <button
             onClick={() => setActiveTab('attendance')}
             className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${
               activeTab === 'attendance' 
                 ? 'bg-white text-slate-800 shadow-sm' 
                 : 'text-slate-500 hover:text-slate-700'
             }`}
           >
             <Clock className="w-4 h-4 mr-2" />
             Time Clock
           </button>
           {canPlanShifts && (
             <button
               onClick={() => setActiveTab('planning')}
               className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                 activeTab === 'planning' 
                   ? 'bg-white text-slate-800 shadow-sm' 
                   : 'text-slate-500 hover:text-slate-700'
               }`}
             >
               <CalendarDays className="w-4 h-4 mr-2" />
               Roster / Planning
             </button>
           )}
        </div>
      </div>

      {activeTab === 'attendance' && (
        <ShiftAttendance 
          shifts={shifts}
          branches={branches}
          posMachines={posMachines}
          users={users}
          currentUser={currentUser}
          settings={settings}
          activeShift={activeShift}
          todaySchedule={todaySchedule}
          historyShifts={historyShifts}
          onStartShift={onStartShift}
          onEndShift={onEndShift}
          onAddCashTransaction={addCashTransaction}
          onGenerateReport={generateZReport}
        />
      )}

      {activeTab === 'planning' && (
        <ShiftRoster 
          shiftSchedules={shiftSchedules}
          shifts={shifts}
          users={users}
          branches={branches}
          canPlanShifts={canPlanShifts}
          onAddSchedule={handleOpenAddSchedule}
          onEditSchedule={handleOpenEditSchedule}
          onDeleteSchedule={deleteShiftSchedule}
          planningDate={planningDate}
          setPlanningDate={setPlanningDate}
          calendarDate={calendarDate}
          setCalendarDate={setCalendarDate}
        />
      )}

      <ScheduleModal 
        isOpen={isScheduleModalOpen}
        onClose={() => setIsScheduleModalOpen(false)}
        branches={branches}
        users={users}
        editingScheduleId={editingScheduleId}
        shiftSchedules={shiftSchedules}
        planningDate={planningDate}
        selectedBranchId={selectedBranchId}
        calendarDate={calendarDate}
        onSave={handleSaveSchedule}
        onRevertSwap={handleRevertSwap}
      />

      <ZReportModal 
        report={viewingReport}
        onClose={() => setViewingReport(null)}
      />
    </div>
  );
};

