}

interface ApprovalListProps {
  items: ApprovalItem[];
  onApprove: (e: React.MouseEvent, item: ApprovalItem) => void;
  onReject: (e: React.MouseEvent, item: ApprovalItem) => void;
}

export const ApprovalList: React.FC<ApprovalListProps> = ({ items, onApprove, onReject }) => {
  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center flex-1 text-slate-400 p-8">
        <div className="bg-slate-50 p-6 rounded-full mb-4">
          <CheckCircle className="w-12 h-12 text-green-200" />
        </div>
        <h3 className="text-lg font-medium text-slate-600">All caught up!</h3>
        <p className="text-sm">No pending approvals found.</p>
      </div>
    );
  }

  return (
    <div className="overflow-y-auto flex-1 bg-slate-50 p-4">
      <div className="grid grid-cols-1 gap-4">
        {items.map((item) => {
          const Icon = item.icon;
          return (
            <div key={item.id} className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-4 relative overflow-hidden group">
              {/* Left Border Status Indicator */}
              <div className={`absolute left-0 top-0 bottom-0 w-1 ${item.color.split(' ')[0].replace('text-', 'bg-')}`}></div>

              <div className="flex-1 flex items-start gap-4">
                <div className={`p-3 rounded-xl border shrink-0 ${item.color}`}>
                  <Icon className="w-6 h-6" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center flex-wrap gap-2 mb-1">
                    <span className={`px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider rounded-full border bg-white ${item.color.replace('text-', 'border-').replace('bg-', '')}`}>
                      {item.typeLabel}
                    </span>
                    <span className="text-xs text-slate-400 font-mono flex items-center">
                       {item.referenceNo}
                       <span className="mx-1">•</span>
                       {new Date(item.date).toLocaleDateString()}
                    </span>
                  </div>

                  <h3 className="font-bold text-slate-800 text-base mb-1">
                    {item.description}
                  </h3>
                  {item.meta && <p className="text-xs text-slate-500 mb-2">{item.meta}</p>}

                  {/* Compact Items Preview */}
                  <div className="flex flex-wrap gap-2 mt-2">
                     {item.items.slice(0, 3).map((prod: any, idx: number) => {
                       const displayQty = item.type === 'count' ? prod.countedQuantity : prod.quantity;
                       const prefix = (item.type === 'adjustment' && prod.quantity > 0) ? '+' : '';

                       return (
                         <div key={idx} className="flex items-center px-2 py-1 bg-slate-50 text-slate-600 text-xs rounded border border-slate-100">
                           <span className="truncate max-w-[100px]">{prod.productName}</span>
                           <span className={`ml-2 font-bold ${item.type === 'adjustment' && prod.quantity < 0 ? 'text-red-600' : 'text-slate-900'}`}>
                             {prefix}{displayQty}
                           </span>
                         </div>
                       );
                     })}
                     {item.items.length > 3 && (
                       <span className="flex items-center px-2 py-1 bg-slate-50 text-slate-400 text-xs rounded border border-slate-100">
                         +{item.items.length - 3}
                       </span>
                     )}
                  </div>
                </div>
              </div>

              {/* Actions - Stacked on Mobile, Row on Desktop */}
              <div className="flex md:flex-col lg:flex-row items-center justify-end gap-3 pt-4 md:pt-0 border-t md:border-t-0 border-slate-100">
                <button 
                  onClick={(e) => onReject(e, item)}
                  className="flex-1 md:flex-none flex items-center justify-center px-4 py-2.5 border border-red-100 text-red-600 rounded-lg hover:bg-red-50 transition-colors font-bold text-sm w-full md:w-auto"
                >
                  <XCircle className="w-4 h-4 mr-2" />
                  Reject
                </button>
                <button 
                  onClick={(e) => onApprove(e, item)}
                  className="flex-1 md:flex-none flex items-center justify-center px-6 py-2.5 bg-slate-900 text-white rounded-lg hover:bg-slate-800 transition-colors font-bold text-sm shadow-md w-full md:w-auto"
                >
                  <CheckCircle className="w-4 h-4 mr-2" />
                  Approve
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { 
  StockTransfer, 
  StockCount, 
  StockReservation, 
  StockReceipt, 
  StockAdjustment,
  DocumentStatus,
  Warehouse
} from '../types';
import { 
  ArrowRightLeft, 
  CheckSquare, 
  CalendarClock, 
  Truck, 
  Clock,
  SlidersHorizontal
} from 'lucide-react';
import { ApprovalList } from './approval/ApprovalList';

interface ApprovalManagementProps {
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  warehouses: Warehouse[];
  onStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;
}

export const ApprovalManagement: React.FC<ApprovalManagementProps> = ({
  transfers,
  counts,
  reservations,
  receipts,
  adjustments,
  warehouses,
  onStatusChange
}) => {

  const getWarehouseName = (id: string) => warehouses.find(w => w.id === id)?.name || id;

  // Flatten and normalize data for the list
  const pendingItems = useMemo(() => {
    const list: any[] = [];

    // 1. Transfers
    transfers.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'transfer',
        typeLabel: 'Stock Transfer',
        icon: ArrowRightLeft,
        description: `Transfer from ${getWarehouseName(item.sourceWarehouseId)} to ${getWarehouseName(item.targetWarehouseId)}`,
        color: 'text-blue-600 bg-blue-50 border-blue-100'
      });
    });

    // 2. Stock Counts
    counts.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'count',
        typeLabel: 'Stock Audit',
        icon: CheckSquare,
        description: `Audit at ${getWarehouseName(item.warehouseId)} by ${item.counterName}`,
        color: 'text-purple-600 bg-purple-50 border-purple-100'
      });
    });

    // 3. Reservations
    reservations.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'reservation',
        typeLabel: 'Reservation',
        icon: CalendarClock,
        description: `Reserved for ${item.customerName}`,
        meta: `Exp: ${new Date(item.expiryDate).toLocaleDateString()}`,
        color: 'text-orange-600 bg-orange-50 border-orange-100'
      });
    });

    // 4. Receipts
    receipts.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'receipt',
        typeLabel: 'Goods Receipt',
        icon: Truck,
        description: `Received from ${item.vendorName}`,
        meta: item.vendorInvoiceNo ? `Inv: ${item.vendorInvoiceNo}` : undefined,
        color: 'text-green-600 bg-green-50 border-green-100'
      });
    });

    // 5. Adjustments
    adjustments.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'adjustment',
        typeLabel: 'Stock Adjustment',
        icon: SlidersHorizontal,
        description: `Adjustment at ${getWarehouseName(item.warehouseId)}`,
        meta: item.reason,
        color: 'text-pink-600 bg-pink-50 border-pink-100'
      });
    });

    // Sort by date (newest first)
    return list.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transfers, counts, reservations, receipts, adjustments, warehouses]);

  const handleApprove = (e: React.MouseEvent, item: any) => {
    e.stopPropagation();
    // Only Approve. Execution happens in Stock Management via 'Complete'.
    if (window.confirm('Are you sure you want to Approve this request?')) {
      onStatusChange(item.type, item.id, 'Approved');
    }
  };

  const handleReject = (e: React.MouseEvent, item: any) => {
    e.stopPropagation();
    if (window.confirm('Are you sure you want to Reject this request?')) {
      onStatusChange(item.type, item.id, 'Cancelled');
    }
  };

  return (
    <div className="space-y-6 h-full flex flex-col pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Approval Center</h2>
          <p className="text-slate-500">Review and approve pending document requests.</p>
        </div>
        <div className="flex items-center space-x-2 bg-white px-4 py-2 rounded-lg shadow-sm border border-slate-200 w-fit">
          <Clock className="w-5 h-5 text-orange-500" />
          <span className="font-bold text-slate-700">{pendingItems.length}</span>
          <span className="text-slate-500 text-sm">Pending</span>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <ApprovalList 
          items={pendingItems}
          onApprove={handleApprove}
          onReject={handleReject}
        />
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Sale, SystemSettings } from '../../types';
import { XCircle, RotateCcw, Wallet, DollarSign, Reply, Ban, Printer } from 'lucide-react';

interface SaleDetailModalProps {
  sale: Sale | null;
  isOpen: boolean;
  onClose: () => void;
  onVoid: () => void;
  onSettleDebt: () => void;
  onReturn: (items: { itemIndex: number, quantity: number }[]) => Promise<void>;
  settings?: SystemSettings;
  formatPrice: (amount: number) => string;
  isAdminOrManager: boolean;
}

export const SaleDetailModal: React.FC<SaleDetailModalProps> = ({ 
  sale, isOpen, onClose, onVoid, onSettleDebt, onReturn, settings, formatPrice, isAdminOrManager 
}) => {
  const [isReturnMode, setIsReturnMode] = useState(false);
  const [returnQuantities, setReturnQuantities] = useState<Record<number, number>>({});

  if (!isOpen || !sale) return null;

  const handleReturnQtyChange = (index: number, qty: number) => {
    const max = sale.items[index].quantity || 0;
    const val = Math.min(Math.max(0, qty), max);
    setReturnQuantities(prev => ({ ...prev, [index]: val }));
  };

  const calculateReturnTotal = () => {
    return sale.items.reduce((acc, item, index) => {
      const qty = returnQuantities[index] || 0;
      return acc + (item.sellPrice * qty);
    }, 0);
  };

  const handleSubmitReturn = async () => {
    const itemsToReturn = Object.entries(returnQuantities)
      .filter(([_, qty]) => (qty as number) > 0)
      .map(([index, quantity]) => ({ itemIndex: parseInt(index), quantity: quantity as number }));

    if (itemsToReturn.length === 0) {
      alert("Please select at least one item to return.");
      return;
    }

    if (confirm(`Confirm refund of ${formatPrice(calculateReturnTotal())}? This will restore stock.`)) {
      await onReturn(itemsToReturn);
      setIsReturnMode(false);
      setReturnQuantities({});
      onClose();
    }
  };

  const toggleReturnMode = () => {
    setIsReturnMode(!isReturnMode);
    setReturnQuantities({});
  };

  const handlePrint = () => {
    window.print();
  };

  const receiptWidthClass = settings?.receiptPaperSize === '58mm' ? 'print-w-58mm' : settings?.receiptPaperSize === 'A4' ? 'print-w-A4' : 'print-w-80mm';

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4 print:p-0 print:bg-white print:static print:block">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg max-h-[90vh] flex flex-col print:shadow-none print:max-w-none print:max-h-none print:rounded-none">

        {/* Modal Header - Hidden on Print */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl print:hidden">
          <div>
             <h3 className="text-xl font-bold text-slate-800">
                {isReturnMode ? 'Select Items to Return' : 'Invoice Details'}
             </h3>
             <p className="text-sm text-slate-500 font-mono">#{sale.id}</p>
          </div>
          <div className="flex items-center space-x-2">
             {sale.status === 'voided' && (
                <span className="px-3 py-1 bg-red-100 text-red-700 rounded-full text-xs font-bold uppercase tracking-wide flex items-center">
                   <RotateCcw className="w-3 h-3 mr-1" /> Stock Restored
                </span>
             )}
             <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
               <XCircle className="w-6 h-6" />
             </button>
          </div>
        </div>

        {/* Screen View */}
        <div className="p-6 overflow-y-auto flex-1 print:hidden">
           {!isReturnMode && (
              <div className="flex justify-between mb-4 text-sm">
                 <div className="text-slate-500">
                    <p>Date: <span className="font-medium text-slate-700">{new Date(sale.date).toLocaleString()}</span></p>
                    <p>Customer: <span className="font-medium text-slate-700">{sale.customerName || 'Walk-in'}</span></p>
                 </div>
                 <div className="text-right text-slate-500">
                    <p>Method: <span className="font-medium text-slate-700 capitalize">{sale.paymentMethod}</span></p>
                    <p>Status: <span className={`font-bold capitalize ${sale.paymentStatus === 'paid' ? 'text-green-600' : 'text-orange-600'}`}>{sale.paymentStatus || 'Paid'}</span></p>
                 </div>
              </div>
           )}

           <div className="border rounded-lg overflow-hidden mb-6">
              <table className="w-full text-sm">
                 <thead className="bg-slate-50 text-slate-500">
                    <tr>
                       {isReturnMode && <th className="px-4 py-2 w-16">Return</th>}
                       <th className="px-4 py-2 text-left">Item</th>
                       <th className="px-4 py-2 text-right">Qty</th>
                       <th className="px-4 py-2 text-right">Price</th>
                       <th className="px-4 py-2 text-right">Total</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100">
                    {sale.items.map((item, idx) => (
                       <tr key={idx} className={returnQuantities[idx] > 0 ? 'bg-red-50' : ''}>
                          {isReturnMode && (
                             <td className="px-4 py-2">
                                <input 
                                   type="number" 
                                   min="0" 
                                   max={item.quantity}
                                   value={returnQuantities[idx] || 0}
                                   onChange={(e) => handleReturnQtyChange(idx, parseInt(e.target.value) || 0)}
                                   className="w-16 border rounded p-1 text-center font-bold"
                                />
                             </td>
                          )}
                          <td className="px-4 py-2">
                             <div className="font-medium text-slate-800">{item.name}</div>
                             {item.selectedVariantId && <div className="text-xs text-slate-400">Variant</div>}
                          </td>
                          <td className="px-4 py-2 text-right">{item.quantity}</td>
                          <td className="px-4 py-2 text-right">{formatPrice(item.sellPrice)}</td>
                          <td className="px-4 py-2 text-right font-bold">{formatPrice(item.sellPrice * item.quantity)}</td>
                       </tr>
                    ))}
                 </tbody>
                 <tfoot className="bg-slate-50 font-bold text-slate-800">
                    {!isReturnMode ? (
                       <>
                          <tr>
                             <td colSpan={3} className="px-4 py-3 text-right">Subtotal</td>
                             <td className="px-4 py-3 text-right">{formatPrice(sale.subtotal || sale.total)}</td>
                          </tr>
                          {sale.discountAmount && sale.discountAmount > 0 && (
                             <tr className="text-green-600">
                                <td colSpan={3} className="px-4 py-1 text-right">Discount</td>
                                <td className="px-4 py-1 text-right">-{formatPrice(sale.discountAmount)}</td>
                             </tr>
                          )}
                          <tr className="border-t border-slate-200">
                             <td colSpan={3} className="px-4 py-3 text-right text-lg">Grand Total</td>
                             <td className="px-4 py-3 text-right text-lg">{formatPrice(Math.abs(sale.total))}</td>
                          </tr>
                       </>
                    ) : (
                       <tr className="bg-red-50 text-red-700 border-t border-red-200">
                          <td colSpan={4} className="px-4 py-3 text-right text-lg">Refund Total</td>
                          <td className="px-4 py-3 text-right text-lg">{formatPrice(calculateReturnTotal())}</td>
                       </tr>
                    )}
                 </tfoot>
              </table>
           </div>

           {/* Actions in Modal (Screen Only) */}
           {(sale.paymentStatus === 'unpaid' || sale.paymentStatus === 'partial') && sale.status !== 'voided' && !isReturnMode && (
              <div className="mb-4 bg-orange-50 p-4 rounded-lg border border-orange-200">
                 <h4 className="font-bold text-orange-800 text-sm mb-2 flex items-center">
                    <Wallet className="w-4 h-4 mr-2" /> 
                    Outstanding Payment
                 </h4>
                 <p className="text-xs text-orange-700 mb-3">
                    This invoice has an outstanding balance of <span className="font-bold">{formatPrice(sale.remainingAmount || 0)}</span>.
                 </p>
                 <button
                    onClick={onSettleDebt}
                    className="w-full py-2 bg-slate-800 text-white rounded-lg text-sm font-bold hover:bg-slate-900 shadow-sm flex items-center justify-center"
                 >
                    <DollarSign className="w-4 h-4 mr-1" />
                    Settle Debt (Receive Full Payment)
                 </button>
              </div>
           )}

           {sale.status !== 'voided' && sale.type !== 'return' && isAdminOrManager && !isReturnMode && (
              <div className="grid grid-cols-2 gap-4">
                 <button 
                    onClick={toggleReturnMode}
                    className="py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-xs font-bold uppercase tracking-wide hover:bg-slate-50 shadow-sm flex items-center justify-center"
                 >
                    <Reply className="w-4 h-4 mr-2" /> Return / Refund
                 </button>
                 <button 
                    onClick={onVoid}
                    className="py-2 bg-red-600 text-white rounded-lg text-xs font-bold uppercase tracking-wide hover:bg-red-700 shadow-sm flex items-center justify-center"
                 >
                    <Ban className="w-4 h-4 mr-2" /> Void Transaction
                 </button>
              </div>
           )}
        </div>

        {/* --- PRINTABLE RECEIPT SECTION (Visible only in Print) --- */}
        <div id="printable-receipt" className={`hidden print:block bg-white p-4 text-xs font-mono text-black mx-auto ${receiptWidthClass}`}>
            <div className="text-center mb-4">
              {settings?.receiptLogoUrl && (
                 <img src={settings.receiptLogoUrl} alt="Logo" className="h-12 w-auto mx-auto mb-2 object-contain" />
              )}
              <h2 className="text-lg font-bold mb-1">{settings?.companyName || 'BuildMaster Store'}</h2>
              <p>{settings?.address}</p>
              <p>{settings?.phone}</p>
              {settings?.receiptShowTaxId && settings.taxId && <p>Tax ID: {settings.taxId}</p>}

              <div className="border-b border-dashed border-black my-2"></div>

              <div className="flex justify-between">
                 <span>Inv: #{sale.id.slice(-8)}</span>
                 <span>{new Date(sale.date).toLocaleDateString()}</span>
              </div>
              {sale.customerName && <div className="text-left mt-1">Cust: {sale.customerName}</div>}
              {sale.status === 'voided' && <div className="font-bold text-center mt-1">[ VOIDED ]</div>}
            </div>

            <div className="border-b border-dashed border-black my-2"></div>

            <div className="space-y-1 mb-2">
              {sale.items.map((item, i) => (
                <div key={i} className="flex justify-between">
                  <span className="truncate w-32">{item.name}</span>
                  <span className="text-right">
                    {item.quantity} x {formatPrice(item.sellPrice)}
                  </span>
                  <span className="font-bold text-right w-16">
                    {formatPrice(item.quantity * item.sellPrice)}
                  </span>
                </div>
              ))}
            </div>

            <div className="border-b border-dashed border-black my-2"></div>

            <div className="space-y-1">
              <div className="flex justify-between">
                <span>Subtotal</span>
                <span>{formatPrice(sale.subtotal || sale.total)}</span>
              </div>
              {sale.discountAmount ? (
                <div className="flex justify-between">
                  <span>Discount</span>
                  <span>-{formatPrice(sale.discountAmount)}</span>
                </div>
              ) : null}

              <div className="flex justify-between font-bold text-sm mt-1 pt-1 border-t border-black">
                <span>Total</span>
                <span>{formatPrice(sale.total)}</span>
              </div>
            </div>

            <div className="border-b border-dashed border-black my-3"></div>

            <div className="space-y-1">
              <div className="flex justify-between">
                <span className="capitalize">Paid via {sale.paymentMethod}</span>
                <span>{formatPrice(sale.amountReceived && sale.amountReceived > 0 ? sale.amountReceived : 0)}</span>
              </div>

              {(sale.paymentStatus === 'unpaid' || sale.paymentStatus === 'partial') && (
                 <div className="flex justify-between font-bold">
                    <span>Balance Due</span>
                    <span>{formatPrice(sale.remainingAmount || 0)}</span>
                 </div>
              )}

              {sale.change !== undefined && sale.change > 0 && (
                <div className="flex justify-between font-bold">
                  <span>Change</span>
                  <span>{formatPrice(sale.change)}</span>
                </div>
              )}
            </div>

            <div className="mt-6 text-center italic">
              <p className="mb-1">{settings?.receiptHeader}</p>
              <p>{settings?.receiptFooter}</p>
              <p className="text-[9px] mt-2 text-slate-500">Reprinted: {new Date().toLocaleString()}</p>
            </div>
        </div>

        {/* Modal Footer - Hidden on Print */}
        <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-slate-50 rounded-b-xl print:hidden">
           {isReturnMode ? (
              <>
                 <button 
                    onClick={toggleReturnMode}
                    className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50"
                 >
                    Cancel Return
                 </button>
                 <button 
                    onClick={handleSubmitReturn}
                    className="px-6 py-2 bg-red-600 text-white font-bold rounded-lg hover:bg-red-700 shadow-sm"
                 >
                    Confirm Refund
                 </button>
              </>
           ) : (
              <>
                 <button 
                    onClick={handlePrint}
                    className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50 flex items-center shadow-sm"
                 >
                    <Printer className="w-4 h-4 mr-2" />
                    Reprint Bill
                 </button>
                 <button 
                    onClick={onClose}
                    className="px-4 py-2 bg-slate-800 text-white font-medium rounded-lg hover:bg-slate-900"
                 >
                    Close
                 </button>
              </>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useRef } from 'react';
import { User } from '../../types';
import { Camera, MapPin, UserCircle } from 'lucide-react';

interface ProfileHeaderProps {
  user: User;
  branchName: string;
  stats: {
    shifts: number;
    orders: number;
    revenue: string;
  };
  onUpdateAvatar: (file: File) => void;
  onUpdateCover: (file: File) => void;
}

export const ProfileHeader: React.FC<ProfileHeaderProps> = ({ 
  user, branchName, stats, onUpdateAvatar, onUpdateCover 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const coverInputRef = useRef<HTMLInputElement>(null);

  const getRoleBadgeColor = (role: string) => {
    switch(role) {
      case 'Admin': return 'bg-purple-100 text-purple-700 border-purple-200';
      case 'Manager': return 'bg-indigo-100 text-indigo-700 border-indigo-200';
      case 'Staff': return 'bg-blue-100 text-blue-700 border-blue-200';
      default: return 'bg-green-100 text-green-700 border-green-200';
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, callback: (file: File) => void) => {
    const file = e.target.files?.[0];
    if (file) callback(file);
  };

  return (
    <div className="relative rounded-3xl overflow-hidden bg-white shadow-sm border border-slate-200 group">
      {/* Cover Image */}
      <div className="h-48 md:h-64 bg-gradient-to-r from-slate-800 to-slate-900 relative">
         {user.coverUrl ? (
            <img src={user.coverUrl} alt="Cover" className="w-full h-full object-cover" />
