import React, { useState, useMemo } from 'react';
import { Sale } from '../../../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';

interface PerformanceTabProps {
  sales: Sale[];
  formatPrice: (val: number) => string;
}

type TimeRange = 'week' | 'month' | 'year';
const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8'];

export const PerformanceTab: React.FC<PerformanceTabProps> = ({ sales, formatPrice }) => {
  const [timeRange, setTimeRange] = useState<TimeRange>('month');

  const { chartData, periodRevenue, periodOrders, periodAvg, paymentChartData } = useMemo(() => {
    const now = new Date();
    let startDate = new Date();
    let groupBy: 'day' | 'month' = 'day';

    switch (timeRange) {
      case 'week':
        startDate.setDate(now.getDate() - 7);
        groupBy = 'day';
        break;
      case 'month':
        startDate.setMonth(now.getMonth() - 1);
        groupBy = 'day';
        break;
      case 'year':
        startDate.setFullYear(now.getFullYear() - 1);
        groupBy = 'month';
        break;
    }

    const filteredSales = sales.filter(s => new Date(s.date) >= startDate);

    const groupedData = new Map<string, { date: string; sortKey: number; revenue: number; count: number }>();
    const paymentMethods: Record<string, number> = {};

    filteredSales.forEach(sale => {
       const d = new Date(sale.date);
       let key = '';
       let sortKey = 0;

       if (groupBy === 'month') {
          key = d.toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
          sortKey = d.getFullYear() * 100 + d.getMonth();
       } else {
          key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
          sortKey = d.getTime();
       }

       const existing = groupedData.get(key) || { date: key, sortKey, revenue: 0, count: 0 };
       existing.revenue += sale.total;
       existing.count += 1;
       groupedData.set(key, existing);

       const method = sale.paymentMethod || 'cash';
       paymentMethods[method] = (paymentMethods[method] || 0) + sale.total;
    });

    const chartData = Array.from(groupedData.values()).sort((a, b) => a.sortKey - b.sortKey);
    const periodRevenue = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const periodOrders = filteredSales.length;
    const periodAvg = periodOrders > 0 ? periodRevenue / periodOrders : 0;

    const paymentChartData = Object.entries(paymentMethods).map(([name, value]) => ({ name, value }));

    return { chartData, periodRevenue, periodOrders, periodAvg, paymentChartData };
  }, [sales, timeRange]);

  return (
     <div className="space-y-6 animate-fade-in">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
           <h3 className="text-lg font-bold text-slate-800">Sales Analytics</h3>
           <div className="flex bg-slate-100 p-1 rounded-lg overflow-x-auto">
              {(['week', 'month', 'year'] as const).map(p => (
                 <button
                    key={p}
                    onClick={() => setTimeRange(p)}
                    className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all capitalize ${
                       timeRange === p ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                    }`}
                 >
                    {p}
                 </button>
              ))}
           </div>
        </div>

        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm h-[300px]">
           <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                 <defs>
                    <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                       <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                       <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                    </linearGradient>
                 </defs>
                 <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                 <XAxis dataKey="date" stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} />
                 <YAxis stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} tickFormatter={(val) => `${val/1000}k`} />
                 <Tooltip 
                    contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0' }}
                    formatter={(val: number) => formatPrice(val)}
                 />
                 <Area type="monotone" dataKey="revenue" stroke="#3b82f6" strokeWidth={2} fillOpacity={1} fill="url(#colorRev)" />
              </AreaChart>
           </ResponsiveContainer>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
           <div className="bg-slate-50 p-6 rounded-xl border border-slate-200">
              <h4 className="font-bold text-slate-700 mb-4 text-sm">Payment Methods</h4>
              <div className="h-48">
                 <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                       <Pie
                          data={paymentChartData}
                          cx="50%"
                          cy="50%"
                          innerRadius={40}
                          outerRadius={60}
                          paddingAngle={5}
                          dataKey="value"
                       >
                          {paymentChartData.map((entry, index) => (
                             <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                          ))}
                       </Pie>
                       <Tooltip formatter={(val: number) => formatPrice(val)} />
                    </PieChart>
                 </ResponsiveContainer>
              </div>
              <div className="flex flex-wrap justify-center gap-3 mt-2">
                 {paymentChartData.map((entry, index) => (
                    <div key={index} className="flex items-center text-xs text-slate-600">
                       <div className="w-2 h-2 rounded-full mr-1" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                       <span className="capitalize">{entry.name}</span>
                    </div>
                 ))}
              </div>
           </div>

           <div className="bg-slate-50 p-6 rounded-xl border border-slate-200">
              <h4 className="font-bold text-slate-700 mb-4 text-sm">Period Summary</h4>
              <div className="space-y-4">
                 <div className="flex justify-between items-center pb-3 border-b border-slate-200">
                    <span className="text-sm text-slate-500">Total Revenue</span>
                    <span className="font-bold text-slate-800">{formatPrice(periodRevenue)}</span>
                 </div>
                 <div className="flex justify-between items-center pb-3 border-b border-slate-200">
                    <span className="text-sm text-slate-500">Total Orders</span>
                    <span className="font-bold text-slate-800">{periodOrders}</span>
                 </div>
                 <div className="flex justify-between items-center">
                    <span className="text-sm text-slate-500">Avg. Ticket Size</span>
                    <span className="font-bold text-green-600">{formatPrice(periodAvg)}</span>
                 </div>
              </div>
           </div>
        </div>
     </div>
  );
};

import React, { useState } from 'react';
import { User } from '../../../types';
import { Shield, Lock, Save, CheckCircle, AlertCircle, Globe, Smartphone } from 'lucide-react';

interface SecurityTabProps {
  user: User;
  onUpdatePassword: (current: string, next: string) => Promise<void>;
}

export const SecurityTab: React.FC<SecurityTabProps> = ({ user, onUpdatePassword }) => {
  const [passForm, setPassForm] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [status, setStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus({ type: 'idle', message: '' });

    if (passForm.newPassword !== passForm.confirmPassword) {
      setStatus({ type: 'error', message: 'New passwords do not match' });
      return;
    }

    if (passForm.newPassword.length < 6) {
      setStatus({ type: 'error', message: 'Password must be at least 6 characters' });
      return;
    }

    setIsSubmitting(true);
    try {
      await onUpdatePassword(passForm.currentPassword, passForm.newPassword);
      setStatus({ type: 'success', message: 'Password changed successfully' });
      setPassForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
    } catch (err: any) {
      setStatus({ type: 'error', message: err.message || 'Failed to update password' });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
     <div className="max-w-lg mx-auto animate-fade-in">
        <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-200 mb-8 flex items-start">
           <Shield className="w-5 h-5 text-yellow-600 mr-3 mt-0.5" />
           <div>
              <h4 className="font-bold text-yellow-800 text-sm">Security Recommendations</h4>
              <ul className="text-xs text-yellow-700 mt-2 space-y-1 list-disc list-inside">
                 <li>Use a strong password with at least 8 characters.</li>
                 <li>Include numbers and symbols.</li>
                 <li>Do not share your account credentials.</li>
              </ul>
           </div>
        </div>

        <form onSubmit={handleSubmit} className="space-y-5">
           <div>
              <label className="block text-sm font-bold text-slate-700 mb-1.5">Current Password</label>
              <div className="relative group">
                 <Lock className="absolute left-3 top-3 w-4 h-4 text-slate-400 group-focus-within:text-orange-500 transition-colors" />
                 <input 
                    type="password" 
                    required
                    value={passForm.currentPassword}
                    onChange={e => setPassForm({...passForm, currentPassword: e.target.value})}
                    className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all bg-white"
                    placeholder="Enter current password"
                 />
              </div>
           </div>

           <div>
              <label className="block text-sm font-bold text-slate-700 mb-1.5">New Password</label>
              <div className="relative group">
                 <Lock className="absolute left-3 top-3 w-4 h-4 text-slate-400 group-focus-within:text-orange-500 transition-colors" />
                 <input 
                    type="password" 
                    required
                    value={passForm.newPassword}
                    onChange={e => setPassForm({...passForm, newPassword: e.target.value})}
                    className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all bg-white"
                    placeholder="At least 6 characters"
                 />
              </div>
           </div>

           <div>
              <label className="block text-sm font-bold text-slate-700 mb-1.5">Confirm New Password</label>
              <div className="relative group">
                 <Lock className="absolute left-3 top-3 w-4 h-4 text-slate-400 group-focus-within:text-orange-500 transition-colors" />
                 <input 
                    type="password" 
                    required
                    value={passForm.confirmPassword}
                    onChange={e => setPassForm({...passForm, confirmPassword: e.target.value})}
                    className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all bg-white"
                    placeholder="Re-enter new password"
                 />
              </div>
           </div>

           {status.message && (
              <div className={`p-4 rounded-xl text-sm flex items-start shadow-sm ${status.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
                 {status.type === 'success' ? <CheckCircle className="w-5 h-5 mr-3 mt-0.5 shrink-0" /> : <AlertCircle className="w-5 h-5 mr-3 mt-0.5 shrink-0" />}
                 <span className="font-medium">{status.message}</span>
              </div>
           )}

           <div className="pt-2">
              <button 
                 type="submit" 
                 disabled={isSubmitting}
                 className="flex items-center justify-center w-full py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-all font-bold shadow-lg disabled:opacity-70 disabled:cursor-not-allowed hover:shadow-xl transform active:scale-[0.98]"
              >
                 {isSubmitting ? 'Updating...' : <><Save className="w-4 h-4 mr-2" /> Update Password</>}
              </button>
           </div>
        </form>

        <div className="mt-8 pt-8 border-t border-slate-100">
           <h4 className="font-bold text-slate-800 mb-4 text-sm">Recent Login Sessions</h4>
           <div className="space-y-3">
              <div className="flex justify-between items-center text-sm p-3 bg-slate-50 rounded-lg">
                 <div className="flex items-center">
                    <Globe className="w-4 h-4 text-slate-400 mr-2" />
                    <span className="font-medium text-slate-700">Chrome on Windows</span>
                 </div>
                 <span className="text-green-600 text-xs font-bold bg-green-50 px-2 py-1 rounded-full border border-green-100">Active Now</span>
              </div>
              <div className="flex justify-between items-center text-sm p-3 bg-white border border-slate-100 rounded-lg">
                 <div className="flex items-center">
                    <Smartphone className="w-4 h-4 text-slate-400 mr-2" />
                    <span className="font-medium text-slate-600">Safari on iPhone</span>
                 </div>
                 <span className="text-slate-400 text-xs">2 days ago</span>
              </div>
           </div>
        </div>
     </div>
  );
};

import React, { useState, useMemo } from 'react';
import { User, Shift, Sale } from '../types';
import { 
  BarChart4, 
  TrendingUp, 
  Lock, 
  Globe 
} from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { verifyPasswordSync, hashPasswordSync } from '../lib/auth';

// Sub-components
import { ProfileHeader } from './profile/ProfileHeader';
import { ProfileSidebar } from './profile/ProfileSidebar';
import { OverviewTab } from './profile/tabs/OverviewTab';
import { PerformanceTab } from './profile/tabs/PerformanceTab';
import { SecurityTab } from './profile/tabs/SecurityTab';
import { SettingsTab } from './profile/tabs/SettingsTab';

interface UserProfileProps {
  user: User;
  shifts: Shift[];
  sales: Sale[];
}

export const UserProfile: React.FC<UserProfileProps> = ({ user, shifts, sales }) => {
  const { updateUser, branches, formatPrice } = useGlobal();
  const [activeTab, setActiveTab] = useState<'overview' | 'performance' | 'security' | 'settings'>('overview');

  // Stats Logic
  const myShifts = useMemo(() => shifts.filter(s => s.userId === user.id), [shifts, user.id]);
  const mySales = useMemo(() => sales.filter(s => s.userId === user.id && s.status !== 'voided'), [sales, user.id]);
  const totalSalesValue = mySales.reduce((acc, s) => acc + s.total, 0);
  const branchName = branches.find(b => b.id === user.branchId)?.name || 'Unassigned';

  const stats = {
    shifts: myShifts.length,
    orders: mySales.length,
    revenue: formatPrice(totalSalesValue)
  };

  // Image Upload Handlers
  const handleUpdateAvatar = (file: File) => {
    if (file.size > 2 * 1024 * 1024) return alert('File too large (Max 2MB)');
    const reader = new FileReader();
    reader.onloadend = () => updateUser({ ...user, avatarUrl: reader.result as string });
    reader.readAsDataURL(file);
  };

  const handleUpdateCover = (file: File) => {
    if (file.size > 3 * 1024 * 1024) return alert('File too large (Max 3MB)');
    const reader = new FileReader();
    reader.onloadend = () => updateUser({ ...user, coverUrl: reader.result as string });
    reader.readAsDataURL(file);
  };

  // Password Logic (Abstracted)
  const handleUpdatePassword = async (current: string, next: string) => {
    try {
      const res = await fetch('/api/auth/change-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: user.id, currentPassword: current, newPassword: next })
      });

      if (!res.ok) {
        // Fallback for offline/demo
        const isValid = verifyPasswordSync(current, user.password || '');
        if (isValid) {
           const newHash = hashPasswordSync(next);
           updateUser({ ...user, password: newHash });
           return; 
        }
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || 'Password update failed');
      }
    } catch (err: any) {
       // Allow local update if API fails (Demo mode)
       try {
         const isValid = verifyPasswordSync(current, user.password || '');
         if (isValid) {
            const newHash = hashPasswordSync(next);
            updateUser({ ...user, password: newHash });
            return;
         }
       } catch (e) {
         throw err;
       }
       throw err;
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-20">
      <ProfileHeader 
        user={user} 
        branchName={branchName} 
        stats={stats}
        onUpdateAvatar={handleUpdateAvatar} 
        onUpdateCover={handleUpdateCover} 
      />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column */}
        <ProfileSidebar user={user} />

        {/* Right Content */}
        <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-200 flex flex-col min-h-[500px]">
           <div className="flex border-b border-slate-100 overflow-x-auto">
              {[
                 { id: 'overview', label: 'Overview', icon: BarChart4 },
                 { id: 'performance', label: 'Performance', icon: TrendingUp },
                 { id: 'security', label: 'Security', icon: Lock },
                 { id: 'settings', label: 'Preferences', icon: Globe },
              ].map(tab => {
                 const Icon = tab.icon;
                 return (
                    <button 
                       key={tab.id}
                       onClick={() => setActiveTab(tab.id as any)}
                       className={`flex items-center px-6 py-4 text-sm font-bold transition-all whitespace-nowrap border-b-2 ${
                          activeTab === tab.id 
                             ? 'border-orange-500 text-orange-600 bg-orange-50/20' 
                             : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'
                       }`}
                    >
                       <Icon className="w-4 h-4 mr-2" />
                       {tab.label}
                    </button>
                 )
              })}
           </div>

           <div className="p-6 md:p-8 flex-1">
              {activeTab === 'overview' && <OverviewTab shifts={myShifts} totalSalesValue={totalSalesValue} formatPrice={formatPrice} />}
              {activeTab === 'performance' && <PerformanceTab sales={mySales} formatPrice={formatPrice} />}
              {activeTab === 'security' && <SecurityTab user={user} onUpdatePassword={handleUpdatePassword} />}
              {activeTab === 'settings' && <SettingsTab />}
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { CategoryItem } from '../../types';
import { 
  Folder, 
  FolderOpen, 
  ChevronRight, 
  ChevronDown, 
  Plus, 
  Edit2, 
  Trash2,
  Layers
} from 'lucide-react';

interface TreeNodeProps {
  node: CategoryItem;
  level: number;
  allCategories: CategoryItem[];
  onAdd: (parentId: string | null) => void;
  onEdit: (cat: CategoryItem) => void;
  onDelete: (id: string) => void;
}

const CategoryTreeNode: React.FC<TreeNodeProps> = ({ 
  node, 
  level, 
  allCategories, 
  onAdd, 
  onEdit, 
  onDelete 
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const children = allCategories.filter(c => c.parentId === node.id);
  const hasChildren = children.length > 0;

  const handleToggle = () => setIsExpanded(!isExpanded);

  return (
    <div className="select-none">
      <div 
        className={`flex items-center p-3 hover:bg-slate-50 border-b border-slate-100 transition-colors group ${level === 0 ? 'bg-white' : ''}`}
        style={{ paddingLeft: `${level * 24 + 12}px` }}
      >
        <div className="flex items-center flex-1">
          <button 
            onClick={handleToggle}
            className={`mr-2 p-1 rounded-md text-slate-400 hover:bg-slate-200 transition-colors ${!hasChildren ? 'invisible' : ''}`}
          >
            {isExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
          </button>

          <div className={`mr-3 p-1.5 rounded-lg ${level === 0 ? 'bg-blue-50 text-blue-600' : 'bg-slate-100 text-slate-500'}`}>
            {isExpanded ? <FolderOpen className="w-5 h-5" /> : <Folder className="w-5 h-5" />}
          </div>

          <div className="flex flex-col">
            <span className={`font-medium ${level === 0 ? 'text-slate-800' : 'text-slate-700'}`}>
              {node.name}
            </span>
            {node.description && (
              <span className="text-xs text-slate-400">{node.description}</span>
            )}
          </div>
        </div>

        <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity px-2">
          <button 
            onClick={() => onAdd(node.id)}
            title="Add Sub-category"
            className="p-1.5 text-slate-400 hover:text-green-600 hover:bg-green-50 rounded transition-colors"
          >
            <Plus className="w-4 h-4" />
          </button>
          <button 
            onClick={() => onEdit(node)}
            title="Edit"
            className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-primary-50 rounded transition-colors"
          >
            <Edit2 className="w-4 h-4" />
          </button>
          <button 
            onClick={() => onDelete(node.id)}
            title="Delete"
            className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
          >
            <Trash2 className="w-4 h-4" />
          </button>
        </div>
      </div>

      {isExpanded && children.map(child => (
        <CategoryTreeNode 
          key={child.id} 
          node={child} 
          level={level + 1} 
          allCategories={allCategories}
          onAdd={onAdd}
          onEdit={onEdit}
          onDelete={onDelete}
        />
      ))}
    </div>
  );
};

interface CategoryTreeProps {
  categories: CategoryItem[];
  onAdd: (parentId: string | null) => void;
  onEdit: (cat: CategoryItem) => void;
  onDelete: (id: string) => void;
}

export const CategoryTree: React.FC<CategoryTreeProps> = ({ categories, onAdd, onEdit, onDelete }) => {
  const rootCategories = categories.filter(c => c.parentId === null);

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
      <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center text-sm font-semibold text-slate-500 uppercase tracking-wide">
        <Layers className="w-4 h-4 mr-2" />
        Category Structure
      </div>
      <div className="overflow-y-auto flex-1">
        {rootCategories.length === 0 ? (
           <div className="flex flex-col items-center justify-center h-full text-slate-400">
             <Layers className="w-12 h-12 mb-4 opacity-20" />
             <p>No categories defined.</p>
           </div>
        ) : (
          rootCategories.map(node => (
            <CategoryTreeNode 
              key={node.id}
              node={node}
              level={0}
              allCategories={categories}
              onAdd={onAdd}
              onEdit={onEdit}
              onDelete={onDelete}
            />
          ))
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CategoryItem } from '../../types';
import { X, CornerDownRight } from 'lucide-react';

interface CategoryFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: Partial<CategoryItem>) => void;
  initialData: Partial<CategoryItem>;
  parentName: string;
}

export const CategoryFormModal: React.FC<CategoryFormModalProps> = ({
  isOpen, onClose, onSubmit, initialData, parentName
}) => {
  const [formData, setFormData] = useState<Partial<CategoryItem>>(initialData);

  useEffect(() => {
    setFormData(initialData);
  }, [initialData, isOpen]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit(formData);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-md animate-fade-in">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
          <div>
            <h3 className="text-xl font-bold text-slate-800">
              {initialData.id ? 'Edit Category' : 'Add New Category'}
            </h3>
            <p className="text-sm text-slate-500 mt-1 flex items-center">
              <CornerDownRight className="w-3 h-3 mr-1" />
              Parent: <span className="font-semibold ml-1">{parentName}</span>
            </p>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
            <X className="w-6 h-6" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Category Name</label>
            <input
              type="text"
              required
              value={formData.name || ''}
              onChange={e => setFormData({...formData, name: e.target.value})}
              className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
              placeholder="e.g. Electrical Fittings"
              autoFocus
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Description (Optional)</label>
            <textarea
              value={formData.description || ''}
              onChange={e => setFormData({...formData, description: e.target.value})}
              className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 resize-none h-24"
              placeholder="Additional details..."
            />
          </div>

          <div className="flex items-center justify-end space-x-3 pt-4 border-t border-slate-100">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 transition-colors shadow-sm"
            >
              Save
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { CategoryItem } from '../types';
import { Plus } from 'lucide-react';
import { CategoryTree } from './category/CategoryTree';
import { CategoryFormModal } from './category/CategoryFormModal';

interface CategoryManagementProps {
  categories: CategoryItem[];
  onAddCategory: (category: CategoryItem) => void;
  onUpdateCategory: (category: CategoryItem) => void;
  onDeleteCategory: (id: string) => void;
}

export const CategoryManagement: React.FC<CategoryManagementProps> = ({ 
  categories, 
  onAddCategory, 
  onUpdateCategory, 
  onDeleteCategory 
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCat, setEditingCat] = useState<CategoryItem | null>(null);

  const [formData, setFormData] = useState<Partial<CategoryItem>>({
    name: '',
    description: '',
    parentId: null
  });

  const handleOpenAdd = (parentId: string | null) => {
    setEditingCat(null);
    setFormData({
      name: '',
      description: '',
      parentId: parentId
    });
    setIsModalOpen(true);
  };

  const handleOpenEdit = (cat: CategoryItem) => {
    setEditingCat(cat);
    setFormData({ ...cat });
    setIsModalOpen(true);
  };

  const handleSubmit = (data: Partial<CategoryItem>) => {
    if (editingCat) {
      onUpdateCategory({ ...data, id: editingCat.id } as CategoryItem);
    } else {
      onAddCategory({
        ...data,
        id: `c-${Date.now()}`,
      } as CategoryItem);
    }
    setIsModalOpen(false);
  };

  const getParentName = (id: string | null | undefined) => {
    if (!id) return 'Root (Top Level)';
    const parent = categories.find(c => c.id === id);
    return parent ? parent.name : 'Unknown';
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Category Management</h2>
          <p className="text-slate-500">Organize product hierarchy with nested categories.</p>
        </div>
        <button 
          onClick={() => handleOpenAdd(null)}
          className="flex items-center justify-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 transition-colors font-medium shadow-sm"
        >
          <Plus className="w-4 h-4 mr-2" />
          Add Root Category
        </button>
      </div>

      <CategoryTree 
        categories={categories}
        onAdd={handleOpenAdd}
        onEdit={handleOpenEdit}
        onDelete={onDeleteCategory}
      />

      <CategoryFormModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSubmit={handleSubmit}
        initialData={formData}
        parentName={getParentName(formData.parentId)}
      />
    </div>
  );
};

