import React from 'react';
import { Product, StockItem } from '../../../types';
import { Plus, Trash2 } from 'lucide-react';

interface StockItemsTableProps {
  items: any[];
  setItems: (items: any[]) => void;
  products: Product[];
  isReadOnly: boolean;
  activeTab: string;
}

export const StockItemsTable: React.FC<StockItemsTableProps> = ({ 
  items, setItems, products, isReadOnly, activeTab 
}) => {

  const handleAddItem = () => {
    if (!products.length) return;
    const p = products[0];
    const newItem: StockItem = {
      productId: p.id,
      productName: p.name,
      unit: p.unit,
      quantity: 1
    };
    setItems([...(items || []), newItem]);
  };

  const handleUpdateItem = (index: number, field: string, value: any) => {
    const newItems = [...items];
    if (field === 'productId') {
        const p = products.find(prod => prod.id === value);
        if (p) {
            newItems[index] = { ...newItems[index], productId: p.id, productName: p.name, unit: p.unit };
        }
    } else {
        newItems[index] = { ...newItems[index], [field]: value };
    }
    setItems(newItems);
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...items];
    newItems.splice(index, 1);
    setItems(newItems);
  };

  return (
    <div className="border-t border-slate-100 pt-4">
       <div className="flex justify-between items-center mb-2">
          <h4 className="font-bold text-slate-700">Items</h4>
          {!isReadOnly && (
            <button type="button" onClick={handleAddItem} className="text-sm text-blue-600 hover:underline flex items-center font-medium bg-blue-50 px-3 py-1.5 rounded-lg"><Plus className="w-4 h-4 mr-1"/> Add Item</button>
          )}
       </div>
       <div className="space-y-3">
          {items?.map((item: any, idx: number) => (
             <div key={idx} className="flex flex-col md:flex-row gap-3 items-start md:items-center bg-slate-50 p-3 rounded-lg border border-slate-200">
                <select 
                   disabled={isReadOnly}
                   value={item.productId} 
                   onChange={e => handleUpdateItem(idx, 'productId', e.target.value)} 
                   className="w-full md:flex-1 px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white disabled:bg-slate-100"
                >
                   {products.map(p => <option key={p.id} value={p.id}>{p.name} ({p.unit})</option>)}
                </select>

                <div className="flex gap-2 w-full md:w-auto items-center">
                   {activeTab === 'count' ? (
                      <div className="flex-1 md:w-24">
                         <input 
                            disabled={isReadOnly}
                            type="number" 
                            value={item.countedQuantity !== undefined ? item.countedQuantity : ''} 
                            onChange={e => handleUpdateItem(idx, 'countedQuantity', parseFloat(e.target.value))} 
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm disabled:bg-slate-100 font-medium"
                            placeholder="Count"
                         />
                      </div>
                   ) : (
                      <div className="flex-1 md:w-24">
                         <input 
                            disabled={isReadOnly}
                            type="number" 
                            value={item.quantity || 0} 
                            onChange={e => handleUpdateItem(idx, 'quantity', parseFloat(e.target.value))} 
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm disabled:bg-slate-100 font-medium"
                            placeholder="Qty"
                         />
                      </div>
                   )}

                   {!isReadOnly && (
                       <button type="button" onClick={() => handleRemoveItem(idx)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg border border-transparent hover:border-red-200"><Trash2 className="w-4 h-4"/></button>
                   )}
                </div>
             </div>
          ))}
          {(!items || items.length === 0) && (
             <div className="text-center py-8 text-slate-400 text-sm italic border-2 border-dashed border-slate-100 rounded-lg">No items added yet.</div>
          )}
       </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Warehouse, Product } from '../../types';
import { Edit2, Plus, X, AlertCircle, CheckCircle, PlayCircle } from 'lucide-react';
import { StockHeaderFields } from './document-form/StockHeaderFields';
import { StockItemsTable } from './document-form/StockItemsTable';

interface StockDocumentModalProps {
  isOpen: boolean;
  onClose: () => void;
  activeTab: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment';
  editingId: string | null;
  initialData: any;
  warehouses: Warehouse[];
  products: Product[];
  onSave: (data: any) => void;
  onComplete: (data: any) => void;
}

export const StockDocumentModal: React.FC<StockDocumentModalProps> = ({
  isOpen, onClose, activeTab, editingId, initialData, warehouses, products, onSave, onComplete
}) => {
  const [formData, setFormData] = useState<any>(initialData);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setFormData(initialData);
    setError(null);
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const isReadOnly = formData.status !== 'Draft';

  const validateForm = () => {
    if (!formData.date) return 'Date is required';
    if (activeTab === 'transfer') {
        if (!formData.sourceWarehouseId) return 'Source Warehouse is required';
        if (!formData.targetWarehouseId) return 'Target Warehouse is required';
        if (formData.sourceWarehouseId === formData.targetWarehouseId) return 'Source and Target warehouses cannot be the same';
    }
    if (['adjustment', 'count', 'receipt', 'reservation'].includes(activeTab)) {
        if (!formData.warehouseId) return 'Warehouse is required';
    }
    if (activeTab === 'receipt' && !formData.vendorName) return 'Vendor Name is required';
    if (activeTab === 'reservation') {
        if (!formData.customerName) return 'Customer Name is required';
        if (!formData.expiryDate) return 'Expiry Date is required';
    }
    if (activeTab === 'count' && !formData.counterName) return 'Counter Name is required';
    if (activeTab === 'adjustment' && !formData.reason) return 'Reason is required';
    return null;
  };

  const handleSaveClick = () => {
    const err = validateForm();
    if (err) {
      setError(err);
      return;
    }
    onSave(formData);
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[60] p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[95vh] flex flex-col overflow-hidden animate-fade-in">
        <div className="p-4 md:p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
          <h3 className="text-lg md:text-xl font-bold text-slate-800 uppercase flex items-center">
            {editingId ? <Edit2 className="w-5 h-5 mr-2 text-blue-500" /> : <Plus className="w-5 h-5 mr-2 text-green-500" />}
            {editingId ? 'Edit' : 'New'} {activeTab}
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto">
          <div className="p-4 md:p-6 space-y-4">

            {error && (
              <div className="p-3 bg-red-50 border border-red-100 rounded-lg text-red-600 text-sm flex items-center">
                <AlertCircle className="w-4 h-4 mr-2 flex-shrink-0" />
                {error}
              </div>
            )}

            <StockHeaderFields 
              activeTab={activeTab}
              formData={formData}
              setFormData={setFormData}
              warehouses={warehouses}
              isReadOnly={isReadOnly}
            />

            <StockItemsTable 
              items={formData.items}
              setItems={(items) => setFormData({...formData, items})}
              products={products}
              isReadOnly={isReadOnly}
              activeTab={activeTab}
            />
          </div>
        </div>

        <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-slate-50 shrink-0">
          <button
            type="button"
            onClick={onClose}
            className="px-5 py-2.5 text-slate-600 font-medium hover:bg-slate-200 rounded-lg transition-colors"
          >
            {isReadOnly ? 'Close' : 'Cancel'}
          </button>

          {formData.status === 'Draft' && (
             <button
                type="button"
                onClick={handleSaveClick}
                className="px-6 py-2.5 bg-construction-orange text-white font-bold rounded-lg hover:bg-orange-600 transition-colors shadow-sm"
             >
                Save Draft
             </button>
          )}

          {formData.status === 'Approved' && (
             <button
                type="button"
                onClick={() => onComplete(formData)}
                className="flex items-center px-6 py-2.5 bg-green-600 text-white font-bold rounded-lg hover:bg-green-700 transition-colors shadow-sm"
             >
                <PlayCircle className="w-4 h-4 mr-2" />
                Complete
             </button>
          )}

          {(formData.status === 'Completed' || formData.status === 'Cancelled') && (
             <span className={`flex items-center font-bold px-4 py-2 ${formData.status === 'Completed' ? 'text-green-600 bg-green-50 rounded-lg' : 'text-red-600 bg-red-50 rounded-lg'}`}>
                {formData.status === 'Completed' ? <CheckCircle className="w-5 h-5 mr-2" /> : <AlertCircle className="w-5 h-5 mr-2" />} 
                {formData.status}
             </span>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { ShiftSchedule, User } from '../../../types';
import { ChevronLeft, ChevronRight } from 'lucide-react';

interface RosterCalendarProps {
  shiftSchedules: ShiftSchedule[];
  users: User[];
  calendarDate: Date;
  setCalendarDate: (date: Date) => void;
  planningDate: string;
  setPlanningDate: (date: string) => void;
}

export const RosterCalendar: React.FC<RosterCalendarProps> = ({
  shiftSchedules, users, calendarDate, setCalendarDate, planningDate, setPlanningDate
}) => {

  const calendarGrid = useMemo(() => {
    const year = calendarDate.getFullYear();
    const month = calendarDate.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const startDay = new Date(year, month, 1).getDay();

    const days: { date: number; fullDate: string; schedules: ShiftSchedule[] }[] = [];

    for (let i = 0; i < startDay; i++) days.push({ date: 0, fullDate: '', schedules: [] });

    for (let i = 1; i <= daysInMonth; i++) {
        const fullDate = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
        const daySchedules = shiftSchedules.filter(s => s.date === fullDate);
        days.push({ date: i, fullDate, schedules: daySchedules });
    }
    return days;
  }, [calendarDate, shiftSchedules]);

  const handlePrevMonth = () => setCalendarDate(new Date(calendarDate.getFullYear(), calendarDate.getMonth() - 1, 1));
  const handleNextMonth = () => setCalendarDate(new Date(calendarDate.getFullYear(), calendarDate.getMonth() + 1, 1));

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 flex flex-col overflow-hidden">
        <div className="flex justify-between items-center p-4 border-b border-slate-100">
            <button onClick={handlePrevMonth} className="p-1 hover:bg-slate-100 rounded-full"><ChevronLeft className="w-5 h-5"/></button>
            <h3 className="font-bold text-lg text-slate-800">
                {calendarDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}
            </h3>
            <button onClick={handleNextMonth} className="p-1 hover:bg-slate-100 rounded-full"><ChevronRight className="w-5 h-5"/></button>
        </div>

        <div className="grid grid-cols-7 border-b border-slate-100 bg-slate-50 text-xs font-bold text-slate-500 uppercase text-center py-2">
            {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => <div key={d}>{d}</div>)}
        </div>

        <div className="flex-1 grid grid-cols-7 auto-rows-fr overflow-y-auto">
            {calendarGrid.map((day, idx) => {
                const isToday = day.fullDate === new Date().toISOString().split('T')[0];
                const isSelected = day.fullDate === planningDate;

                return (
                    <div 
                    key={idx} 
                    className={`border-b border-r border-slate-100 p-1 md:p-2 min-h-[60px] md:min-h-[100px] flex flex-col cursor-pointer transition-colors ${day.date === 0 ? 'bg-slate-50/50' : isSelected ? 'bg-blue-50' : 'bg-white hover:bg-slate-50'}`}
                    onClick={() => {
                        if(day.date !== 0) {
                            setPlanningDate(day.fullDate);
                        }
                    }}
                    >
                    {day.date !== 0 && (
                        <>
                            <div className="flex justify-between items-start">
                                <span className={`text-xs md:text-sm font-bold mb-1 w-6 h-6 flex items-center justify-center rounded-full ${isToday ? 'bg-blue-600 text-white' : 'text-slate-700'}`}>
                                {day.date}
                                </span>
                                <div className="md:hidden flex gap-0.5">
                                {day.schedules.length > 0 && <div className="w-1.5 h-1.5 rounded-full bg-orange-500"></div>}
                                </div>
                            </div>
                            <div className="hidden md:block space-y-1 overflow-y-auto max-h-[80px]">
                                {day.schedules.map(sch => {
                                const u = users.find(user => user.id === sch.userId);
                                return (
                                    <div key={sch.id} className={`text-[10px] px-1.5 py-0.5 rounded truncate font-medium border ${sch.isSwap ? 'bg-orange-50 text-orange-700 border-orange-100' : 'bg-blue-50 text-blue-700 border-blue-100'}`}>
                                        {u?.name.split(' ')[0]} ({sch.startTime})
                                    </div>
                                );
                                })}
                            </div>
                        </>
                    )}
                    </div>
                );
            })}
        </div>
    </div>
  );
};

import React from 'react';
import { ShiftSchedule, Shift, User, Branch } from '../../../types';
import { Calendar, MapPin, Clock, Edit2, Trash2, ArrowRightLeft } from 'lucide-react';

interface RosterListProps {
  filteredSchedules: ShiftSchedule[];
  planningDate: string;
  users: User[];
  branches: Branch[];
  shifts: Shift[];
  onEditSchedule: (schedule: ShiftSchedule) => void;
  onDeleteSchedule: (id: string) => void;
}

export const RosterList: React.FC<RosterListProps> = ({
  filteredSchedules, planningDate, users, branches, shifts, onEditSchedule, onDeleteSchedule
}) => {
  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-y-auto p-4 space-y-3">
        <h4 className="font-bold text-slate-700 mb-2">Schedule for {new Date(planningDate).toLocaleDateString()}</h4>
        {filteredSchedules.length === 0 ? (
        <div className="flex flex-col items-center justify-center h-48 text-slate-400">
            <Calendar className="w-12 h-12 mb-3 opacity-30" />
            <p>No shifts assigned for this date.</p>
        </div>
        ) : (
        filteredSchedules.map(schedule => {
            const user = users.find(u => u.id === schedule.userId);
            const branch = branches.find(b => b.id === schedule.branchId);
            const originalUser = schedule.originalUserId ? users.find(u => u.id === schedule.originalUserId) : null;

            const actualShift = shifts.find(s => 
                s.userId === schedule.userId && 
                s.branchId === schedule.branchId &&
                new Date(s.startTime).toISOString().split('T')[0] === schedule.date
            );

            let statusBadge = <span className="text-xs bg-slate-100 text-slate-500 px-2 py-0.5 rounded border">Scheduled</span>;

            if (actualShift) {
                if (actualShift.status === 'Open') {
                    statusBadge = <span className="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded border border-green-200 font-bold animate-pulse">Working Now</span>;
                } else {
                    statusBadge = <span className="text-xs bg-blue-100 text-blue-700 px-2 py-0.5 rounded border border-blue-200 font-bold">Completed</span>;
                }
            }

            return (
                <div key={schedule.id} className="flex items-center justify-between p-4 border border-slate-200 rounded-xl hover:border-blue-300 transition-colors bg-white group shadow-sm relative">
                    {schedule.isSwap && (
                    <span className="absolute top-2 right-2 flex items-center gap-1 px-1.5 py-0.5 bg-orange-100 text-orange-700 text-[10px] font-bold uppercase rounded border border-orange-200 tracking-wide" title={`Originally assigned to ${originalUser?.name || 'Unknown'}`}>
                        <ArrowRightLeft className="w-3 h-3" /> Swapped
                    </span>
                    )}
                    <div className="flex items-center space-x-4">
                    <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 font-bold text-sm">
                        {user?.name.charAt(0) || 'U'}
                    </div>
                    <div>
                        <div className="flex items-center gap-2">
                            <h4 className="font-bold text-slate-800">{user?.name || 'Unknown User'}</h4>
                            {statusBadge}
                        </div>
                        <div className="flex items-center text-xs text-slate-500 mt-1">
                            <span className="flex items-center mr-3">
                                <MapPin className="w-3 h-3 mr-1" /> {branch?.name}
                            </span>
                            <span className="flex items-center">
                                <Clock className="w-3 h-3 mr-1" /> {schedule.startTime} - {schedule.endTime}
                            </span>
                        </div>
                    </div>
                    </div>

                    <div className="flex space-x-2">
                    <button 
                        onClick={() => onEditSchedule(schedule)}
                        className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                        title="Edit Shift"
                    >
                        <Edit2 className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={() => onDeleteSchedule(schedule.id)}
                        className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                        title="Delete Shift"
                    >
                        <Trash2 className="w-4 h-4" />
                    </button>
                    </div>
                </div>
            );
        })
        )}
    </div>
  );
};

