import React from 'react';
import { ArrowLeft } from 'lucide-react';
import { useGlobal } from '../../../context/GlobalContext';

interface PaymentNumpadProps {
  receivedAmountStr: string;
  setReceivedAmountStr: React.Dispatch<React.SetStateAction<string>>;
  total: number;
  change: number;
  handleQuickCash: (amount: number) => void;
}

export const PaymentNumpad: React.FC<PaymentNumpadProps> = ({ 
  receivedAmountStr, setReceivedAmountStr, total, change, handleQuickCash 
}) => {
  const { formatPrice } = useGlobal();
  const receivedAmount = parseFloat(receivedAmountStr) || 0;

  const handleNumPadClick = (val: string) => {
    if (val === 'C') setReceivedAmountStr('');
    else if (val === 'BS') setReceivedAmountStr(prev => prev.slice(0, -1));
    else if (val === '.') {
      if (!receivedAmountStr.includes('.')) setReceivedAmountStr(prev => (prev === '' ? '0' : prev) + '.');
    } else {
      setReceivedAmountStr(prev => (prev === '0' ? val : prev + val));
    }
  };

  return (
    <div className="flex-1 flex flex-col max-w-lg mx-auto w-full">
        <div className="bg-slate-50 border border-slate-200 rounded-2xl p-6 mb-4 text-right shadow-inner relative">
            <span className="absolute top-4 left-4 text-xs font-bold text-slate-400 uppercase tracking-wide">Amount Received</span>
            <div className={`text-6xl font-bold tracking-tight ${receivedAmountStr ? 'text-slate-900' : 'text-slate-300'}`}>
                {receivedAmountStr ? formatPrice(parseFloat(receivedAmountStr)) : formatPrice(0)}
            </div>
        </div>
        <div className="flex justify-between items-end mb-6 px-2">
            <div>
                <p className="text-xs font-bold text-slate-400 uppercase mb-1">Change Due</p>
                <p className={`text-4xl font-bold ${change > 0 ? 'text-green-600' : 'text-slate-300'}`}>{formatPrice(change)}</p>
            </div>
            {(total - receivedAmount) > 0 && (
                <div className="text-right">
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Remaining</p>
                    <p className="text-2xl font-bold text-red-500">{formatPrice(total - receivedAmount)}</p>
                </div>
            )}
        </div>
        <div className="flex gap-3 flex-1 min-h-[320px]">
            <div className="grid grid-cols-3 gap-3 flex-[3]">
                {[1, 2, 3, 4, 5, 6, 7, 8, 9, '00', 0, 'BS'].map((btn) => (
                    <button
                    key={btn}
                    onClick={() => handleNumPadClick(btn.toString())}
                    className="bg-white border border-slate-200 rounded-xl text-2xl font-semibold text-slate-700 hover:bg-slate-50 hover:border-slate-300 active:scale-95 transition-all shadow-sm flex items-center justify-center"
                    >
                    {btn === 'BS' ? <ArrowLeft className="w-8 h-8" /> : btn}
                    </button>
                ))}
            </div>
            <div className="flex flex-col gap-3 flex-1">
                <button onClick={() => handleQuickCash(Math.ceil(total))} className="flex-1 bg-blue-50 text-blue-700 font-bold rounded-xl border border-blue-100 hover:bg-blue-100 transition-all text-sm shadow-sm">Exact</button>
                {[10000, 20000, 50000, 100000].map(val => (
                    <button key={val} onClick={() => handleQuickCash(val)} className="flex-1 bg-white text-slate-600 font-bold rounded-xl border border-slate-200 hover:bg-slate-50 transition-all text-xs shadow-sm">
                    {val/1000}k
                    </button>
                ))}
            </div>
        </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Customer } from '../../types';
import { X, Banknote, QrCode, CreditCard, FileText, ChevronLeft, CheckCircle } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';
import { PaymentMethodList } from './checkout/PaymentMethodList';
import { PaymentNumpad } from './checkout/PaymentNumpad';

interface CheckoutModalProps {
  isOpen: boolean;
  onClose: () => void;
  total: number;
  onProcessPayment: (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit', receivedAmount: number, change: number) => Promise<void>;
  selectedCustomer: Customer | null;
  isProcessing: boolean;
}

export const CheckoutModal: React.FC<CheckoutModalProps> = ({
  isOpen,
  onClose,
  total,
  onProcessPayment,
  selectedCustomer,
  isProcessing
}) => {
  const { formatPrice } = useGlobal();
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'qr' | 'credit'>('cash');
  const [receivedAmountStr, setReceivedAmountStr] = useState('');
  const [checkoutStep, setCheckoutStep] = useState<'method' | 'detail'>('method');

  if (!isOpen) return null;

  const receivedAmount = parseFloat(receivedAmountStr) || 0;
  const change = Math.max(0, receivedAmount - total);

  const selectPaymentMethod = (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit') => {
    if (method === 'credit' && !selectedCustomer) {
      alert("Credit payment requires a registered customer.");
      return;
    }
    setPaymentMethod(method);
    setReceivedAmountStr('');
    setCheckoutStep('detail');
  };

  const handleQuickCash = (amount: number) => {
    setReceivedAmountStr(amount.toString());
  };

  const handleProcess = () => {
    let finalReceived = paymentMethod === 'cash' || paymentMethod === 'credit' ? receivedAmount : total;
    let finalChange = paymentMethod === 'cash' ? change : 0;

    // Auto-fill exact amount for non-cash methods if not set
    if (paymentMethod !== 'cash' && paymentMethod !== 'credit') {
        finalReceived = total;
    }

    onProcessPayment(paymentMethod, finalReceived, finalChange);
  };

  const getConfirmButtonText = () => {
    if (isProcessing) return 'Processing...';

    if (paymentMethod === 'cash') {
      if (receivedAmount < total) return `Enter Amount (Due: ${formatPrice(total)})`;
      if (change > 0) return `Confirm Pay & Return ${formatPrice(change)}`;
      return `Confirm Payment ${formatPrice(total)}`;
    }

    if (paymentMethod === 'credit') {
       return `Confirm Credit Sale ${formatPrice(total)}`;
    }

    return `Confirm Payment ${formatPrice(total)}`;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/60 backdrop-blur-sm p-0 sm:p-4 animate-fade-in">
      <div className="bg-white w-full h-[90vh] sm:h-[650px] sm:max-w-5xl rounded-t-2xl sm:rounded-2xl shadow-2xl flex flex-col sm:flex-row overflow-hidden">

        {/* Method Selection Sidebar */}
        <PaymentMethodList 
            paymentMethod={paymentMethod}
            onSelect={selectPaymentMethod}
            onClose={onClose}
            total={total}
            selectedCustomer={selectedCustomer}
            className={checkoutStep === 'detail' ? 'hidden sm:flex' : 'flex'}
        />

        {/* Detail / Numpad Area */}
        <div className={`flex-1 bg-white flex flex-col ${checkoutStep === 'method' ? 'hidden sm:flex' : 'flex'} h-full`}>
           <div className="p-4 border-b border-slate-100 flex items-center justify-between sm:justify-end">
              <button onClick={() => setCheckoutStep('method')} className="sm:hidden flex items-center text-slate-500 font-medium hover:text-slate-800">
                 <ChevronLeft className="w-5 h-5 mr-1" /> Back
              </button>
              <button onClick={onClose} className="hidden sm:block p-2 hover:bg-slate-100 rounded-full text-slate-400">
                 <X className="w-6 h-6" />
              </button>
           </div>

           <div className="flex-1 p-4 sm:p-8 overflow-y-auto">
              <div className="text-center mb-6">
                 <h3 className="text-xl font-bold text-slate-800 flex items-center justify-center gap-2">
                    {paymentMethod === 'cash' ? <Banknote className="text-blue-600"/> : paymentMethod === 'qr' ? <QrCode className="text-blue-600"/> : <CreditCard className="text-blue-600"/>}
                    {paymentMethod === 'cash' ? 'Cash Payment' : paymentMethod === 'qr' ? 'Scan to Pay' : 'Digital Payment'}
                 </h3>
              </div>

              {paymentMethod === 'cash' ? (
                 <PaymentNumpad 
                    receivedAmountStr={receivedAmountStr}
                    setReceivedAmountStr={setReceivedAmountStr}
                    total={total}
                    change={change}
                    handleQuickCash={handleQuickCash}
                 />
              ) : paymentMethod === 'qr' ? (
                 <div className="flex-1 flex flex-col items-center justify-center">
                    <div className="bg-white p-6 rounded-3xl border-2 border-slate-100 shadow-lg mb-6">
                       <img src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=Payment_OnePay_${total}`} className="w-64 h-64 object-contain" alt="QR" />
                    </div>
                    <p className="text-lg font-bold text-slate-700">Scan to pay {formatPrice(total)}</p>
                 </div>
              ) : (
                 <div className="flex-1 flex flex-col items-center justify-center text-center">
                    <div className="w-32 h-32 bg-slate-100 rounded-full flex items-center justify-center mb-6 animate-pulse">
                       {paymentMethod === 'credit' ? <FileText className="w-16 h-16 text-orange-500" /> : <CreditCard className="w-16 h-16 text-blue-500" />}
                    </div>
                    <h4 className="text-xl font-bold text-slate-800 mb-2">
                       {paymentMethod === 'credit' ? 'Confirm Credit Sale' : 'Waiting for Terminal'}
                    </h4>
                    <p className="text-slate-500">Total amount: <strong>{formatPrice(total)}</strong></p>
                 </div>
              )}
           </div>
           <div className="p-4 border-t border-slate-100 bg-white">
              <button 
                 onClick={handleProcess}
                 disabled={isProcessing || (paymentMethod === 'cash' && receivedAmount < total) || (paymentMethod === 'credit' && receivedAmount > total)}
                 className={`w-full py-4 rounded-xl font-bold text-xl text-white shadow-lg flex items-center justify-center transition-all active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed ${paymentMethod === 'credit' ? 'bg-orange-600' : 'bg-slate-900 hover:bg-slate-800'}`}
              >
                 {isProcessing ? 'Processing...' : (
                    <>
                       <CheckCircle className="w-6 h-6 mr-2" /> 
                       {getConfirmButtonText()}
                    </>
                 )}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Sale, SystemSettings } from '../../types';

interface PrintableReceiptProps {
  sale: Sale;
  settings?: SystemSettings;
  isReprint?: boolean;
}

export const PrintableReceipt: React.FC<PrintableReceiptProps> = ({ sale, settings, isReprint }) => {
  const receiptWidthClass = settings?.receiptPaperSize === '58mm' ? 'print-w-58mm' : settings?.receiptPaperSize === 'A4' ? 'print-w-A4' : 'print-w-80mm';

  const formatPrice = (amount: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: settings?.currencySymbol === '₭' ? 'LAK' : settings?.currencySymbol === '฿' ? 'THB' : 'USD',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(amount);
  };

  return (
    <div id="printable-receipt" className={`bg-white p-4 text-xs font-mono text-black mx-auto ${receiptWidthClass} print:shadow-none print:border-none`}>
      <div className="text-center mb-4">
        {settings?.receiptLogoUrl && (
           <img src={settings.receiptLogoUrl} alt="Logo" className="h-12 w-auto mx-auto mb-2 object-contain" />
        )}
        <h2 className="text-lg font-bold mb-1">{settings?.companyName || 'Store Name'}</h2>
        <p>{settings?.address}</p>
        <p>{settings?.phone}</p>
        {settings?.receiptShowTaxId && settings.taxId && <p>Tax ID: {settings.taxId}</p>}

        <div className="border-b border-dashed border-black my-2"></div>

        <div className="flex justify-between">
           <span>Inv: #{sale.id.slice(-6)}</span>
           <span>{new Date(sale.date).toLocaleDateString()}</span>
        </div>
        <div className="flex justify-between">
           <span>Time: {new Date(sale.date).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
           {settings?.receiptShowCashier && <span>Staff: {sale.userName || 'Admin'}</span>}
        </div>
        {sale.customerName && <div className="text-left mt-1">Cust: {sale.customerName}</div>}
        {sale.status === 'voided' && <div className="font-bold text-center mt-1">[ VOIDED ]</div>}
      </div>

      <div className="border-b border-dashed border-black my-2"></div>

      <div className="space-y-1 mb-2">
        {sale.items.map((item, i) => (
          <div key={i} className="flex justify-between">
            <span className="truncate w-32">{item.name}</span>
            <span className="text-right">
              {item.quantity} x {formatPrice(item.sellPrice)}
            </span>
            <span className="font-bold text-right w-16">
              {formatPrice(item.quantity * item.sellPrice)}
            </span>
          </div>
        ))}
      </div>

      <div className="border-b border-dashed border-black my-2"></div>

      <div className="space-y-1">
        <div className="flex justify-between">
          <span>Subtotal</span>
          <span>{formatPrice(sale.subtotal || sale.total)}</span>
        </div>
        {sale.discountAmount ? (
          <div className="flex justify-between">
            <span>Discount</span>
            <span>-{formatPrice(sale.discountAmount)}</span>
          </div>
        ) : null}

        <div className="flex justify-between font-bold text-sm mt-1 pt-1 border-t border-black">
          <span>Total</span>
          <span>{formatPrice(sale.total)}</span>
        </div>
      </div>

      <div className="border-b border-dashed border-black my-3"></div>

      <div className="space-y-1">
        <div className="flex justify-between">
          <span className="capitalize">Paid via {sale.paymentMethod}</span>
          <span>{formatPrice(sale.amountReceived && sale.amountReceived > 0 ? sale.amountReceived : sale.total)}</span>
        </div>

        {(sale.paymentStatus === 'unpaid' || sale.paymentStatus === 'partial') && (
           <div className="flex justify-between font-bold">
              <span>Balance Due</span>
              <span>{formatPrice(sale.remainingAmount || 0)}</span>
           </div>
        )}

        {sale.change !== undefined && sale.change > 0 && (
          <div className="flex justify-between font-bold">
            <span>Change</span>
            <span>{formatPrice(sale.change)}</span>
          </div>
        )}
      </div>

      <div className="mt-6 text-center italic">
        <p className="mb-1">{settings?.receiptHeader}</p>
        <p>{settings?.receiptFooter}</p>
        {isReprint && <p className="text-[9px] mt-2 text-slate-500">*** REPRINT ***</p>}

        {/* QR Code at bottom if configured */}
        {settings?.receiptQrCodeUrl && (
          <div className="mt-3 flex flex-col items-center">
              <img src={settings.receiptQrCodeUrl} alt="QR" className="w-16 h-16 object-contain" />
              <span className="text-[9px] font-bold mt-1">Scan to Pay</span>
          </div>
        )}
      </div>
    </div>
  );
};

