import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { Sale, Customer, CustomerLevel, Shift, ShiftSchedule, Promotion, CashTransaction, Quotation } from '../types';
import { INITIAL_SALES, INITIAL_CUSTOMERS, INITIAL_CUSTOMER_LEVELS, INITIAL_PROMOTIONS, INITIAL_SHIFT_SCHEDULES } from '../services/data';

interface SalesState {
  sales: Sale[];
  quotations: Quotation[]; // Added
  customers: Customer[];
  customerLevels: CustomerLevel[];
  shifts: Shift[];
  shiftSchedules: ShiftSchedule[];
  promotions: Promotion[];

  addSale: (sale: Sale) => void;
  updateSale: (sale: Sale) => void; 

  addQuotation: (quotation: Quotation) => void; // Added
  updateQuotation: (quotation: Quotation) => void; // Added
  deleteQuotation: (id: string) => void; // Added

  addCustomer: (customer: Customer) => void;
  updateCustomer: (customer: Customer) => void;
  deleteCustomer: (id: string) => void;

  addCustomerLevel: (level: CustomerLevel) => void;
  updateCustomerLevel: (level: CustomerLevel) => void;
  deleteCustomerLevel: (id: string) => void;

  startShift: (shift: Shift) => void;
  endShift: (id: string, endData: Partial<Shift>) => void;
  // New action for cash drawer
  addCashTransaction: (transaction: CashTransaction) => void;

  addShiftSchedule: (schedule: ShiftSchedule) => void;
  updateShiftSchedule: (schedule: ShiftSchedule) => void;
  deleteShiftSchedule: (id: string) => void;

  addPromotion: (promo: Promotion) => void;
  updatePromotion: (promo: Promotion) => void;
  deletePromotion: (id: string) => void;

  restoreSalesData: (data: any) => void;
}

export const useSalesStore = create<SalesState>()(
  persist(
    (set) => ({
      sales: INITIAL_SALES,
      quotations: [],
      customers: INITIAL_CUSTOMERS,
      customerLevels: INITIAL_CUSTOMER_LEVELS,
      shifts: [],
      shiftSchedules: INITIAL_SHIFT_SCHEDULES,
      promotions: INITIAL_PROMOTIONS,

      addSale: (sale) => set((state) => ({ sales: [sale, ...state.sales] })),
      updateSale: (sale) => set((state) => ({ sales: state.sales.map(s => s.id === sale.id ? sale : s) })),

      addQuotation: (quotation) => set((state) => ({ quotations: [quotation, ...state.quotations] })),
      updateQuotation: (quotation) => set((state) => ({ quotations: state.quotations.map(q => q.id === quotation.id ? quotation : q) })),
      deleteQuotation: (id) => set((state) => ({ quotations: state.quotations.filter(q => q.id !== id) })),

      addCustomer: (customer) => set((state) => ({ customers: [...state.customers, customer] })),
      updateCustomer: (customer) => set((state) => ({ customers: state.customers.map(c => c.id === customer.id ? customer : c) })),
      deleteCustomer: (id) => set((state) => ({ customers: state.customers.filter(c => c.id !== id) })),

      addCustomerLevel: (level) => set((state) => ({ customerLevels: [...state.customerLevels, level] })),
      updateCustomerLevel: (level) => set((state) => ({ customerLevels: state.customerLevels.map(l => l.id === level.id ? level : l) })),
      deleteCustomerLevel: (id) => set((state) => ({ customerLevels: state.customerLevels.filter(l => l.id !== id) })),

      startShift: (shift) => set((state) => ({ shifts: [shift, ...state.shifts] })),
      endShift: (id, endData) => set((state) => ({ 
        shifts: state.shifts.map(s => s.id === id ? { ...s, ...endData } : s) 
      })),

      addCashTransaction: (txn) => set((state) => ({
        shifts: state.shifts.map(s => {
          if (s.id === txn.shiftId) {
            return {
              ...s,
              cashTransactions: [...(s.cashTransactions || []), txn]
            };
          }
          return s;
        })
      })),

      addShiftSchedule: (schedule) => set((state) => ({ shiftSchedules: [...state.shiftSchedules, schedule] })),
      updateShiftSchedule: (schedule) => set((state) => ({ shiftSchedules: state.shiftSchedules.map(s => s.id === schedule.id ? schedule : s) })),
      deleteShiftSchedule: (id) => set((state) => ({ shiftSchedules: state.shiftSchedules.filter(s => s.id !== id) })),

      addPromotion: (promo) => set((state) => ({ promotions: [...state.promotions, promo] })),
      updatePromotion: (promo) => set((state) => ({ promotions: state.promotions.map(p => p.id === promo.id ? promo : p) })),
      deletePromotion: (id) => set((state) => ({ promotions: state.promotions.filter(p => p.id !== id) })),

      restoreSalesData: (data) => set((state) => ({
        ...state,
        sales: data.sales || state.sales,
        quotations: data.quotations || state.quotations || [],
        customers: data.customers || state.customers,
        customerLevels: data.customerLevels || state.customerLevels,
        shifts: data.shifts || state.shifts,
        promotions: data.promotions || state.promotions
      }))
    }),
    {
      name: 'bm_sales_store',
    }
  )
);

import React from 'react';
import { Customer, SystemSettings, Quotation } from '../../types';
import { ShoppingCart, PauseCircle, X, Minus, Plus, Trash2, User, Percent, Banknote, FileText } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';
import { useCartStore } from '../../store/useCartStore';
import { useSalesStore } from '../../store/useSalesStore';

interface CartSidebarProps {
  isOpen: boolean;
  onClose: () => void;
  selectedCustomer: Customer | null;
  onRemoveCustomer: () => void;
  onHoldOrder: () => void;
  onCheckout: () => void;
  onDiscountClick: () => void;
  subtotal: number;
  discount: number;
  tax: number;
  total: number;
  settings?: SystemSettings;
}

export const CartSidebar: React.FC<CartSidebarProps> = ({
  isOpen,
  onClose,
  selectedCustomer,
  onRemoveCustomer,
  onHoldOrder,
  onCheckout,
  onDiscountClick,
  subtotal,
  discount,
  tax,
  total,
  settings
}) => {
  const { formatPrice, currentUser } = useGlobal();
  const { cart, removeFromCart, updateQuantity, setQuantity, clearCart } = useCartStore();
  const { addQuotation } = useSalesStore();

  const handleCreateQuotation = () => {
    if (cart.length === 0) return;

    // Default valid for 7 days
    const validDate = new Date();
    validDate.setDate(validDate.getDate() + 7);

    const userConfirm = confirm(`Create Quotation for ${formatPrice(total)}?\nValid until: ${validDate.toLocaleDateString()}`);

    if (userConfirm) {
       const newQuote: Quotation = {
          id: `Q-${Date.now()}`,
          referenceNo: `QT-${new Date().getFullYear()}${(new Date().getMonth()+1).toString().padStart(2,'0')}-${Math.floor(Math.random()*10000)}`,
          date: new Date().toISOString(),
          validUntil: validDate.toISOString(),
          items: [...cart],
          subtotal,
          discountAmount: discount,
          taxAmount: tax,
          total,
          customerId: selectedCustomer?.id,
          customerName: selectedCustomer?.name,
          customerPhone: selectedCustomer?.phone,
          customerAddress: selectedCustomer?.address,
          status: 'active',
          userId: currentUser?.id,
          userName: currentUser?.name
       };

       addQuotation(newQuote);
       clearCart();
       alert(`Quotation ${newQuote.referenceNo} created successfully!`);
    }
  };

  return (
    <div className={`fixed inset-y-0 right-0 z-40 w-full md:w-[400px] bg-white shadow-2xl transform transition-transform duration-300 lg:relative lg:translate-x-0 lg:shadow-none lg:border-l lg:border-slate-200 flex flex-col ${isOpen ? 'translate-x-0' : 'translate-x-full'}`}>
      <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-white shadow-sm z-10">
        <h3 className="font-bold text-slate-800 text-lg flex items-center"><ShoppingCart className="w-5 h-5 mr-2 text-orange-600" /> Current Order</h3>
        <div className="flex space-x-2">
           <button onClick={onHoldOrder} disabled={cart.length === 0} className="p-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200 transition-colors" title="Hold Order">
              <PauseCircle className="w-5 h-5" />
           </button>
           <button onClick={handleCreateQuotation} disabled={cart.length === 0} className="p-2 bg-blue-50 text-blue-600 border border-blue-200 rounded-lg hover:bg-blue-100 transition-colors" title="Create Quotation">
              <FileText className="w-5 h-5" />
           </button>
           <button onClick={onClose} className="lg:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-full">
             <X className="w-6 h-6" />
           </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50/50">
        {cart.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-slate-400 space-y-4">
            <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center"><ShoppingCart className="w-8 h-8 text-slate-300" /></div>
            <p>Cart is empty</p>
          </div>
        ) : (
          cart.map((item, index) => (
            <div key={`${item.id}-${index}`} className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm flex flex-col gap-2">
              <div className="flex justify-between items-start">
                <div>
                  <h4 className="font-bold text-slate-800 text-sm line-clamp-1">{item.name}</h4>
                  <span className="text-xs text-slate-500 bg-slate-100 px-1.5 py-0.5 rounded">{item.sellUnit} • {formatPrice(item.sellPrice)}</span>
                </div>
                <span className="font-bold text-slate-900">{formatPrice(item.sellPrice * item.quantity)}</span>
              </div>
              <div className="flex items-center justify-between mt-1">
                 <div className="flex items-center bg-slate-100 rounded-lg p-1">
                    <button onClick={() => updateQuantity(index, -1)} className="w-8 h-8 flex items-center justify-center bg-white rounded shadow-sm text-slate-600 hover:text-red-500"><Minus className="w-4 h-4" /></button>
                    <input type="number" value={item.quantity} onChange={(e) => setQuantity(index, parseInt(e.target.value)||1)} className="w-10 text-center bg-transparent font-bold text-sm" />
                    <button onClick={() => updateQuantity(index, 1)} className="w-8 h-8 flex items-center justify-center bg-white rounded shadow-sm text-slate-600 hover:text-green-500"><Plus className="w-4 h-4" /></button>
                 </div>
                 <button onClick={() => removeFromCart(index)} className="p-2 text-red-400 hover:text-red-600"><Trash2 className="w-4 h-4" /></button>
              </div>
            </div>
          ))
        )}
      </div>

      <div className="p-5 bg-white border-t border-slate-200 shadow-[0_-10px_30px_rgba(0,0,0,0.05)] z-20">
        {selectedCustomer && (
           <div className="flex justify-between items-center p-3 bg-blue-50 border border-blue-100 rounded-lg text-sm text-blue-900 mb-3">
              <span className="font-bold flex items-center"><User className="w-4 h-4 mr-2" /> {selectedCustomer.name}</span>
              <button onClick={onRemoveCustomer}><X className="w-4 h-4 text-blue-400" /></button>
           </div>
        )}
        <div className="space-y-2 text-sm text-slate-600 mb-4">
          <div className="flex justify-between"><span>Subtotal</span><span>{formatPrice(subtotal)}</span></div>
          <div className="flex justify-between text-green-600 cursor-pointer" onClick={onDiscountClick}>
             <span className="flex items-center underline"><Percent className="w-3 h-3 mr-1" /> Discount</span>
             <span>-{formatPrice(discount)}</span>
          </div>
          {settings?.tax?.enabled && <div className="flex justify-between text-slate-500"><span>Tax ({settings.tax.rate}%)</span><span>{formatPrice(tax)}</span></div>}
        </div>
        <div className="flex justify-between items-end mb-4 pt-4 border-t border-slate-100">
          <span className="text-lg font-bold text-slate-800">Total</span>
          <span className="text-3xl font-bold text-slate-900 tracking-tight">{formatPrice(total)}</span>
        </div>
        <button 
          onClick={onCheckout} 
          disabled={cart.length === 0}
          className="w-full py-4 bg-slate-900 text-white rounded-xl font-bold text-lg hover:bg-slate-800 shadow-lg disabled:opacity-50 flex items-center justify-center transition-all active:scale-[0.98]"
        >
          <Banknote className="w-5 h-5 mr-2" /> Charge
        </button>
      </div>
    </div>
  );
};

