import React from 'react';
import { Quotation, SystemSettings } from '../../types';
import { X, Printer, ShoppingCart, Trash2 } from 'lucide-react';
import { PrintableQuotation } from '../shared/PrintableQuotation';
import { useCartStore } from '../../store/useCartStore';
import { useSalesStore } from '../../store/useSalesStore';

interface QuotationDetailModalProps {
  quotation: Quotation | null;
  isOpen: boolean;
  onClose: () => void;
  settings?: SystemSettings;
}

export const QuotationDetailModal: React.FC<QuotationDetailModalProps> = ({ quotation, isOpen, onClose, settings }) => {
  const { addToCart, clearCart } = useCartStore();
  const { updateQuotation, deleteQuotation } = useSalesStore();

  if (!isOpen || !quotation) return null;

  const handlePrint = () => {
    window.print();
  };

  const handleConvertToSale = () => {
    if (confirm("This will clear your current cart and load items from this quotation. Continue?")) {
       clearCart();
       quotation.items.forEach(item => {
          addToCart(item, item.quantity, item.selectedVariantId);
       });

       // Update quote status
       updateQuotation({ ...quotation, status: 'converted' });
       onClose();
       // Redirect logic would be handled by parent or user manually navigating to POS
       alert("Items loaded to POS Cart. Please proceed to payment.");
    }
  };

  const handleDelete = () => {
     if(confirm("Delete this quotation permanently?")) {
        deleteQuotation(quotation.id);
        onClose();
     }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[70] p-4 print:p-0 print:bg-white print:static print:block">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col print:shadow-none print:max-w-none print:max-h-none print:rounded-none">

        {/* Header */}
        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl print:hidden">
           <div>
              <h3 className="text-xl font-bold text-slate-800">Quotation Details</h3>
              <p className="text-xs text-slate-500">{quotation.referenceNo}</p>
           </div>
           <button onClick={onClose} className="text-slate-400 hover:text-slate-600"><X className="w-6 h-6" /></button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 bg-slate-50 print:p-0 print:bg-white">
           <PrintableQuotation quotation={quotation} settings={settings} />
        </div>

        {/* Footer Actions */}
        <div className="p-4 border-t border-slate-100 flex justify-between bg-slate-50 rounded-b-xl print:hidden">
           <button 
              onClick={handleDelete}
              className="px-4 py-2 border border-red-200 text-red-600 rounded-lg hover:bg-red-50 font-medium flex items-center"
           >
              <Trash2 className="w-4 h-4 mr-2" /> Delete
           </button>
           <div className="flex space-x-3">
              <button 
                 onClick={handlePrint}
                 className="px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 font-medium flex items-center shadow-sm"
              >
                 <Printer className="w-4 h-4 mr-2" /> Print
              </button>
              {quotation.status === 'active' && (
                 <button 
                    onClick={handleConvertToSale}
                    className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-bold shadow-md flex items-center"
                 >
                    <ShoppingCart className="w-4 h-4 mr-2" /> Convert to Sale
                 </button>
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Sale, Quotation } from '../types';
import { Search, Receipt, FileText } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { SalesList } from './sales/SalesList';
import { SaleDetailModal } from './sales/SaleDetailModal';
import { useSalesStore } from '../store/useSalesStore'; // Import Store directly for quotes
import { QuotationList } from './sales/QuotationList';
import { QuotationDetailModal } from './sales/QuotationDetailModal';

interface SalesHistoryProps {
  sales: Sale[];
  onVoidSale: (id: string) => void;
}

export const SalesHistory: React.FC<SalesHistoryProps> = ({ sales = [], onVoidSale }) => {
  const { currentUser, settleSaleDebt, processReturn, settings, formatPrice } = useGlobal();
  const { quotations } = useSalesStore(); // Access quotes from store

  const [activeTab, setActiveTab] = useState<'sales' | 'quotations'>('sales');
  const [searchTerm, setSearchTerm] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'completed' | 'voided' | 'unpaid' | 'active' | 'converted' | 'expired'>('all');

  // Modal States
  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [selectedQuote, setSelectedQuote] = useState<Quotation | null>(null);

  const safeSales = sales || [];

  const filteredSales = useMemo(() => {
    return safeSales.filter(sale => {
      const matchesSearch = 
        sale.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (sale.customerName && sale.customerName.toLowerCase().includes(searchTerm.toLowerCase()));

      let matchesStatus = true;
      if (statusFilter === 'completed') matchesStatus = sale.status === 'completed' && sale.paymentStatus === 'paid';
      else if (statusFilter === 'unpaid') matchesStatus = sale.paymentStatus === 'unpaid' || sale.paymentStatus === 'partial';
      else if (statusFilter === 'voided') matchesStatus = sale.status === 'voided';

      let matchesDate = true;
      if (startDate) {
        matchesDate = matchesDate && new Date(sale.date) >= new Date(startDate);
      }
      if (endDate) {
        const end = new Date(endDate);
        end.setHours(23, 59, 59, 999);
        matchesDate = matchesDate && new Date(sale.date) <= end;
      }

      return matchesSearch && matchesStatus && matchesDate;
    });
  }, [safeSales, searchTerm, startDate, endDate, statusFilter]);

  const filteredQuotations = useMemo(() => {
     return quotations.filter(quote => {
        const matchesSearch = 
           quote.referenceNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
           (quote.customerName && quote.customerName.toLowerCase().includes(searchTerm.toLowerCase()));

        let matchesStatus = true;
        if (statusFilter !== 'all' && ['completed','voided','unpaid'].includes(statusFilter)) {
           // If Sales specific filter is active but we are in quotes, reset logic or show nothing?
           // Better to check valid Quote statuses
        } else if (statusFilter !== 'all') {
           matchesStatus = quote.status === statusFilter;
        }

        return matchesSearch && matchesStatus;
     });
  }, [quotations, searchTerm, statusFilter]);

  const handleVoid = () => {
    if (!selectedSale) return;
    if (confirm(`Are you sure you want to VOID Sale #${selectedSale.id}? This will restore items to stock automatically.`)) {
      onVoidSale(selectedSale.id);
      setSelectedSale(null);
    }
  };

  const handleSettleDebt = async () => {
    if (!selectedSale) return;
    const debt = selectedSale.remainingAmount || selectedSale.total;
    if (confirm(`Confirm full payment of ${formatPrice(debt)} for this invoice?`)) {
       await settleSaleDebt(selectedSale.id, debt, 'cash');
       setSelectedSale(prev => prev ? ({...prev, paymentStatus: 'paid', remainingAmount: 0, amountReceived: (prev.amountReceived || 0) + debt}) : null); 
    }
  };

  const isAdminOrManager = currentUser?.role === 'Admin' || currentUser?.role === 'Manager';

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center print:hidden">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Sales & Quotations</h2>
          <p className="text-slate-500">Manage invoices, credit sales, quotations and void transactions.</p>
        </div>

        <div className="flex bg-slate-100 p-1 rounded-lg">
           <button 
              onClick={() => { setActiveTab('sales'); setStatusFilter('all'); }}
              className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'sales' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
           >
              <Receipt className="w-4 h-4 mr-2" /> Invoices
           </button>
           <button 
              onClick={() => { setActiveTab('quotations'); setStatusFilter('all'); }}
              className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'quotations' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
           >
              <FileText className="w-4 h-4 mr-2" /> Quotations
           </button>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4 items-end print:hidden">
        <div className="flex-1 w-full">
           <label className="block text-xs font-medium text-slate-500 mb-1">Search</label>
           <div className="relative">
              <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
              <input
                type="text"
                placeholder={activeTab === 'sales' ? "Invoice ID or Customer Name" : "Ref No or Customer Name"}
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
              />
           </div>
        </div>

        {activeTab === 'sales' && (
           <>
              <div>
                 <label className="block text-xs font-medium text-slate-500 mb-1">Start Date</label>
                 <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500" />
              </div>
              <div>
                 <label className="block text-xs font-medium text-slate-500 mb-1">End Date</label>
                 <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500" />
              </div>
           </>
        )}

        <div>
           <label className="block text-xs font-medium text-slate-500 mb-1">Status</label>
           <select
             value={statusFilter}
             onChange={e => setStatusFilter(e.target.value as any)}
             className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-white min-w-[120px]"
           >
             <option value="all">All Status</option>
             {activeTab === 'sales' ? (
                <>
                   <option value="completed">Paid / Completed</option>
                   <option value="unpaid">Unpaid / Credit</option>
                   <option value="voided">Voided</option>
                </>
             ) : (
                <>
                   <option value="active">Active</option>
                   <option value="converted">Converted</option>
                   <option value="expired">Expired</option>
                </>
             )}
           </select>
        </div>
      </div>

      {activeTab === 'sales' ? (
         <SalesList 
            sales={filteredSales} 
            formatPrice={formatPrice} 
            onViewSale={setSelectedSale} 
         />
      ) : (
         <QuotationList 
            quotations={filteredQuotations}
            formatPrice={formatPrice}
            onViewQuotation={setSelectedQuote}
         />
      )}

      <SaleDetailModal 
        sale={selectedSale}
        isOpen={!!selectedSale}
        onClose={() => setSelectedSale(null)}
        onVoid={handleVoid}
        onSettleDebt={handleSettleDebt}
        onReturn={processReturn.bind(null, selectedSale!)} 
        settings={settings}
        formatPrice={formatPrice}
        isAdminOrManager={isAdminOrManager}
      />

      <QuotationDetailModal 
         quotation={selectedQuote}
         isOpen={!!selectedQuote}
         onClose={() => setSelectedQuote(null)}
         settings={settings}
      />
    </div>
  );
};

