import React, { useState } from 'react';
import { Customer } from '../../types';
import { X, Banknote, QrCode, CreditCard, FileText, ChevronLeft, CheckCircle } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';
import { PaymentMethodList } from './checkout/PaymentMethodList';
import { PaymentNumpad } from './checkout/PaymentNumpad';

interface CheckoutModalProps {
  isOpen: boolean;
  onClose: () => void;
  total: number;
  onProcessPayment: (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit', receivedAmount: number, change: number) => Promise<void>;
  selectedCustomer: Customer | null;
  isProcessing: boolean;
  onCreateQuotation: () => void;
}

export const CheckoutModal: React.FC<CheckoutModalProps> = ({
  isOpen,
  onClose,
  total,
  onProcessPayment,
  selectedCustomer,
  isProcessing,
  onCreateQuotation
}) => {
  const { formatPrice } = useGlobal();
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'qr' | 'credit'>('cash');
  const [receivedAmountStr, setReceivedAmountStr] = useState('');
  const [checkoutStep, setCheckoutStep] = useState<'method' | 'detail'>('method');

  if (!isOpen) return null;

  const receivedAmount = parseFloat(receivedAmountStr) || 0;
  const change = Math.max(0, receivedAmount - total);

  const selectPaymentMethod = (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit') => {
    if (method === 'credit' && !selectedCustomer) {
      alert("Credit payment requires a registered customer.");
      return;
    }
    setPaymentMethod(method);
    setReceivedAmountStr('');
    setCheckoutStep('detail');
  };

  const handleQuickCash = (amount: number) => {
    setReceivedAmountStr(amount.toString());
  };

  const handleProcess = () => {
    let finalReceived = paymentMethod === 'cash' || paymentMethod === 'credit' ? receivedAmount : total;
    let finalChange = paymentMethod === 'cash' ? change : 0;

    // Auto-fill exact amount for non-cash methods if not set
    if (paymentMethod !== 'cash' && paymentMethod !== 'credit') {
        finalReceived = total;
    }

    onProcessPayment(paymentMethod, finalReceived, finalChange);
  };

  const getConfirmButtonText = () => {
    if (isProcessing) return 'Processing...';

    if (paymentMethod === 'cash') {
      if (receivedAmount < total) return `Enter Amount (Due: ${formatPrice(total)})`;
      if (change > 0) return `Confirm Pay & Return ${formatPrice(change)}`;
      return `Confirm Payment ${formatPrice(total)}`;
    }

    if (paymentMethod === 'credit') {
       return `Confirm Credit Sale ${formatPrice(total)}`;
    }

    return `Confirm Payment ${formatPrice(total)}`;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/60 backdrop-blur-sm p-0 sm:p-4 animate-fade-in">
      <div className="bg-white w-full h-[90vh] sm:h-[650px] sm:max-w-5xl rounded-t-2xl sm:rounded-2xl shadow-2xl flex flex-col sm:flex-row overflow-hidden">

        {/* Method Selection Sidebar */}
        <PaymentMethodList 
            paymentMethod={paymentMethod}
            onSelect={selectPaymentMethod}
            onClose={onClose}
            total={total}
            selectedCustomer={selectedCustomer}
            onCreateQuotation={onCreateQuotation}
            className={checkoutStep === 'detail' ? 'hidden sm:flex' : 'flex'}
        />

        {/* Detail / Numpad Area */}
        <div className={`flex-1 bg-white flex flex-col ${checkoutStep === 'method' ? 'hidden sm:flex' : 'flex'} h-full`}>
           <div className="p-4 border-b border-slate-100 flex items-center justify-between sm:justify-end">
              <button onClick={() => setCheckoutStep('method')} className="sm:hidden flex items-center text-slate-500 font-medium hover:text-slate-800">
                 <ChevronLeft className="w-5 h-5 mr-1" /> Back
              </button>
              <button onClick={onClose} className="hidden sm:block p-2 hover:bg-slate-100 rounded-full text-slate-400">
                 <X className="w-6 h-6" />
              </button>
           </div>

           <div className="flex-1 p-4 sm:p-8 overflow-y-auto">
              <div className="text-center mb-6">
                 <h3 className="text-xl font-bold text-slate-800 flex items-center justify-center gap-2">
                    {paymentMethod === 'cash' ? <Banknote className="text-blue-600"/> : paymentMethod === 'qr' ? <QrCode className="text-blue-600"/> : <CreditCard className="text-blue-600"/>}
                    {paymentMethod === 'cash' ? 'Cash Payment' : paymentMethod === 'qr' ? 'Scan to Pay' : 'Digital Payment'}
                 </h3>
              </div>

              {paymentMethod === 'cash' ? (
                 <PaymentNumpad 
                    receivedAmountStr={receivedAmountStr}
                    setReceivedAmountStr={setReceivedAmountStr}
                    total={total}
                    change={change}
                    handleQuickCash={handleQuickCash}
                 />
              ) : paymentMethod === 'qr' ? (
                 <div className="flex-1 flex flex-col items-center justify-center">
                    <div className="bg-white p-6 rounded-3xl border-2 border-slate-100 shadow-lg mb-6">
                       <img src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=Payment_OnePay_${total}`} className="w-64 h-64 object-contain" alt="QR" />
                    </div>
                    <p className="text-lg font-bold text-slate-700">Scan to pay {formatPrice(total)}</p>
                 </div>
              ) : (
                 <div className="flex-1 flex flex-col items-center justify-center text-center">
                    <div className="w-32 h-32 bg-slate-100 rounded-full flex items-center justify-center mb-6 animate-pulse">
                       {paymentMethod === 'credit' ? <FileText className="w-16 h-16 text-orange-500" /> : <CreditCard className="w-16 h-16 text-blue-500" />}
                    </div>
                    <h4 className="text-xl font-bold text-slate-800 mb-2">
                       {paymentMethod === 'credit' ? 'Confirm Credit Sale' : 'Waiting for Terminal'}
                    </h4>
                    <p className="text-slate-500">Total amount: <strong>{formatPrice(total)}</strong></p>
                 </div>
              )}
           </div>
           <div className="p-4 border-t border-slate-100 bg-white">
              <button 
                 onClick={handleProcess}
                 disabled={isProcessing || (paymentMethod === 'cash' && receivedAmount < total) || (paymentMethod === 'credit' && receivedAmount > total)}
                 className={`w-full py-4 rounded-xl font-bold text-xl text-white shadow-lg flex items-center justify-center transition-all active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed ${paymentMethod === 'credit' ? 'bg-orange-600' : 'bg-slate-900 hover:bg-slate-800'}`}
              >
                 {isProcessing ? 'Processing...' : (
                    <>
                       <CheckCircle className="w-6 h-6 mr-2" /> 
                       {getConfirmButtonText()}
                    </>
                 )}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Banknote, QrCode, CreditCard, FileText, X } from 'lucide-react';
import { Customer } from '../../../types';
import { useGlobal } from '../../../context/GlobalContext';

interface PaymentMethodListProps {
  paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit';
  onSelect: (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit') => void;
  onClose: () => void;
  total: number;
  selectedCustomer: Customer | null;
  onCreateQuotation: () => void;
  className?: string;
}

export const PaymentMethodList: React.FC<PaymentMethodListProps> = ({ 
  paymentMethod, onSelect, onClose, total, selectedCustomer, onCreateQuotation, className 
}) => {
  const { formatPrice } = useGlobal();

  return (
    <div className={`w-full sm:w-1/3 bg-slate-50 border-r border-slate-200 flex-col ${className}`}>
        <div className="p-5 border-b border-slate-200 bg-white sm:bg-transparent flex justify-between items-center">
            <h3 className="font-bold text-lg text-slate-800">Payment Method</h3>
            <button onClick={onClose} className="sm:hidden p-2 bg-slate-100 rounded-full text-slate-500"><X className="w-5 h-5"/></button>
        </div>
        <div className="p-4 space-y-3 flex-1 overflow-y-auto">
            {[
                { id: 'cash', icon: Banknote, label: 'Cash', color: 'blue' },
                { id: 'qr', icon: QrCode, label: 'OnePay / QR', color: 'blue' },
                { id: 'card', icon: CreditCard, label: 'Card / Transfer', color: 'blue' },
                { id: 'credit', icon: FileText, label: 'Credit / ติดหนี้', color: 'orange', sub: 'Members Only', disabled: !selectedCustomer }
            ].map((m) => (
                <button 
                key={m.id}
                onClick={() => !m.disabled && onSelect(m.id as any)} 
                className={`w-full p-4 rounded-xl border-2 flex items-center transition-all ${
                    m.disabled ? 'opacity-50 cursor-not-allowed border-slate-200 bg-white' :
                    paymentMethod === m.id 
                    ? `border-${m.color}-500 bg-white shadow-md` 
                    : `border-slate-200 bg-white hover:border-${m.color}-300`
                }`}
                >
                <div className={`p-3 rounded-full mr-4 ${paymentMethod === m.id ? `bg-${m.color}-100 text-${m.color}-600` : 'bg-slate-100 text-slate-500'}`}>
                    <m.icon className="w-6 h-6" />
                </div>
                <div className="text-left">
                    <span className="font-bold text-lg text-slate-700 block">{m.label}</span>
                    {m.sub && <span className="text-xs text-slate-400 font-medium">{m.sub}</span>}
                </div>
                </button>
            ))}

            <div className="border-t border-slate-200 my-4 pt-4">
               <button 
                  onClick={onCreateQuotation}
                  className="w-full p-4 rounded-xl border-2 border-slate-200 bg-white hover:border-slate-300 hover:bg-slate-50 flex items-center transition-all group"
               >
                  <div className="p-3 rounded-full mr-4 bg-slate-100 text-slate-500 group-hover:bg-slate-200">
                     <FileText className="w-6 h-6" />
                  </div>
                  <div className="text-left">
                     <span className="font-bold text-lg text-slate-700 block">Save as Quotation</span>
                     <span className="text-xs text-slate-500 font-medium">No payment required</span>
                  </div>
               </button>
            </div>
        </div>
        <div className="p-5 border-t border-slate-200 bg-white sm:bg-transparent">
            <div className="flex justify-between items-center">
                <span className="text-sm font-medium text-slate-500">Total Due</span>
                <span className="text-2xl font-bold text-slate-900">{formatPrice(total)}</span>
            </div>
        </div>
    </div>
  );
};

import React from 'react';
import { Quotation, SystemSettings } from '../../types';
import { X, Printer, ShoppingCart, Trash2 } from 'lucide-react';
import { PrintableQuotation } from '../shared/PrintableQuotation';
import { useCartStore } from '../../store/useCartStore';
import { useSalesStore } from '../../store/useSalesStore';

interface QuotationDetailModalProps {
  quotation: Quotation | null;
  isOpen: boolean;
  onClose: () => void;
  settings?: SystemSettings;
}

export const QuotationDetailModal: React.FC<QuotationDetailModalProps> = ({ quotation, isOpen, onClose, settings }) => {
  const { addToCart, clearCart } = useCartStore();
  const { updateQuotation, deleteQuotation } = useSalesStore();

  if (!isOpen || !quotation) return null;

  const handlePrint = () => {
    window.print();
  };

  const handleConvertToSale = () => {
    if (confirm("This will clear your current cart and load items from this quotation. Continue?")) {
       clearCart();
       quotation.items.forEach(item => {
          addToCart(item, item.quantity, item.selectedVariantId);
       });

       // Update quote status
       updateQuotation({ ...quotation, status: 'converted' });
       onClose();
       // Redirect logic would be handled by parent or user manually navigating to POS
       alert("Items loaded to POS Cart. Please proceed to payment.");
    }
  };

  const handleDelete = () => {
     if(confirm("Delete this quotation permanently?")) {
        deleteQuotation(quotation.id);
        onClose();
     }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-70 flex items-end md:items-center justify-center z-[70] p-0 md:p-4 print:p-0 print:bg-white print:static print:block backdrop-blur-sm">
      <div className="bg-white w-full h-full md:h-auto md:max-h-[95vh] md:max-w-4xl md:rounded-xl shadow-2xl flex flex-col print:shadow-none print:max-w-none print:max-h-none print:rounded-none">

        {/* Header */}
        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 md:rounded-t-xl print:hidden shrink-0">
           <div>
              <h3 className="text-lg md:text-xl font-bold text-slate-800">Quotation Details</h3>
              <p className="text-xs text-slate-500">{quotation.referenceNo}</p>
           </div>
           <button onClick={onClose} className="p-2 bg-slate-100 rounded-full text-slate-500 hover:text-slate-800 hover:bg-slate-200 transition-colors">
             <X className="w-5 h-5" />
           </button>
        </div>

        {/* Content - Scrollable */}
        <div className="flex-1 overflow-y-auto bg-slate-100/50 p-0 md:p-6 print:p-0 print:bg-white print:overflow-visible">
           {/* Wrapper to center A4 on desktop, full width on mobile */}
           <div className="shadow-none md:shadow-lg print:shadow-none mx-auto md:max-w-[210mm] bg-white">
              <PrintableQuotation quotation={quotation} settings={settings} />
           </div>
        </div>

        {/* Footer Actions */}
        <div className="p-4 border-t border-slate-100 flex flex-col sm:flex-row justify-between gap-3 bg-white md:rounded-b-xl print:hidden shrink-0">
           <button 
              onClick={handleDelete}
              className="order-2 sm:order-1 px-4 py-3 sm:py-2 border border-red-200 text-red-600 rounded-lg hover:bg-red-50 font-medium flex items-center justify-center text-sm w-full sm:w-auto"
           >
              <Trash2 className="w-4 h-4 mr-2" /> Delete
           </button>
           <div className="order-1 sm:order-2 flex flex-col sm:flex-row gap-3 w-full sm:w-auto">
              <button 
                 onClick={handlePrint}
                 className="px-5 py-3 sm:py-2.5 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 font-bold flex items-center justify-center shadow-sm w-full sm:w-auto"
              >
                 <Printer className="w-4 h-4 mr-2" /> Print / PDF
              </button>
              {quotation.status === 'active' && (
                 <button 
                    onClick={handleConvertToSale}
                    className="px-6 py-3 sm:py-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-bold shadow-md flex items-center justify-center w-full sm:w-auto"
                 >
                    <ShoppingCart className="w-4 h-4 mr-2" /> To Cart
                 </button>
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

