import React from 'react';
import { Quotation, SystemSettings } from '../../types';
import { X, Printer, ShoppingCart, Trash2 } from 'lucide-react';
import { PrintableQuotation } from '../shared/PrintableQuotation';
import { useCartStore } from '../../store/useCartStore';
import { useSalesStore } from '../../store/useSalesStore';

interface QuotationDetailModalProps {
  quotation: Quotation | null;
  isOpen: boolean;
  onClose: () => void;
  settings?: SystemSettings;
}

export const QuotationDetailModal: React.FC<QuotationDetailModalProps> = ({ quotation, isOpen, onClose, settings }) => {
  const addToCart = useCartStore((state) => state.addToCart);
  const clearCart = useCartStore((state) => state.clearCart);
  const updateQuotation = useSalesStore((state) => state.updateQuotation);
  const deleteQuotation = useSalesStore((state) => state.deleteQuotation);

  if (!isOpen || !quotation) return null;

  const handlePrint = () => {
    window.print();
  };

  const handleConvertToSale = () => {
    if (window.confirm("This will clear your current cart and load items from this quotation. Continue?")) {
       clearCart();

       if (quotation.items && quotation.items.length > 0) {
         quotation.items.forEach(item => {
            addToCart(item, item.quantity, item.selectedVariantId);
         });

         updateQuotation({ ...quotation, status: 'converted' });

         onClose();

         // Short delay to ensure modal is gone before alert
         setTimeout(() => {
            alert("Items loaded to POS Cart. Please proceed to payment.");
         }, 100);
       }
    }
  };

  const handleDelete = () => {
     if (window.confirm("Delete this quotation permanently?")) {
        deleteQuotation(quotation.id);
        onClose();
     }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center">
      {/* Backdrop with click handler to close */}
      <div 
        className="absolute inset-0 bg-black/70 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      {/* Modal Container */}
      <div 
        className="relative bg-white w-full h-[95dvh] md:h-auto md:max-h-[90vh] md:max-w-4xl md:rounded-xl shadow-2xl flex flex-col overflow-hidden z-10 animate-fade-in print:shadow-none print:max-w-none print:max-h-none print:rounded-none print:h-auto print:w-full print:fixed print:inset-0"
      >

        {/* Header */}
        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 print:hidden shrink-0">
           <div>
              <h3 className="text-lg md:text-xl font-bold text-slate-800">Quotation Details</h3>
              <p className="text-xs text-slate-500">{quotation.referenceNo}</p>
           </div>
           <button 
             type="button" 
             onClick={onClose} 
             className="p-2 bg-slate-200 rounded-full text-slate-600 hover:bg-slate-300 transition-colors"
           >
             <X className="w-5 h-5" />
           </button>
        </div>

        {/* Content - Scrollable */}
        <div className="flex-1 overflow-y-auto bg-slate-100/50 p-0 md:p-6 print:p-0 print:bg-white print:overflow-visible">
           <div className="shadow-none md:shadow-lg print:shadow-none mx-auto md:max-w-[210mm] bg-white min-h-full">
              <PrintableQuotation quotation={quotation} settings={settings} />
           </div>
        </div>

        {/* Footer Actions */}
        <div className="p-4 border-t border-slate-200 flex flex-col sm:flex-row justify-between gap-3 bg-white print:hidden shrink-0 z-20 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)]">
           <button 
              type="button"
              onClick={handleDelete}
              className="order-2 sm:order-1 px-4 py-3 sm:py-2.5 border-2 border-red-100 text-red-600 rounded-lg hover:bg-red-50 hover:border-red-200 font-bold flex items-center justify-center text-sm w-full sm:w-auto transition-colors"
           >
              <Trash2 className="w-4 h-4 mr-2" /> Delete
           </button>
           <div className="order-1 sm:order-2 flex flex-col sm:flex-row gap-3 w-full sm:w-auto">
              <button 
                 type="button"
                 onClick={handlePrint}
                 className="px-5 py-3 sm:py-2.5 bg-white border-2 border-slate-200 text-slate-700 rounded-lg hover:bg-slate-50 hover:border-slate-300 font-bold flex items-center justify-center shadow-sm w-full sm:w-auto transition-colors"
              >
                 <Printer className="w-4 h-4 mr-2" /> Print / PDF
              </button>
              {quotation.status === 'active' && (
                 <button 
                    type="button"
                    onClick={handleConvertToSale}
                    className="px-6 py-3 sm:py-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-bold shadow-md flex items-center justify-center w-full sm:w-auto transition-colors"
                 >
                    <ShoppingCart className="w-4 h-4 mr-2" /> To Cart
                 </button>
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

