import React, { useEffect } from 'react';
import { Quotation, SystemSettings } from '../../types';
import { X, Printer, ShoppingCart, Trash2, FileText, CheckCircle, Clock, Copy } from 'lucide-react';
import { PrintableQuotation } from '../shared/PrintableQuotation';
import { useCartStore } from '../../store/useCartStore';
import { useSalesStore } from '../../store/useSalesStore';

interface QuotationDetailModalProps {
  quotation: Quotation | null;
  isOpen: boolean;
  onClose: () => void;
  settings?: SystemSettings;
}

export const QuotationDetailModal: React.FC<QuotationDetailModalProps> = ({ quotation, isOpen, onClose, settings }) => {
  const addToCart = useCartStore((state) => state.addToCart);
  const clearCart = useCartStore((state) => state.clearCart);
  const updateQuotation = useSalesStore((state) => state.updateQuotation);
  const deleteQuotation = useSalesStore((state) => state.deleteQuotation);

  // Close on Escape key
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [onClose]);

  if (!isOpen || !quotation) return null;

  const handlePrint = (e: React.MouseEvent) => {
    e.stopPropagation();
    window.print();
  };

  const handleConvertToSale = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Load items into cart? Current cart will be cleared.")) {
       clearCart();

       if (quotation.items && quotation.items.length > 0) {
         quotation.items.forEach(item => {
            addToCart(item, item.quantity, item.selectedVariantId);
         });

         updateQuotation({ ...quotation, status: 'converted' });
         onClose();
         setTimeout(() => alert("Items loaded to Cart."), 300);
       }
    }
  };

  const handleDelete = (e: React.MouseEvent) => {
     e.stopPropagation();
     if (window.confirm("Permanently delete this quotation?")) {
        deleteQuotation(quotation.id);
        onClose();
     }
  };

  const statusColors = {
    active: 'bg-blue-100 text-blue-700',
    converted: 'bg-green-100 text-green-700',
    expired: 'bg-red-100 text-red-700'
  };

  return (
    <div className="fixed inset-0 z-[100] flex justify-end items-start" role="dialog" aria-modal="true">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      {/* Slide-over Panel */}
      <div className="relative w-full md:max-w-3xl h-full bg-white shadow-2xl flex flex-col animate-fade-in print:w-full print:max-w-none">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200 bg-white z-20 print:hidden">
           <div>
              <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                 <FileText className="w-5 h-5 text-slate-500" />
                 Quotation Details
              </h2>
              <div className="flex items-center gap-3 mt-1 text-sm">
                 <span className="font-mono text-slate-500">{quotation.referenceNo}</span>
                 <span className={`px-2 py-0.5 rounded-full text-xs font-bold uppercase ${statusColors[quotation.status] || 'bg-gray-100'}`}>
                    {quotation.status}
                 </span>
              </div>
           </div>
           <button 
             onClick={onClose}
             className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-colors"
           >
             <X className="w-6 h-6" />
           </button>
        </div>

