import { ReceiptModal } from './pos/ReceiptModal';
import { CustomerModal } from './pos/CustomerModal';
import { DiscountModal } from './pos/DiscountModal';
import { RecallModal } from './pos/RecallModal';

interface PosTerminalProps {
  products: Product[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number
  ) => Promise<Sale>;
  settings?: SystemSettings;
}

export const PosTerminal: React.FC<PosTerminalProps> = ({ products, onProcessSale, settings }) => {
  const { customers, customerLevels, t, branches, warehouses, currentUser } = useGlobal();
  const { 
    cart, addToCart, clearCart,
    heldOrders, holdCurrentOrder, recallOrder, discardHeldOrder
  } = useCartStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false); 

  // Modal States
  const [isDiscountModalOpen, setIsDiscountModalOpen] = useState(false);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [isRecallModalOpen, setIsRecallModalOpen] = useState(false);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);

  // Transaction State
  const [manualDiscount, setManualDiscount] = useState<{ type: 'percent' | 'fixed', value: number } | null>(null);
  const [redeemPoints, setRedeemPoints] = useState<number>(0);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // --- Branch Logic (Inventory Filtering) ---
  const activeBranchId = settings?.currentBranchId || currentUser?.branchId || (branches.length > 0 ? branches[0].id : '');

  const branchProducts = useMemo(() => {
    if (!activeBranchId) return products;

    // Get warehouse IDs belonging to this branch
    const branchWarehouseIds = warehouses
      .filter(w => w.branchId === activeBranchId)
      .map(w => w.id);

    return products.map(p => {
      // 1. Calculate Stock for this branch
      const branchStock = p.warehouseInventory?.reduce((acc, inv) => {
        if (branchWarehouseIds.includes(inv.warehouseId)) {
          return acc + inv.quantity;
        }
        return acc;
      }, 0) || 0;

      // 2. Check for Branch Price override
      const branchPriceConfig = p.branchPrices?.find(bp => bp.branchId === activeBranchId);
      const effectivePrice = branchPriceConfig ? branchPriceConfig.price : p.price;

      return {
        ...p,
        stock: branchStock,
        price: effectivePrice
      };
    });
  }, [products, activeBranchId, warehouses]);

  // --- Calculations ---
  const customerLevel = useMemo(() => {
    if (!selectedCustomer?.levelId) return null;
    return customerLevels.find(l => l.id === selectedCustomer.levelId);
  }, [selectedCustomer, customerLevels]);

  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);

  // 1. Apply Discounts
  const customerDiscountPercent = customerLevel?.discountPercentage || 0;
  const customerDiscountAmount = customerDiscountPercent > 0 
    ? rawSubtotal * (customerDiscountPercent / 100) 
    : 0;

  let manualDiscountAmount = 0;
  if (manualDiscount) {
    if (manualDiscount.type === 'percent') {
      manualDiscountAmount = rawSubtotal * (manualDiscount.value / 100);
    } else {
      manualDiscountAmount = manualDiscount.value;
    }
  }

  const redeemRate = settings?.loyaltyProgram?.redeemRate || 100;
  const loyaltyDiscountAmount = redeemPoints > 0 ? redeemPoints / redeemRate : 0;

  let discountAmount = Math.min(customerDiscountAmount + manualDiscountAmount + loyaltyDiscountAmount, rawSubtotal);
  let discountedSubtotal = rawSubtotal - discountAmount;

  // 2. Apply Tax
  let taxAmount = 0;
  let finalTotal = discountedSubtotal;
  const taxConfig = settings?.tax;

  if (taxConfig && taxConfig.enabled) {
    const rate = taxConfig.rate / 100;
    if (taxConfig.calculationMode === 'excluded') {
       taxAmount = discountedSubtotal * rate;
       finalTotal = discountedSubtotal + taxAmount;
    } else {
       taxAmount = discountedSubtotal - (discountedSubtotal / (1 + rate));
       finalTotal = discountedSubtotal;
    }
  }

  // --- Broadcast Channel ---
  useEffect(() => {
    if (settings?.customerDisplay?.enabled) {
      const payload = {
        type: isCheckoutOpen ? 'CHECKOUT' : (cart.length === 0 ? 'RESET' : 'UPDATE'),
        cart,
        subtotal: rawSubtotal,
        discount: discountAmount,
        tax: taxAmount,
        total: finalTotal,
        customer: selectedCustomer,
        // paymentMethod and amountReceived would be passed during checkout updates if we sync live
        companyName: settings?.companyName,
        settings: settings?.customerDisplay
      };
      const channel = new BroadcastChannel('customer_display_channel');
      channel.postMessage(payload);
      return () => channel.close();
    }
  }, [cart, rawSubtotal, discountAmount, taxAmount, finalTotal, selectedCustomer, isCheckoutOpen, settings]);

  const handleOpenCustomerDisplay = () => {
    window.open('/customer-display', 'CustomerDisplay', 'width=1024,height=768,menubar=no,toolbar=no,location=no,status=no');
  };

  useEffect(() => {
     setRedeemPoints(0);
  }, [selectedCustomer]);

  // --- Handlers ---
  const performScan = (code: string) => {
    const mainMatch = branchProducts.find(p => p.barcode === code || p.sku === code);
    if (mainMatch) {
      addToCart(mainMatch, 1, undefined);
      setSearchTerm(''); 
      return;
    }
    for (const p of branchProducts) {
      if (p.variants) {
        const variantMatch = p.variants.find(v => v.barcode === code || v.code === code);
        if (variantMatch) {
          addToCart(p, 1, variantMatch.id);
          setSearchTerm('');
          return;
        }
      }
    }
    alert(`Product not found: ${code}`);
  };

  const handleAiItemsAdded = (items: EstimateResultItem[]) => {
    items.forEach(est => {
      if (est.matchedProductId) {
        const product = branchProducts.find(p => p.id === est.matchedProductId);
        if (product) addToCart(product, Math.ceil(est.estimatedQuantity), undefined);
      }
    });
  };

  const handleHoldOrder = () => {
    if (cart.length === 0) return;
    const note = prompt("Optional note for this hold:");
    holdCurrentOrder(selectedCustomer, note || undefined);
    setSelectedCustomer(null);
    setManualDiscount(null);
    setRedeemPoints(0);
  };

  const handleRecall = (orderId: string) => {
    const restored = recallOrder(orderId);
    if (restored) {
      setSelectedCustomer(restored.customer || null);
      setIsRecallModalOpen(false);
    }
  };

  const handleProcessPayment = async (
    method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    receivedAmount: number,
    change: number
  ) => {
    setIsProcessing(true);
    try {
      const sale = await onProcessSale(
        cart, finalTotal, selectedCustomer?.id, discountAmount, rawSubtotal,
        method, receivedAmount, change, redeemPoints
      );

      setLastSale(sale);
      setIsCheckoutOpen(false);
      clearCart();
      setManualDiscount(null); 
      setRedeemPoints(0);
      setSelectedCustomer(null);
      setIsReceiptOpen(true);
    } catch (error) {
      console.error("Sale failed", error);
      alert("Transaction failed. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);
  const barcodeList = useMemo(() => products.map(p => p.barcode).filter(Boolean), [products]);

  return (
    <div className="flex flex-col lg:flex-row h-full gap-6 relative">
      {/* Main Product Area */}
      <div className="flex-1 flex flex-col min-w-0 h-full">
        {/* Top Bar */}
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-4">
            <h2 className="text-2xl font-bold text-slate-800 hidden md:block">{t('pos.newOrder')}</h2>
          </div>

          <div className="flex space-x-2 w-full md:w-auto overflow-x-auto pb-1 md:pb-0">
             <button 
               onClick={() => setIsRecallModalOpen(true)}
               disabled={heldOrders.length === 0}
               className={`flex items-center px-3 py-2 rounded-lg text-sm font-medium border whitespace-nowrap ${
                 heldOrders.length > 0 ? 'bg-orange-50 text-orange-700 border-orange-200' : 'bg-white text-slate-400 border-slate-200 cursor-not-allowed'
               }`}
             >
               <ClipboardList className="w-4 h-4 mr-2" />
               Recall ({heldOrders.length})
             </button>
             {settings?.customerDisplay?.enabled && (
               <button onClick={handleOpenCustomerDisplay} className="flex items-center px-3 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 shadow-sm text-sm whitespace-nowrap">
                 <Monitor className="w-4 h-4 mr-2" /> Customer Screen
               </button>
             )}
             <button 
              onClick={() => setIsCustomerModalOpen(true)}
              className={`flex items-center px-3 py-2 rounded-lg shadow-sm font-medium text-sm border whitespace-nowrap ${
                selectedCustomer ? 'bg-blue-50 text-blue-700 border-blue-200' : 'bg-white text-slate-600 border-slate-200'
              }`}
            >
              <User className="w-4 h-4 mr-2" />
              {selectedCustomer ? selectedCustomer.name : t('pos.selectCustomer')}
            </button>
            <button onClick={() => setIsAiModalOpen(true)} className="flex items-center px-3 py-2 bg-gradient-to-r from-violet-600 to-indigo-600 text-white rounded-lg shadow-md hover:shadow-lg transition-all text-sm font-medium whitespace-nowrap">
              <Sparkles className="w-4 h-4 md:mr-2" /> <span className="hidden md:inline">{t('pos.aiEstimate')}</span>
            </button>
          </div>
        </div>

        <ProductGrid 
          products={branchProducts} 
          searchTerm={searchTerm}
          setSearchTerm={setSearchTerm}
          onScanClick={() => setIsScannerOpen(true)}
          onScan={performScan}
        />
      </div>

      {/* Mobile Cart Toggle */}
      {cartItemCount > 0 && (
        <button 
          onClick={() => setIsCartOpen(true)}
          className="lg:hidden fixed bottom-6 right-4 left-4 bg-slate-900 text-white p-4 rounded-xl shadow-xl flex justify-between items-center z-30"
        >
          <div className="flex items-center">
            <div className="bg-orange-500 rounded-full w-8 h-8 flex items-center justify-center font-bold text-xs mr-3">
              {cartItemCount}
            </div>
            <span className="font-bold">View Cart</span>
          </div>
          <span className="font-bold text-lg">${finalTotal.toFixed(2)}</span>
        </button>
      )}

      {/* Cart Sidebar */}
      <CartSidebar 
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        selectedCustomer={selectedCustomer}
        onRemoveCustomer={() => setSelectedCustomer(null)}
        onHoldOrder={handleHoldOrder}
        onCheckout={() => setIsCheckoutOpen(true)}
        onDiscountClick={() => setIsDiscountModalOpen(true)}
        subtotal={rawSubtotal}
        discount={discountAmount}
        tax={taxAmount}
        total={finalTotal}
        settings={settings}
      />

      {/* Modals */}
      <CheckoutModal 
        isOpen={isCheckoutOpen}
        onClose={() => setIsCheckoutOpen(false)}
        total={finalTotal}
        onProcessPayment={handleProcessPayment}
        selectedCustomer={selectedCustomer}
        isProcessing={isProcessing}
      />

      <ReceiptModal 
        isOpen={isReceiptOpen}
        onClose={() => setIsReceiptOpen(false)}
        sale={lastSale}
        settings={settings}
      />

      <CustomerModal 
        isOpen={isCustomerModalOpen}
        onClose={() => setIsCustomerModalOpen(false)}
        customers={customers}
        onSelectCustomer={(c) => { setSelectedCustomer(c); setIsCustomerModalOpen(false); }}
      />

      <DiscountModal 
        isOpen={isDiscountModalOpen}
        onClose={() => setIsDiscountModalOpen(false)}
        onApplyDiscount={setManualDiscount}
        currencySymbol={settings?.currencySymbol}
      />

      <RecallModal 
        isOpen={isRecallModalOpen}
        onClose={() => setIsRecallModalOpen(false)}
        heldOrders={heldOrders}
        onRecall={handleRecall}
        onDiscard={discardHeldOrder}
      />

      <AiAssistant 
        isOpen={isAiModalOpen} 
        onClose={() => setIsAiModalOpen(false)} 
        inventory={branchProducts} 
        onAddItemsToCart={handleAiItemsAdded} 
      />

      <BarcodeScanner 
        isOpen={isScannerOpen} 
        onClose={() => setIsScannerOpen(false)} 
        onScan={performScan} 
        dummyCodes={barcodeList as string[]} 
      />
    </div>
  );
};

import React, { useState } from 'react';
import { Customer } from '../../types';
import { X, Banknote, QrCode, CreditCard, FileText, ChevronLeft, CheckCircle } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';
import { PaymentMethodList } from './checkout/PaymentMethodList';
import { PaymentNumpad } from './checkout/PaymentNumpad';

interface CheckoutModalProps {
  isOpen: boolean;
  onClose: () => void;
  total: number;
  onProcessPayment: (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit', receivedAmount: number, change: number) => Promise<void>;
  selectedCustomer: Customer | null;
  isProcessing: boolean;
}

export const CheckoutModal: React.FC<CheckoutModalProps> = ({
  isOpen,
  onClose,
  total,
  onProcessPayment,
  selectedCustomer,
  isProcessing
}) => {
  const { formatPrice } = useGlobal();
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'qr' | 'credit'>('cash');
  const [receivedAmountStr, setReceivedAmountStr] = useState('');
  const [checkoutStep, setCheckoutStep] = useState<'method' | 'detail'>('method');

  if (!isOpen) return null;

  const receivedAmount = parseFloat(receivedAmountStr) || 0;
  const change = Math.max(0, receivedAmount - total);

  const selectPaymentMethod = (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit') => {
    if (method === 'credit' && !selectedCustomer) {
      alert("Credit payment requires a registered customer.");
      return;
    }
    setPaymentMethod(method);
    setReceivedAmountStr(''); // Reset for clean entry
    setCheckoutStep('detail');
  };

  const handleQuickCash = (amount: number) => {
    setReceivedAmountStr(amount.toString());
  };

  const handleProcess = () => {
    let finalReceived = paymentMethod === 'cash' || paymentMethod === 'credit' ? receivedAmount : total;
    let finalChange = paymentMethod === 'cash' ? change : 0;

    // Auto-fill exact amount for non-cash methods if not set (or for full credit if user enters nothing, though usually we want explicit 0)
    if (paymentMethod !== 'cash' && paymentMethod !== 'credit') {
        finalReceived = total;
    }

    onProcessPayment(paymentMethod, finalReceived, finalChange);
  };

  const getConfirmButtonText = () => {
    if (isProcessing) return 'Processing...';

    if (paymentMethod === 'cash') {
      if (receivedAmount < total) return `Enter Amount (Due: ${formatPrice(total)})`;
      if (change > 0) return `Confirm Pay & Return ${formatPrice(change)}`;
      return `Confirm Payment ${formatPrice(total)}`;
    }

    if (paymentMethod === 'credit') {
       const debt = Math.max(0, total - receivedAmount);
       if (receivedAmount > total) return `Amount exceeds total`;
       if (receivedAmount > 0) return `Pay Deposit ${formatPrice(receivedAmount)} (Debt: ${formatPrice(debt)})`;
       return `Confirm Full Credit (Debt: ${formatPrice(total)})`;
    }

    return `Confirm Payment ${formatPrice(total)}`;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/60 backdrop-blur-sm p-0 sm:p-4 animate-fade-in">
      <div className="bg-white w-full h-[90vh] sm:h-[650px] sm:max-w-5xl rounded-t-2xl sm:rounded-2xl shadow-2xl flex flex-col sm:flex-row overflow-hidden">

        {/* Method Selection Sidebar */}
        <PaymentMethodList 
            paymentMethod={paymentMethod}
            onSelect={selectPaymentMethod}
            onClose={onClose}
            total={total}
            selectedCustomer={selectedCustomer}
            className={checkoutStep === 'detail' ? 'hidden sm:flex' : 'flex'}
        />

        {/* Detail / Numpad Area */}
        <div className={`flex-1 bg-white flex flex-col ${checkoutStep === 'method' ? 'hidden sm:flex' : 'flex'} h-full`}>
           <div className="p-4 border-b border-slate-100 flex items-center justify-between sm:justify-end">
              <button onClick={() => setCheckoutStep('method')} className="sm:hidden flex items-center text-slate-500 font-medium hover:text-slate-800">
                 <ChevronLeft className="w-5 h-5 mr-1" /> Back
              </button>
              <button onClick={onClose} className="hidden sm:block p-2 hover:bg-slate-100 rounded-full text-slate-400">
                 <X className="w-6 h-6" />
              </button>
           </div>

           <div className="flex-1 p-4 sm:p-8 overflow-y-auto">
              <div className="text-center mb-6">
                 <h3 className="text-xl font-bold text-slate-800 flex items-center justify-center gap-2">
                    {paymentMethod === 'cash' ? <Banknote className="text-blue-600"/> : paymentMethod === 'qr' ? <QrCode className="text-blue-600"/> : paymentMethod === 'credit' ? <FileText className="text-orange-500"/> : <CreditCard className="text-blue-600"/>}
                    {paymentMethod === 'cash' ? 'Cash Payment' : paymentMethod === 'qr' ? 'Scan to Pay' : paymentMethod === 'credit' ? 'Credit / Debt Sale' : 'Digital Payment'}
                 </h3>
              </div>

              {/* Show Numpad for Cash OR Credit */}
              {paymentMethod === 'cash' || paymentMethod === 'credit' ? (
                 <PaymentNumpad 
                    receivedAmountStr={receivedAmountStr}
                    setReceivedAmountStr={setReceivedAmountStr}
                    total={total}
                    change={paymentMethod === 'cash' ? change : 0} // No change for credit usually, just reduced debt
                    handleQuickCash={handleQuickCash}
                 />
              ) : paymentMethod === 'qr' ? (
                 <div className="flex-1 flex flex-col items-center justify-center">
                    <div className="bg-white p-6 rounded-3xl border-2 border-slate-100 shadow-lg mb-6">
                       <img src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=Payment_OnePay_${total}`} className="w-64 h-64 object-contain" alt="QR" />
                    </div>
                    <p className="text-lg font-bold text-slate-700">Scan to pay {formatPrice(total)}</p>
                 </div>
              ) : (
                 <div className="flex-1 flex flex-col items-center justify-center text-center">
                    <div className="w-32 h-32 bg-slate-100 rounded-full flex items-center justify-center mb-6 animate-pulse">
                       <CreditCard className="w-16 h-16 text-blue-500" />
                    </div>
                    <h4 className="text-xl font-bold text-slate-800 mb-2">
                       Waiting for Terminal
                    </h4>
                    <p className="text-slate-500">Total amount: <strong>{formatPrice(total)}</strong></p>
                 </div>
              )}
           </div>
           <div className="p-4 border-t border-slate-100 bg-white">
              <button 
                 onClick={handleProcess}
                 disabled={isProcessing || (paymentMethod === 'cash' && receivedAmount < total) || (paymentMethod === 'credit' && receivedAmount > total)}
                 className={`w-full py-4 rounded-xl font-bold text-xl text-white shadow-lg flex items-center justify-center transition-all active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed ${paymentMethod === 'credit' ? 'bg-orange-600' : 'bg-slate-900 hover:bg-slate-800'}`}
              >
                 {isProcessing ? 'Processing...' : (
                    <>
                       <CheckCircle className="w-6 h-6 mr-2" /> 
                       {getConfirmButtonText()}
                    </>
                 )}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Sale, SystemSettings } from '../../types';
import { XCircle, RotateCcw, Wallet, DollarSign, Reply, Ban, Printer, CheckCircle, CreditCard, Banknote, QrCode } from 'lucide-react';
import { PrintableReceipt } from '../shared/PrintableReceipt';

interface SaleDetailModalProps {
  sale: Sale | null;
  isOpen: boolean;
  onClose: () => void;
  onVoid: () => void;
  onSettleDebt: (amount: number, method: string) => Promise<void>;
  onReturn: (items: { itemIndex: number, quantity: number }[]) => Promise<void>;
  settings?: SystemSettings;
  formatPrice: (amount: number) => string;
  isAdminOrManager: boolean;
}

export const SaleDetailModal: React.FC<SaleDetailModalProps> = ({ 
  sale, isOpen, onClose, onVoid, onSettleDebt, onReturn, settings, formatPrice, isAdminOrManager 
}) => {
  const [isReturnMode, setIsReturnMode] = useState(false);
  const [isSettleMode, setIsSettleMode] = useState(false);
  const [returnQuantities, setReturnQuantities] = useState<Record<number, number>>({});

  // Settle Debt State
  const [settleAmountStr, setSettleAmountStr] = useState('');
  const [settleMethod, setSettleMethod] = useState<'cash' | 'transfer' | 'qr'>('cash');

  if (!isOpen || !sale) return null;

  const handleReturnQtyChange = (index: number, qty: number) => {
    const max = sale.items[index].quantity || 0;
    const val = Math.min(Math.max(0, qty), max);
    setReturnQuantities(prev => ({ ...prev, [index]: val }));
  };

  const calculateReturnTotal = () => {
    return sale.items.reduce((acc, item, index) => {
      const qty = returnQuantities[index] || 0;
      return acc + (item.sellPrice * qty);
    }, 0);
  };

  const handleSubmitReturn = async () => {
    const itemsToReturn = Object.entries(returnQuantities)
      .filter(([_, qty]) => (qty as number) > 0)
      .map(([index, quantity]) => ({ itemIndex: parseInt(index), quantity: quantity as number }));

    if (itemsToReturn.length === 0) {
      alert("Please select at least one item to return.");
      return;
    }

    if (confirm(`Confirm refund of ${formatPrice(calculateReturnTotal())}? This will restore stock.`)) {
      await onReturn(itemsToReturn);
      setIsReturnMode(false);
      setReturnQuantities({});
      onClose();
    }
  };

  const toggleReturnMode = () => {
    setIsReturnMode(!isReturnMode);
    setReturnQuantities({});
    setIsSettleMode(false);
  };

  const toggleSettleMode = () => {
    setIsSettleMode(!isSettleMode);
    setSettleAmountStr((sale.remainingAmount || sale.total).toString());
    setIsReturnMode(false);
  };

  const handleSettleSubmit = async () => {
     const amount = parseFloat(settleAmountStr);
     const debt = sale.remainingAmount || sale.total;

     if (isNaN(amount) || amount <= 0) {
        alert("Please enter a valid amount.");
        return;
     }

     if (amount > debt) {
        alert("Amount cannot exceed total debt.");
        return;
     }

     await onSettleDebt(amount, settleMethod);
     setIsSettleMode(false);
     // Note: Parent usually updates the 'sale' prop or closes modal, 
     // but we assume parent handles state update if we stay open or close.
     onClose();
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4 print:p-0 print:bg-white print:static print:block">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg max-h-[90vh] flex flex-col print:shadow-none print:max-w-none print:max-h-none print:rounded-none">

        {/* Modal Header - Hidden on Print */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl print:hidden">
          <div>
             <h3 className="text-xl font-bold text-slate-800">
                {isReturnMode ? 'Select Items to Return' : isSettleMode ? 'Settle Outstanding Debt' : 'Invoice Details'}
             </h3>
             <p className="text-sm text-slate-500 font-mono">#{sale.id}</p>
          </div>
          <div className="flex items-center space-x-2">
             {sale.status === 'voided' && (
                <span className="px-3 py-1 bg-red-100 text-red-700 rounded-full text-xs font-bold uppercase tracking-wide flex items-center">
                   <RotateCcw className="w-3 h-3 mr-1" /> Stock Restored
                </span>
             )}
             <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
               <XCircle className="w-6 h-6" />
             </button>
          </div>
        </div>

        {/* Screen View */}
        <div className="p-6 overflow-y-auto flex-1 print:hidden">

           {/* Normal View Header Info */}
           {!isReturnMode && !isSettleMode && (
              <div className="flex justify-between mb-4 text-sm">
                 <div className="text-slate-500">
                    <p>Date: <span className="font-medium text-slate-700">{new Date(sale.date).toLocaleString()}</span></p>
                    <p>Customer: <span className="font-medium text-slate-700">{sale.customerName || 'Walk-in'}</span></p>
                 </div>
                 <div className="text-right text-slate-500">
                    <p>Method: <span className="font-medium text-slate-700 capitalize">{sale.paymentMethod}</span></p>
                    <p>Status: <span className={`font-bold capitalize ${sale.paymentStatus === 'paid' ? 'text-green-600' : 'text-orange-600'}`}>{sale.paymentStatus || 'Paid'}</span></p>
                 </div>
              </div>
           )}

           {/* SETTLE DEBT MODE */}
           {isSettleMode ? (
              <div className="space-y-6">
                 <div className="bg-orange-50 p-4 rounded-xl border border-orange-100 text-center">
                    <p className="text-sm text-orange-600 font-bold uppercase tracking-wider mb-1">Total Outstanding</p>
                    <p className="text-3xl font-bold text-orange-800">{formatPrice(sale.remainingAmount || sale.total)}</p>
                 </div>

                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-2">Payment Amount</label>
                    <div className="relative">
                       <DollarSign className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                       <input 
                          type="number"
                          value={settleAmountStr}
                          onChange={(e) => setSettleAmountStr(e.target.value)}
                          className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-xl focus:ring-2 focus:ring-green-500 text-lg font-bold"
                          placeholder="0.00"
                          autoFocus
                       />
                    </div>
                 </div>

                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-2">Payment Method</label>
                    <div className="grid grid-cols-3 gap-3">
                       <button 
                          onClick={() => setSettleMethod('cash')}
                          className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all ${settleMethod === 'cash' ? 'bg-blue-50 border-blue-500 text-blue-700' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
                       >
                          <Banknote className="w-6 h-6 mb-1" />
                          <span className="text-xs font-bold">Cash</span>
                       </button>
                       <button 
                          onClick={() => setSettleMethod('transfer')}
                          className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all ${settleMethod === 'transfer' ? 'bg-blue-50 border-blue-500 text-blue-700' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
                       >
                          <CreditCard className="w-6 h-6 mb-1" />
                          <span className="text-xs font-bold">Transfer</span>
                       </button>
                       <button 
                          onClick={() => setSettleMethod('qr')}
                          className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all ${settleMethod === 'qr' ? 'bg-blue-50 border-blue-500 text-blue-700' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
                       >
                          <QrCode className="w-6 h-6 mb-1" />
                          <span className="text-xs font-bold">QR / App</span>
                       </button>
                    </div>
                 </div>
              </div>
           ) : (
              // DEFAULT / RETURN VIEW
              <div className="border rounded-lg overflow-hidden mb-6">
                 <table className="w-full text-sm">
                    <thead className="bg-slate-50 text-slate-500">
                       <tr>
                          {isReturnMode && <th className="px-4 py-2 w-16">Return</th>}
                          <th className="px-4 py-2 text-left">Item</th>
                          <th className="px-4 py-2 text-right">Qty</th>
                          <th className="px-4 py-2 text-right">Price</th>
                          <th className="px-4 py-2 text-right">Total</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {sale.items.map((item, idx) => (
                          <tr key={idx} className={returnQuantities[idx] > 0 ? 'bg-red-50' : ''}>
                             {isReturnMode && (
                                <td className="px-4 py-2">
                                   <input 
                                      type="number" 
                                      min="0" 
                                      max={item.quantity}
                                      value={returnQuantities[idx] || 0}
                                      onChange={(e) => handleReturnQtyChange(idx, parseInt(e.target.value) || 0)}
                                      className="w-16 border rounded p-1 text-center font-bold"
                                   />
                                </td>
                             )}
                             <td className="px-4 py-2">
                                <div className="font-medium text-slate-800">{item.name}</div>
                                {item.selectedVariantId && <div className="text-xs text-slate-400">Variant</div>}
                             </td>
                             <td className="px-4 py-2 text-right">{item.quantity}</td>
                             <td className="px-4 py-2 text-right">{formatPrice(item.sellPrice)}</td>
                             <td className="px-4 py-2 text-right font-bold">{formatPrice(item.sellPrice * item.quantity)}</td>
                          </tr>
                       ))}
                    </tbody>
                    <tfoot className="bg-slate-50 font-bold text-slate-800">
                       {!isReturnMode ? (
                          <>
                             <tr>
                                <td colSpan={3} className="px-4 py-3 text-right">Subtotal</td>
                                <td className="px-4 py-3 text-right">{formatPrice(sale.subtotal || sale.total)}</td>
                             </tr>
                             {sale.discountAmount && sale.discountAmount > 0 && (
                                <tr className="text-green-600">
                                   <td colSpan={3} className="px-4 py-1 text-right">Discount</td>
                                   <td className="px-4 py-1 text-right">-{formatPrice(sale.discountAmount)}</td>
                                </tr>
                             )}
                             <tr className="border-t border-slate-200">
                                <td colSpan={3} className="px-4 py-3 text-right text-lg">Grand Total</td>
                                <td className="px-4 py-3 text-right text-lg">{formatPrice(Math.abs(sale.total))}</td>
                             </tr>
                          </>
                       ) : (
                          <tr className="bg-red-50 text-red-700 border-t border-red-200">
                             <td colSpan={4} className="px-4 py-3 text-right text-lg">Refund Total</td>
                             <td className="px-4 py-3 text-right text-lg">{formatPrice(calculateReturnTotal())}</td>
                          </tr>
                       )}
                    </tfoot>
                 </table>
              </div>
           )}

           {/* Actions in Modal (Screen Only) */}
           {!isReturnMode && !isSettleMode && (
              <>
                 {(sale.paymentStatus === 'unpaid' || sale.paymentStatus === 'partial') && sale.status !== 'voided' && (
                    <div className="mb-4 bg-orange-50 p-4 rounded-lg border border-orange-200">
                       <h4 className="font-bold text-orange-800 text-sm mb-2 flex items-center">
                          <Wallet className="w-4 h-4 mr-2" /> 
                          Outstanding Payment
                       </h4>
                       <p className="text-xs text-orange-700 mb-3">
                          This invoice has an outstanding balance of <span className="font-bold">{formatPrice(sale.remainingAmount || 0)}</span>.
                       </p>
                       <button
                          onClick={toggleSettleMode}
                          className="w-full py-2 bg-slate-800 text-white rounded-lg text-sm font-bold hover:bg-slate-900 shadow-sm flex items-center justify-center"
                       >
                          <DollarSign className="w-4 h-4 mr-1" />
                          Settle Debt
                       </button>
                    </div>
                 )}

                 {sale.status !== 'voided' && sale.type !== 'return' && isAdminOrManager && (
                    <div className="grid grid-cols-2 gap-4">
                       <button 
                          onClick={toggleReturnMode}
                          className="py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-xs font-bold uppercase tracking-wide hover:bg-slate-50 shadow-sm flex items-center justify-center"
                       >
                          <Reply className="w-4 h-4 mr-2" /> Return / Refund
                       </button>
                       <button 
                          onClick={onVoid}
                          className="py-2 bg-red-600 text-white rounded-lg text-xs font-bold uppercase tracking-wide hover:bg-red-700 shadow-sm flex items-center justify-center"
                       >
                          <Ban className="w-4 h-4 mr-2" /> Void Transaction
                       </button>
                    </div>
                 )}
              </>
           )}
        </div>

        {/* --- PRINTABLE RECEIPT SECTION (Visible only in Print) --- */}
        <div className="hidden print:block">
           <PrintableReceipt sale={sale} settings={settings} isReprint={true} />
        </div>

        {/* Modal Footer - Hidden on Print */}
        <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-slate-50 rounded-b-xl print:hidden">
           {isReturnMode ? (
              <>
                 <button 
                    onClick={toggleReturnMode}
                    className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50"
                 >
                    Cancel Return
                 </button>
                 <button 
                    onClick={handleSubmitReturn}
                    className="px-6 py-2 bg-red-600 text-white font-bold rounded-lg hover:bg-red-700 shadow-sm"
                 >
                    Confirm Refund
                 </button>
              </>
           ) : isSettleMode ? (
              <>
                 <button 
                    onClick={toggleSettleMode}
                    className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50"
                 >
                    Cancel
                 </button>
                 <button 
                    onClick={handleSettleSubmit}
                    className="px-6 py-2 bg-green-600 text-white font-bold rounded-lg hover:bg-green-700 shadow-sm flex items-center"
                 >
                    <CheckCircle className="w-4 h-4 mr-2" />
                    Confirm Payment
                 </button>
              </>
           ) : (
              <>
                 <button 
                    onClick={handlePrint}
                    className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50 flex items-center shadow-sm"
                 >
                    <Printer className="w-4 h-4 mr-2" />
                    Reprint Bill
                 </button>
                 <button 
                    onClick={onClose}
                    className="px-4 py-2 bg-slate-800 text-white font-medium rounded-lg hover:bg-slate-900"
                 >
                    Close
                 </button>
              </>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Sale } from '../types';
import { Search, Receipt } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { SalesList } from './sales/SalesList';
import { SaleDetailModal } from './sales/SaleDetailModal';

interface SalesHistoryProps {
  sales: Sale[];
  onVoidSale: (id: string) => void;
}

export const SalesHistory: React.FC<SalesHistoryProps> = ({ sales = [], onVoidSale }) => {
  const { currentUser, settleSaleDebt, processReturn, settings, formatPrice } = useGlobal();

  const [searchTerm, setSearchTerm] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'completed' | 'voided' | 'unpaid'>('all');

  // Modal States
  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);

  const safeSales = sales || [];

  const filteredSales = useMemo(() => {
    return safeSales.filter(sale => {
      const matchesSearch = 
        sale.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (sale.customerName && sale.customerName.toLowerCase().includes(searchTerm.toLowerCase()));

      let matchesStatus = true;
      if (statusFilter === 'completed') matchesStatus = sale.status === 'completed' && sale.paymentStatus === 'paid';
      else if (statusFilter === 'unpaid') matchesStatus = sale.paymentStatus === 'unpaid' || sale.paymentStatus === 'partial';
      else if (statusFilter === 'voided') matchesStatus = sale.status === 'voided';

      let matchesDate = true;
      if (startDate) {
        matchesDate = matchesDate && new Date(sale.date) >= new Date(startDate);
      }
      if (endDate) {
        const end = new Date(endDate);
        end.setHours(23, 59, 59, 999);
        matchesDate = matchesDate && new Date(sale.date) <= end;
      }

      return matchesSearch && matchesStatus && matchesDate;
    });
  }, [safeSales, searchTerm, startDate, endDate, statusFilter]);

  const handleVoid = () => {
    if (!selectedSale) return;
    if (confirm(`Are you sure you want to VOID Sale #${selectedSale.id}? This will restore items to stock automatically.`)) {
      onVoidSale(selectedSale.id);
      setSelectedSale(null);
    }
  };

  const handleSettleDebt = async (amount: number, method: string) => {
    if (!selectedSale) return;

    await settleSaleDebt(selectedSale.id, amount, method);

    // Update the selected sale object locally to reflect changes immediately in the modal
    setSelectedSale(prev => {
        if (!prev) return null;
        const newPaid = (prev.amountReceived || 0) + amount;
        const newRemaining = Math.max(0, (prev.remainingAmount || prev.total) - amount);
        return {
            ...prev, 
            amountReceived: newPaid, 
            remainingAmount: newRemaining,
            paymentStatus: newRemaining <= 0.01 ? 'paid' : 'partial'
        };
    });
  };

  const isAdminOrManager = currentUser?.role === 'Admin' || currentUser?.role === 'Manager';

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center print:hidden">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Sales History</h2>
          <p className="text-slate-500">Manage invoices, credit sales, and void transactions.</p>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4 items-end print:hidden">
        <div className="flex-1 w-full">
           <label className="block text-xs font-medium text-slate-500 mb-1">Search</label>
           <div className="relative">
              <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
              <input
                type="text"
                placeholder="Invoice ID or Customer Name"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
              />
           </div>
        </div>

        <div>
           <label className="block text-xs font-medium text-slate-500 mb-1">Start Date</label>
           <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500" />
        </div>
        <div>
           <label className="block text-xs font-medium text-slate-500 mb-1">End Date</label>
           <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500" />
        </div>

        <div>
           <label className="block text-xs font-medium text-slate-500 mb-1">Status</label>
           <select
             value={statusFilter}
             onChange={e => setStatusFilter(e.target.value as any)}
             className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-white min-w-[120px]"
           >
             <option value="all">All Status</option>
             <option value="completed">Paid / Completed</option>
             <option value="unpaid">Unpaid / Credit</option>
             <option value="voided">Voided</option>
           </select>
        </div>
      </div>

      <SalesList 
        sales={filteredSales} 
        formatPrice={formatPrice} 
        onViewSale={setSelectedSale} 
      />

      <SaleDetailModal 
        sale={selectedSale}
        isOpen={!!selectedSale}
        onClose={() => setSelectedSale(null)}
        onVoid={handleVoid}
        onSettleDebt={handleSettleDebt}
        onReturn={processReturn.bind(null, selectedSale!)} 
        settings={settings}
        formatPrice={formatPrice}
        isAdminOrManager={isAdminOrManager}
      />
    </div>
  );
};

import React, { useState } from 'react';
import { Sale, SystemSettings } from '../../types';
import { XCircle, RotateCcw, Wallet, DollarSign, Reply, Ban, Printer, CheckCircle, CreditCard, Banknote, QrCode } from 'lucide-react';
import { PrintableReceipt } from '../shared/PrintableReceipt';

interface SaleDetailModalProps {
  sale: Sale | null;
  isOpen: boolean;
  onClose: () => void;
  onVoid: () => void;
  onSettleDebt: (amount: number, method: string) => Promise<void>;
  onReturn: (items: { itemIndex: number, quantity: number }[]) => Promise<void>;
  settings?: SystemSettings;
  formatPrice: (amount: number) => string;
  isAdminOrManager: boolean;
}

export const SaleDetailModal: React.FC<SaleDetailModalProps> = ({ 
  sale, isOpen, onClose, onVoid, onSettleDebt, onReturn, settings, formatPrice, isAdminOrManager 
}) => {
  const [isReturnMode, setIsReturnMode] = useState(false);
  const [isSettleMode, setIsSettleMode] = useState(false);
  const [returnQuantities, setReturnQuantities] = useState<Record<number, number>>({});

  // Settle Debt State
  const [settleAmountStr, setSettleAmountStr] = useState('');
  const [settleMethod, setSettleMethod] = useState<'cash' | 'transfer' | 'qr'>('cash');

  if (!isOpen || !sale) return null;

  const handleReturnQtyChange = (index: number, qty: number) => {
    const max = sale.items[index].quantity || 0;
    const val = Math.min(Math.max(0, qty), max);
    setReturnQuantities(prev => ({ ...prev, [index]: val }));
  };

  const calculateReturnTotal = () => {
    return sale.items.reduce((acc, item, index) => {
      const qty = returnQuantities[index] || 0;
      return acc + (item.sellPrice * qty);
    }, 0);
  };

  const handleSubmitReturn = async () => {
    const itemsToReturn = Object.entries(returnQuantities)
      .filter(([_, qty]) => (qty as number) > 0)
      .map(([index, quantity]) => ({ itemIndex: parseInt(index), quantity: quantity as number }));

    if (itemsToReturn.length === 0) {
      alert("Please select at least one item to return.");
      return;
    }

    if (confirm(`Confirm refund of ${formatPrice(calculateReturnTotal())}? This will restore stock.`)) {
      await onReturn(itemsToReturn);
      setIsReturnMode(false);
      setReturnQuantities({});
      onClose();
    }
  };

  const toggleReturnMode = () => {
    setIsReturnMode(!isReturnMode);
    setReturnQuantities({});
    setIsSettleMode(false);
  };

  const toggleSettleMode = () => {
    setIsSettleMode(!isSettleMode);
    setSettleAmountStr((sale.remainingAmount || sale.total).toString());
    setIsReturnMode(false);
  };

  const handleSettleSubmit = async () => {
     const amount = parseFloat(settleAmountStr);
     const debt = sale.remainingAmount || sale.total;

     if (isNaN(amount) || amount <= 0) {
        alert("Please enter a valid amount.");
        return;
     }

     if (amount > debt) {
        alert("Amount cannot exceed total debt.");
        return;
     }

     await onSettleDebt(amount, settleMethod);
     setIsSettleMode(false);
     // Note: Parent usually updates the 'sale' prop or closes modal, 
     // but we assume parent handles state update if we stay open or close.
     onClose();
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4 print:p-0 print:bg-white print:static print:block">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg max-h-[90vh] flex flex-col print:shadow-none print:max-w-none print:max-h-none print:rounded-none">

        {/* Modal Header - Hidden on Print */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl print:hidden">
          <div>
             <h3 className="text-xl font-bold text-slate-800">
                {isReturnMode ? 'Select Items to Return' : isSettleMode ? 'Settle Outstanding Debt' : 'Invoice Details'}
             </h3>
             <p className="text-sm text-slate-500 font-mono">#{sale.id}</p>
          </div>
          <div className="flex items-center space-x-2">
             {sale.status === 'voided' && (
                <span className="px-3 py-1 bg-red-100 text-red-700 rounded-full text-xs font-bold uppercase tracking-wide flex items-center">
                   <RotateCcw className="w-3 h-3 mr-1" /> Stock Restored
                </span>
             )}
             <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
               <XCircle className="w-6 h-6" />
             </button>
          </div>
        </div>

        {/* Screen View */}
        <div className="p-6 overflow-y-auto flex-1 print:hidden">

           {/* Normal View Header Info */}
           {!isReturnMode && !isSettleMode && (
              <div className="flex justify-between mb-4 text-sm">
                 <div className="text-slate-500">
                    <p>Date: <span className="font-medium text-slate-700">{new Date(sale.date).toLocaleString()}</span></p>
                    <p>Customer: <span className="font-medium text-slate-700">{sale.customerName || 'Walk-in'}</span></p>
                 </div>
                 <div className="text-right text-slate-500">
                    <p>Method: <span className="font-medium text-slate-700 capitalize">{sale.paymentMethod}</span></p>
                    <p>Status: <span className={`font-bold capitalize ${sale.paymentStatus === 'paid' ? 'text-green-600' : 'text-orange-600'}`}>{sale.paymentStatus || 'Paid'}</span></p>
                 </div>
              </div>
           )}

           {/* SETTLE DEBT MODE */}
           {isSettleMode ? (
              <div className="space-y-6">
                 <div className="bg-orange-50 p-4 rounded-xl border border-orange-100 text-center">
                    <p className="text-sm text-orange-600 font-bold uppercase tracking-wider mb-1">Total Outstanding</p>
                    <p className="text-3xl font-bold text-orange-800">{formatPrice(sale.remainingAmount || sale.total)}</p>
                 </div>

                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-2">Payment Amount</label>
                    <div className="relative">
                       <DollarSign className="absolute left-3 top-3 w-5 h-5 text-slate-400" />
                       <input 
                          type="number"
                          value={settleAmountStr}
                          onChange={(e) => setSettleAmountStr(e.target.value)}
                          className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-xl focus:ring-2 focus:ring-green-500 text-lg font-bold"
                          placeholder="0.00"
                          autoFocus
                       />
                    </div>
                 </div>

                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-2">Payment Method</label>
                    <div className="grid grid-cols-3 gap-3">
                       <button 
                          onClick={() => setSettleMethod('cash')}
                          className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all ${settleMethod === 'cash' ? 'bg-blue-50 border-blue-500 text-blue-700' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
                       >
                          <Banknote className="w-6 h-6 mb-1" />
                          <span className="text-xs font-bold">Cash</span>
                       </button>
                       <button 
                          onClick={() => setSettleMethod('transfer')}
                          className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all ${settleMethod === 'transfer' ? 'bg-blue-50 border-blue-500 text-blue-700' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
                       >
                          <CreditCard className="w-6 h-6 mb-1" />
                          <span className="text-xs font-bold">Transfer</span>
                       </button>
                       <button 
                          onClick={() => setSettleMethod('qr')}
                          className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all ${settleMethod === 'qr' ? 'bg-blue-50 border-blue-500 text-blue-700' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
                       >
                          <QrCode className="w-6 h-6 mb-1" />
                          <span className="text-xs font-bold">QR / App</span>
                       </button>
                    </div>
                 </div>
              </div>
           ) : (
              // DEFAULT / RETURN VIEW
              <div className="border rounded-lg overflow-hidden mb-6">
                 <table className="w-full text-sm">
                    <thead className="bg-slate-50 text-black font-bold">
                       <tr>
                          {isReturnMode && <th className="px-4 py-2 w-16 text-black">Return</th>}
                          <th className="px-4 py-2 text-left text-black">Item</th>
                          <th className="px-4 py-2 text-right text-black">Qty</th>
                          <th className="px-4 py-2 text-right text-black">Price</th>
                          <th className="px-4 py-2 text-right text-black">Total</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {sale.items.map((item, idx) => (
                          <tr key={idx} className={returnQuantities[idx] > 0 ? 'bg-red-50' : ''}>
                             {isReturnMode && (
                                <td className="px-4 py-2">
                                   <input 
                                      type="number" 
                                      min="0" 
                                      max={item.quantity}
                                      value={returnQuantities[idx] || 0}
                                      onChange={(e) => handleReturnQtyChange(idx, parseInt(e.target.value) || 0)}
                                      className="w-16 border rounded p-1 text-center font-bold"
                                   />
                                </td>
                             )}
                             <td className="px-4 py-2">
                                <div className="font-medium text-slate-800">{item.name}</div>
                                {item.selectedVariantId && <div className="text-xs text-slate-400">Variant</div>}
                             </td>
                             <td className="px-4 py-2 text-right">{item.quantity}</td>
                             <td className="px-4 py-2 text-right">{formatPrice(item.sellPrice)}</td>
                             <td className="px-4 py-2 text-right font-bold">{formatPrice(item.sellPrice * item.quantity)}</td>
                          </tr>
                       ))}
                    </tbody>
                    <tfoot className="bg-slate-50 font-bold text-slate-800">
                       {!isReturnMode ? (
                          <>
                             <tr>
                                <td colSpan={3} className="px-4 py-3 text-right">Subtotal</td>
                                <td className="px-4 py-3 text-right">{formatPrice(sale.subtotal || sale.total)}</td>
                             </tr>
                             {sale.discountAmount && sale.discountAmount > 0 && (
                                <tr className="text-green-600">
                                   <td colSpan={3} className="px-4 py-1 text-right">Discount</td>
                                   <td className="px-4 py-1 text-right">-{formatPrice(sale.discountAmount)}</td>
                                </tr>
                             )}
                             <tr className="border-t border-slate-200">
                                <td colSpan={3} className="px-4 py-3 text-right text-lg">Grand Total</td>
                                <td className="px-4 py-3 text-right text-lg">{formatPrice(Math.abs(sale.total))}</td>
                             </tr>
                          </>
                       ) : (
                          <tr className="bg-red-50 text-red-700 border-t border-red-200">
                             <td colSpan={4} className="px-4 py-3 text-right text-lg">Refund Total</td>
                             <td className="px-4 py-3 text-right text-lg">{formatPrice(calculateReturnTotal())}</td>
                          </tr>
                       )}
                    </tfoot>
                 </table>
              </div>
           )}

           {/* Actions in Modal (Screen Only) */}
           {!isReturnMode && !isSettleMode && (
              <>
                 {(sale.paymentStatus === 'unpaid' || sale.paymentStatus === 'partial') && sale.status !== 'voided' && (
                    <div className="mb-4 bg-orange-50 p-4 rounded-lg border border-orange-200">
                       <h4 className="font-bold text-orange-800 text-sm mb-2 flex items-center">
                          <Wallet className="w-4 h-4 mr-2" /> 
                          Outstanding Payment
                       </h4>
                       <p className="text-xs text-orange-700 mb-3">
                          This invoice has an outstanding balance of <span className="font-bold">{formatPrice(sale.remainingAmount || 0)}</span>.
                       </p>
                       <button
                          onClick={toggleSettleMode}
                          className="w-full py-2 bg-slate-800 text-white rounded-lg text-sm font-bold hover:bg-slate-900 shadow-sm flex items-center justify-center"
                       >
                          <DollarSign className="w-4 h-4 mr-1" />
                          Settle Debt
                       </button>
                    </div>
                 )}

                 {sale.status !== 'voided' && sale.type !== 'return' && isAdminOrManager && (
                    <div className="grid grid-cols-2 gap-4">
                       <button 
                          onClick={toggleReturnMode}
                          className="py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-xs font-bold uppercase tracking-wide hover:bg-slate-50 shadow-sm flex items-center justify-center"
                       >
                          <Reply className="w-4 h-4 mr-2" /> Return / Refund
                       </button>
                       <button 
                          onClick={onVoid}
                          className="py-2 bg-red-600 text-white rounded-lg text-xs font-bold uppercase tracking-wide hover:bg-red-700 shadow-sm flex items-center justify-center"
                       >
                          <Ban className="w-4 h-4 mr-2" /> Void Transaction
                       </button>
                    </div>
                 )}
              </>
           )}
        </div>

        {/* --- PRINTABLE RECEIPT SECTION (Visible only in Print) --- */}
        <div className="hidden print:block">
           <PrintableReceipt sale={sale} settings={settings} isReprint={true} />
        </div>

        {/* Modal Footer - Hidden on Print */}
        <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-slate-50 rounded-b-xl print:hidden">
           {isReturnMode ? (
              <>
                 <button 
                    onClick={toggleReturnMode}
                    className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50"
                 >
                    Cancel Return
                 </button>
                 <button 
                    onClick={handleSubmitReturn}
                    className="px-6 py-2 bg-red-600 text-white font-bold rounded-lg hover:bg-red-700 shadow-sm"
                 >
                    Confirm Refund
                 </button>
              </>
           ) : isSettleMode ? (
              <>
                 <button 
                    onClick={toggleSettleMode}
                    className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50"
                 >
                    Cancel
                 </button>
                 <button 
                    onClick={handleSettleSubmit}
                    className="px-6 py-2 bg-green-600 text-white font-bold rounded-lg hover:bg-green-700 shadow-sm flex items-center"
                 >
                    <CheckCircle className="w-4 h-4 mr-2" />
                    Confirm Payment
                 </button>
              </>
           ) : (
              <>
                 <button 
                    onClick={handlePrint}
                    className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50 flex items-center shadow-sm"
                 >
                    <Printer className="w-4 h-4 mr-2" />
                    Reprint Bill
                 </button>
                 <button 
                    onClick={onClose}
                    className="px-4 py-2 bg-slate-800 text-white font-medium rounded-lg hover:bg-slate-900"
                 >
                    Close
                 </button>
              </>
           )}
        </div>
      </div>
    </div>
  );
};
